        public static void InspectSplatAnimationCandidatesIter588()
        {
            var actions = new[] { "Idle", "Run", "Jump", "Land" };
            for (var i = 0; i < actions.Length; i++)
            {
                var path = $"Assets/SpaceAndCrafts/Art/Animations/Authoring/Iter588/Splat_{actions[i]}_Iter588.fbx";
                var assets = AssetDatabase.LoadAllAssetsAtPath(path);
                var found = false;
                for (var j = 0; j < assets.Length; j++)
                {
                    if (!(assets[j] is AnimationClip clip)) continue;
                    found = true;
                    var bindings = AnimationUtility.GetCurveBindings(clip);
                    var firstBinding = bindings.Length > 0
                        ? $"{bindings[0].path}:{bindings[0].propertyName}"
                        : "humanoid/no transform binding";
                    Debug.Log($"[Splat animation import] action={actions[i]}, clip={clip.name}, length={clip.length:F2}s, fps={clip.frameRate:F0}, legacy={clip.legacy}, bindings={bindings.Length}, first={firstBinding}.");
                }

                if (!found) Debug.LogWarning($"[Splat animation import] No AnimationClip subasset found in {path}.");
            }

            EditorApplication.Exit(0);
        }

        public static void AuditSplatBlendActionsIter910()
        {
            var paths = new[]
            {
                "Assets/SpaceAndCrafts/Art/Animations/Authoring/Iter850/Splat_Animations_Iter850.blend",
                "Assets/SpaceAndCrafts/Art/Characters/Splat/Splat_Rigged.blend",
                "Assets/SpaceAndCrafts/Resources/Characters/Splat_Rigged.fbx",
                "Assets/SpaceAndCrafts/Resources/Characters/Splat_Rigged_Candidate_Iter378.fbx",
                "Assets/SpaceAndCrafts/Resources/Characters/Splat_AnimationActions_Iter911.fbx"
            };
            for (var i = 0; i < paths.Length; i++)
            {
                var assets = AssetDatabase.LoadAllAssetsAtPath(paths[i]);
                Debug.Log($"[Splat animation audit] path={paths[i]}, subassets={assets.Length}.");
                for (var j = 0; j < assets.Length; j++)
                {
                    if (assets[j] is AnimationClip clip)
                    {
                        var bindings = AnimationUtility.GetCurveBindings(clip);
                        var bindingNames = new HashSet<string>();
                        var properties = new HashSet<string>();
                        var scaleMin = new Vector3(float.PositiveInfinity, float.PositiveInfinity, float.PositiveInfinity);
                        var scaleMax = new Vector3(float.NegativeInfinity, float.NegativeInfinity, float.NegativeInfinity);
                        for (var bindingIndex = 0; bindingIndex < bindings.Length; bindingIndex++)
                        {
                            properties.Add(bindings[bindingIndex].propertyName);
                            bindingNames.Add(bindings[bindingIndex].path);
                            var axis = bindings[bindingIndex].propertyName switch
                            {
                                "m_LocalScale.x" => 0,
                                "m_LocalScale.y" => 1,
                                "m_LocalScale.z" => 2,
                                _ => -1
                            };
                            if (axis < 0) continue;
                            var curve = AnimationUtility.GetEditorCurve(clip, bindings[bindingIndex]);
                            if (curve == null) continue;
                            for (var keyIndex = 0; keyIndex < curve.length; keyIndex++)
                            {
                                var value = curve.keys[keyIndex].value;
                                scaleMin[axis] = Mathf.Min(scaleMin[axis], value);
                                scaleMax[axis] = Mathf.Max(scaleMax[axis], value);
                            }
                        }
                        var samplePaths = new List<string>(bindingNames);
                        if (samplePaths.Count > 8) samplePaths.RemoveRange(8, samplePaths.Count - 8);
                        var scaleSummary = float.IsInfinity(scaleMin.x)
                            ? "none"
                            : $"x={scaleMin.x:F3}..{scaleMax.x:F3},y={scaleMin.y:F3}..{scaleMax.y:F3},z={scaleMin.z:F3}..{scaleMax.z:F3}";
                        Debug.Log($"[Splat animation audit] clip={clip.name}, duration={clip.length:F2}s, bindings={bindings.Length}, properties={string.Join(",", properties)}, samplePaths={string.Join(",", samplePaths)}, scaleRange={scaleSummary}.");
                    }
                    else if (assets[j] is GameObject model && model.transform == model.transform.root)
                    {
                        var transforms = model.GetComponentsInChildren<Transform>(true);
                        var names = new List<string>(transforms.Length);
                        for (var transformIndex = 0; transformIndex < transforms.Length; transformIndex++)
                            names.Add(AnimationUtility.CalculateTransformPath(transforms[transformIndex], model.transform));
                        Debug.Log($"[Splat animation audit] model={model.name}, transforms={transforms.Length}, skinnedRenderers={model.GetComponentsInChildren<SkinnedMeshRenderer>(true).Length}, hierarchyPaths={string.Join(",", names)}.");
                    }
                }
            }

            EditorApplication.Exit(0);
        }

        public static void InspectCommissionedCharacterAnimationAssetsIter863()
        {
            var folders = new[]
            {
                "Assets/SpaceAndCrafts/Art/Commissioned/Enemies",
                "Assets/SpaceAndCrafts/Art/Commissioned/Hero",
            };
            var guids = AssetDatabase.FindAssets("t:Model", folders);
            for (var i = 0; i < guids.Length; i++)
            {
                var path = AssetDatabase.GUIDToAssetPath(guids[i]);
                var model = AssetDatabase.LoadAssetAtPath<GameObject>(path);
                if (model == null) continue;

                var skinnedRenderers = model.GetComponentsInChildren<SkinnedMeshRenderer>(true);
                var animatorComponents = model.GetComponentsInChildren<Animator>(true);
                var legacyComponents = model.GetComponentsInChildren<Animation>(true);
                var assets = AssetDatabase.LoadAllAssetsAtPath(path);
                var clips = new List<string>();
                for (var assetIndex = 0; assetIndex < assets.Length; assetIndex++)
                {
                    if (!(assets[assetIndex] is AnimationClip clip)) continue;
                    var bindings = AnimationUtility.GetCurveBindings(clip);
                    clips.Add($"{clip.name}:{clip.length:F2}s/{bindings.Length} bindings");
                }

                var skinnedSummary = new List<string>();
                for (var rendererIndex = 0; rendererIndex < skinnedRenderers.Length; rendererIndex++)
                {
                    var renderer = skinnedRenderers[rendererIndex];
                    if (renderer == null) continue;
                    skinnedSummary.Add($"{renderer.name}:{(renderer.bones != null ? renderer.bones.Length : 0)} bones");
                }

                Debug.Log($"[Character animation asset audit] model={path}, skinnedRenderers={skinnedRenderers.Length} [{string.Join("; ", skinnedSummary)}], animators={animatorComponents.Length}, legacyAnimations={legacyComponents.Length}, importedClips={clips.Count} [{string.Join("; ", clips)}].");
            }

            EditorApplication.Exit(0);
        }

