        public static void InspectSplatRigBindingCoverageIter624()
        {
            const string prefabPath = "Assets/SpaceAndCrafts/Resources/Characters/Splat_Rigged_Candidate_Iter378.fbx";
            var prefab = AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath);
            if (prefab == null)
            {
                Debug.LogError($"[Splat rig coverage] Missing prefab at {prefabPath}.");
                EditorApplication.Exit(2);
                return;
            }

            var rigRoot = prefab.transform.Find("Splat_SkinRig") ?? prefab.transform;
            var transforms = rigRoot.GetComponentsInChildren<Transform>(true);
            var paths = new System.Collections.Generic.HashSet<string> { string.Empty };
            foreach (var bone in transforms)
            {
                var segments = new System.Collections.Generic.List<string>();
                var current = bone;
                while (current != null && current != rigRoot)
                {
                    segments.Add(current.name);
                    current = current.parent;
                }
                segments.Reverse();
                paths.Add(string.Join("/", segments));
            }
            Debug.Log($"[Splat rig coverage] targetRoot={rigRoot.name}, rigPaths={string.Join(" | ", paths)}.");

            var actions = new[] { "Idle", "Run", "Jump", "Land" };
            foreach (var action in actions)
            {
                var path = $"Assets/SpaceAndCrafts/Art/Animations/Authoring/Iter588/Splat_{action}_Iter588.fbx";
                foreach (var asset in AssetDatabase.LoadAllAssetsAtPath(path))
                {
                    if (!(asset is AnimationClip clip) || clip.name.StartsWith("__preview__")) continue;
                    var bindings = AnimationUtility.GetCurveBindings(clip);
                    var matched = 0;
                    var missing = new System.Collections.Generic.SortedSet<string>();
                    foreach (var binding in bindings)
                    {
                        if (paths.Contains(binding.path)) matched++;
                        else missing.Add(binding.path);
                    }
                    var examples = string.Join(", ", new System.Collections.Generic.List<string>(missing).GetRange(
                        0, Mathf.Min(8, missing.Count)));
                    var clipPaths = new System.Collections.Generic.SortedSet<string>();
                    foreach (var binding in bindings) clipPaths.Add(binding.path);
                    Debug.Log($"[Splat rig coverage] action={action} distinctClipPaths={string.Join(" | ", clipPaths)}.");
                    Debug.Log($"[Splat rig coverage] action={action}, clip={clip.name}, prefabTransforms={transforms.Length}, bindings={bindings.Length}, matched={matched}, coverage={(bindings.Length > 0 ? (100f * matched / bindings.Length) : 0f):F1}%, unmatchedPaths={missing.Count}, examples={examples}.");
                }
            }

            EditorApplication.Exit(0);
        }
