        public static void InspectCommissionedEnemyAnimationAssetsIter793()
        {
            var names = new[] { "ScrapMite", "ScrapFloater", "ScrapRoller", "ScrapStormSentinel" };
            for (var i = 0; i < names.Length; i++)
            {
                var path = $"Assets/SpaceAndCrafts/Art/Commissioned/Enemies/{names[i]}.fbx";
                var importer = AssetImporter.GetAtPath(path) as ModelImporter;
                var clips = new List<string>();
                var rendererTypes = new List<string>();
                var animatorCount = 0;
                var assets = AssetDatabase.LoadAllAssetsAtPath(path);
                for (var j = 0; j < assets.Length; j++)
                {
                    if (assets[j] is AnimationClip clip && !clip.name.StartsWith("__preview__", System.StringComparison.Ordinal))
                        clips.Add($"{clip.name}:{clip.length:F2}s");
                    if (assets[j] is GameObject root)
                    {
                        foreach (var animator in root.GetComponentsInChildren<Animator>(true))
                        {
                            animatorCount++;
                            var controller = animator.runtimeAnimatorController;
                            if (controller != null)
                            {
                                foreach (var controllerClip in controller.animationClips)
                                    clips.Add($"controller/{controllerClip.name}:{controllerClip.length:F2}s");
                            }
                        }
                        foreach (var renderer in root.GetComponentsInChildren<SkinnedMeshRenderer>(true))
                            rendererTypes.Add($"SkinnedMeshRenderer:{renderer.name}");
                        foreach (var renderer in root.GetComponentsInChildren<MeshRenderer>(true))
                            rendererTypes.Add($"MeshRenderer:{renderer.name}");
                    }
                }

                var defaultClips = importer != null ? importer.defaultClipAnimations : System.Array.Empty<ModelImporterClipAnimation>();
                Debug.Log($"[Commissioned enemy animation audit] model={names[i]}, animationType={(importer != null ? importer.animationType.ToString() : "missing importer")}, defaultTakeCount={defaultClips.Length}, importedClips=[{string.Join(", ", clips)}], animatorCount={animatorCount}, rendererTypes=[{string.Join(", ", rendererTypes)}].");
            }

            EditorApplication.Exit(0);
        }

