        public static void AnalyzeScrapMiteMeshIslandsIter724()
        {
            const string modelPath = "Assets/SpaceAndCrafts/Art/Commissioned/Enemies/ScrapMite.fbx";
            var assets = AssetDatabase.LoadAllAssetsAtPath(modelPath);
            var meshCount = 0;
            for (var assetIndex = 0; assetIndex < assets.Length; assetIndex++)
            {
                if (!(assets[assetIndex] is Mesh mesh) || mesh.vertexCount == 0)
                {
                    continue;
                }

                meshCount++;
                var vertices = mesh.vertices;
                var parent = new int[vertices.Length];
                var welded = new Dictionary<Vector3Int, int>(vertices.Length);
                for (var vertexIndex = 0; vertexIndex < vertices.Length; vertexIndex++)
                {
                    parent[vertexIndex] = vertexIndex;
                    var vertex = vertices[vertexIndex];
                    var key = new Vector3Int(Mathf.RoundToInt(vertex.x * 100000f),
                        Mathf.RoundToInt(vertex.y * 100000f), Mathf.RoundToInt(vertex.z * 100000f));
                    if (welded.TryGetValue(key, out var existing))
                    {
                        UnionMeshIslandVertices(parent, vertexIndex, existing);
                    }
                    else
                    {
                        welded.Add(key, vertexIndex);
                    }
                }

                var triangles = mesh.triangles;
                for (var triangleIndex = 0; triangleIndex + 2 < triangles.Length; triangleIndex += 3)
                {
                    UnionMeshIslandVertices(parent, triangles[triangleIndex], triangles[triangleIndex + 1]);
                    UnionMeshIslandVertices(parent, triangles[triangleIndex], triangles[triangleIndex + 2]);
                }

                var islands = new Dictionary<int, MeshIslandSummary>();
                for (var vertexIndex = 0; vertexIndex < vertices.Length; vertexIndex++)
                {
                    var root = FindMeshIslandRoot(parent, vertexIndex);
                    if (!islands.TryGetValue(root, out var summary))
                    {
                        summary = new MeshIslandSummary(vertices[vertexIndex]);
                        islands.Add(root, summary);
                    }

                    summary.VertexCount++;
                    summary.Bounds.Encapsulate(vertices[vertexIndex]);
                }

                for (var triangleIndex = 0; triangleIndex + 2 < triangles.Length; triangleIndex += 3)
                {
                    var root = FindMeshIslandRoot(parent, triangles[triangleIndex]);
                    islands[root].TriangleCount++;
                }

                var roots = new List<int>(islands.Keys);
                roots.Sort((left, right) => islands[right].TriangleCount.CompareTo(islands[left].TriangleCount));
                Debug.Log($"[Mesh island diagnostic] asset={modelPath}, mesh={mesh.name}, vertices={mesh.vertexCount}, triangles={triangles.Length / 3}, subMeshes={mesh.subMeshCount}, weldedComponents={roots.Count}, meshBounds={mesh.bounds.size.ToString("F4")}, prefabScale=(100,100,100).");
                var reportCount = Mathf.Min(roots.Count, 32);
                for (var islandIndex = 0; islandIndex < reportCount; islandIndex++)
                {
                    var root = roots[islandIndex];
                    var summary = islands[root];
                    Debug.Log($"[Mesh island diagnostic] island={islandIndex}, vertices={summary.VertexCount}, triangles={summary.TriangleCount}, center={summary.Bounds.center.ToString("F4")}, size={summary.Bounds.size.ToString("F4")}.");
                }
            }

            if (meshCount == 0)
            {
                Debug.LogError($"[Mesh island diagnostic] No readable mesh found at {modelPath}.");
            }

            EditorApplication.Exit(meshCount > 0 ? 0 : 3);
        }

