        private static void BuildScrapMiteMeshIslandPreview(GameObject focusObject, float groundY)
        {
            const string modelPath = "Assets/SpaceAndCrafts/Art/Commissioned/Enemies/ScrapMite.fbx";
            var sourcePrefab = AssetDatabase.LoadAssetAtPath<GameObject>(
                "Assets/SpaceAndCrafts/Art/Commissioned/Enemies/ScrapMite_URP.prefab");
            var sourceFilter = sourcePrefab != null ? sourcePrefab.GetComponent<MeshFilter>() : null;
            var sourceMesh = sourceFilter != null ? sourceFilter.sharedMesh : null;
            var sourceRenderer = sourcePrefab != null ? sourcePrefab.GetComponent<MeshRenderer>() : null;
            if (focusObject == null || sourceMesh == null || sourceRenderer == null)
            {
                Debug.LogError($"[Mesh island preview] Could not load authored mesh/material from {modelPath}.");
                return;
            }

            var parent = new int[sourceMesh.vertexCount];
            var welded = new Dictionary<Vector3Int, int>(sourceMesh.vertexCount);
            var vertices = sourceMesh.vertices;
            var sourceLowestLocalY = float.PositiveInfinity;
            for (var i = 0; i < vertices.Length; i++)
            {
                var sourceRootLocal = sourceFilter.transform.TransformPoint(vertices[i])
                    - sourcePrefab.transform.position;
                sourceLowestLocalY = Mathf.Min(sourceLowestLocalY, sourceRootLocal.y);
            }
            var worldRaise = groundY - focusObject.transform.position.y - sourceLowestLocalY;
            for (var i = 0; i < vertices.Length; i++)
            {
                parent[i] = i;
                var v = vertices[i];
                var key = new Vector3Int(Mathf.RoundToInt(v.x * 100000f),
                    Mathf.RoundToInt(v.y * 100000f), Mathf.RoundToInt(v.z * 100000f));
                if (welded.TryGetValue(key, out var existing)) UnionMeshIslandVertices(parent, i, existing);
                else welded.Add(key, i);
            }

            var triangles = sourceMesh.triangles;
            for (var i = 0; i + 2 < triangles.Length; i += 3)
            {
                UnionMeshIslandVertices(parent, triangles[i], triangles[i + 1]);
                UnionMeshIslandVertices(parent, triangles[i], triangles[i + 2]);
            }

            var islandTriangles = new Dictionary<int, List<int>>();
            for (var i = 0; i + 2 < triangles.Length; i += 3)
            {
                var root = FindMeshIslandRoot(parent, triangles[i]);
                if (!islandTriangles.TryGetValue(root, out var list))
                {
                    list = new List<int>();
                    islandTriangles.Add(root, list);
                }
                list.Add(triangles[i]);
                list.Add(triangles[i + 1]);
                list.Add(triangles[i + 2]);
            }

            foreach (var renderer in focusObject.GetComponentsInChildren<Renderer>(true)) renderer.enabled = false;
            var previewRoot = new GameObject("CaptureOnly_ScrapMiteMeshIslandPreview").transform;
            previewRoot.SetParent(focusObject.transform, false);
            previewRoot.localPosition = focusObject.transform.InverseTransformVector(Vector3.up * worldRaise);
            var normals = sourceMesh.normals;
            var uvs = new List<Vector2>();
            sourceMesh.GetUVs(0, uvs);
            var roots = new List<int>(islandTriangles.Keys);
            roots.Sort((a, b) => islandTriangles[b].Count.CompareTo(islandTriangles[a].Count));
            var shader = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard");
            for (var islandIndex = 0; islandIndex < roots.Count; islandIndex++)
            {
                var localVertices = new List<Vector3>();
                var localNormals = new List<Vector3>();
                var localUvs = new List<Vector2>();
                var localTriangles = new List<int>();
                var remap = new Dictionary<int, int>();
                var sourceTriangles = islandTriangles[roots[islandIndex]];
                for (var i = 0; i < sourceTriangles.Count; i++)
                {
                    var sourceIndex = sourceTriangles[i];
                    if (!remap.TryGetValue(sourceIndex, out var localIndex))
                    {
                        localIndex = localVertices.Count;
                        remap.Add(sourceIndex, localIndex);
                        localVertices.Add(sourceFilter.transform.TransformPoint(vertices[sourceIndex])
                            - sourcePrefab.transform.position);
                        if (normals.Length == vertices.Length)
                        {
                            localNormals.Add(sourcePrefab.transform.InverseTransformDirection(
                                sourceFilter.transform.TransformDirection(normals[sourceIndex])).normalized);
                        }
                        if (uvs.Count == vertices.Length) localUvs.Add(uvs[sourceIndex]);
                    }
                    localTriangles.Add(localIndex);
                }

                var mesh = new Mesh { name = $"CaptureOnly_MiteIsland_{islandIndex:00}" };
                mesh.SetVertices(localVertices);
                mesh.SetTriangles(localTriangles, 0);
                if (localNormals.Count == localVertices.Count) mesh.SetNormals(localNormals);
                else mesh.RecalculateNormals();
                if (localUvs.Count == localVertices.Count) mesh.SetUVs(0, localUvs);
                mesh.RecalculateBounds();
                var componentBounds = new Bounds(localVertices[0], Vector3.zero);
                for (var i = 1; i < localVertices.Count; i++) componentBounds.Encapsulate(localVertices[i]);
                var island = new GameObject($"CaptureOnly_MiteIsland_{islandIndex:00}");
                island.transform.SetParent(previewRoot, false);
                island.AddComponent<MeshFilter>().sharedMesh = mesh;
                var islandRenderer = island.AddComponent<MeshRenderer>();
                if (shader != null)
                {
                    var material = new Material(shader);
                    var color = Color.HSVToRGB((float)islandIndex / Mathf.Max(roots.Count, 1), 0.82f, 0.96f);
                    if (material.HasProperty("_BaseColor")) material.SetColor("_BaseColor", color);
                    if (material.HasProperty("_Color")) material.SetColor("_Color", color);
                    islandRenderer.sharedMaterial = material;
                    Debug.Log($"[Mesh island preview] part={islandIndex:00}, triangles={sourceTriangles.Count / 3}, center={componentBounds.center.ToString("F4")}, size={componentBounds.size.ToString("F4")}, color={color.ToString("F2")}.");
                }
            }
            Debug.Log($"[Mesh island preview] Displayed {roots.Count} disconnected components from the commissioned Scrap Mite mesh; colors identify islands, not intended final materials or rig assignments.");
            var camera = Camera.main;
            if (camera != null)
            {
                var target = new Vector3(focusObject.transform.position.x, groundY + 0.48f,
                    focusObject.transform.position.z);
                camera.transform.position = target + focusObject.transform.right * 1.35f
                    + focusObject.transform.forward * 1.35f + Vector3.up * 0.05f;
                camera.transform.rotation = Quaternion.LookRotation(target - camera.transform.position, Vector3.up);
            }
            Debug.Log($"[Mesh island preview] sourceRootLocalBottom={sourceLowestLocalY:F3}, stageGround={groundY:F3}, lift={worldRaise:F3}, focus={focusObject.transform.position.ToString("F3")}.");
        }

        private static void InstallCaptureOnlyCommissionedMiteRig(GameObject focusObject, float groundY)
        {
            var currentVisual = focusObject.transform.Find("ART_MeshyEnemyVisual");
            if (currentVisual != null
                && currentVisual.GetComponent<SpaceAndCrafts.AI.ScrapMiteCommissionedAnimator>() != null)
            {
                return;
            }

            var prefab = Resources.Load<GameObject>("SpaceAndCrafts/Enemies/ScrapMite_Rigged");
            if (prefab == null)
            {
                Debug.LogError("[Scrap Mite rig capture] Could not load Resources/SpaceAndCrafts/Enemies/ScrapMite_Rigged.prefab.");
                return;
            }

            // Route the trial visual through ScrapMite's real commissioned-rig
            // detection path. Previously this was named CaptureOnly_..., so the
            // legacy root pose driver and pivot animator both wrote the same bones.
            // The old static render is retained in the scene but disabled for this
            // isolated Play Mode capture; nothing is saved back to the level.
            var renderers = focusObject.GetComponentsInChildren<Renderer>(true);
            for (var i = 0; i < renderers.Length; i++)
                if (renderers[i] != null) renderers[i].enabled = false;
            if (currentVisual != null)
            {
                currentVisual.gameObject.SetActive(false);
            }

            var instance = Object.Instantiate(prefab, focusObject.transform, false);
            instance.name = "ART_MeshyEnemyVisual";
            var pivotRigRenderers = instance.GetComponentsInChildren<Renderer>(true);
            var enabledPivotRigRenderers = 0;
            for (var i = 0; i < pivotRigRenderers.Length; i++)
            {
                var renderer = pivotRigRenderers[i];
                if (renderer == null) continue;
                if (renderer.enabled && renderer.gameObject.activeInHierarchy) enabledPivotRigRenderers++;
            }
            Debug.Log($"[Scrap Mite rig capture] Instantiated visual renderer audit: total={pivotRigRenderers.Length}, "
                + $"enabledAndActive={enabledPivotRigRenderers}, visualRootActive={instance.activeInHierarchy}, "
                + $"materials={(pivotRigRenderers.Length > 0 && pivotRigRenderers[0].sharedMaterial != null ? pivotRigRenderers[0].sharedMaterial.name : "missing")}.");
            if (SessionState.GetBool(MiteCompactFaceCaptureKey, false))
            {
                // Isolated art-direction trial: retain the single cohesive Meshy
                // source while reducing the eye cups and rear shell that dominate
                // the current capture-only rig's gameplay silhouette.
                foreach (var part in instance.GetComponentsInChildren<Transform>(true))
                {
                    if (part.name == "ART_MiteShell")
                        part.localScale = Vector3.one * 0.62f;
                    else if (part.name == "ART_MiteEye")
                        part.localScale = Vector3.one * 0.76f;
                }
            }
            var mite = focusObject.GetComponent<SpaceAndCrafts.AI.ScrapMite>();
            if (mite != null)
            {
                var type = typeof(SpaceAndCrafts.AI.ScrapMite);
                type.GetMethod("CacheVisualRig", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                    ?.Invoke(mite, null);
                type.GetMethod("AlignFeetToGround", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                    ?.Invoke(mite, null);
                Debug.Log($"[Scrap Mite rig capture] seatedRoot={mite.transform.position.ToString("F3")}, contactGround={mite.GroundYForVisuals:F3}.");
            }

            var camera = Camera.main;
            if (camera != null)
            {
                var target = new Vector3(focusObject.transform.position.x, groundY + 0.52f,
                    focusObject.transform.position.z);
                camera.transform.position = target + focusObject.transform.forward * 1.8f + Vector3.up * 0.05f;
                camera.transform.rotation = Quaternion.LookRotation(target - camera.transform.position, Vector3.up);
                camera.fieldOfView = 44f;
                var faceCamera = camera.transform.position - focusObject.transform.position;
                faceCamera.y = 0f;
                if (faceCamera.sqrMagnitude > 0.001f)
                    focusObject.transform.rotation = Quaternion.LookRotation(faceCamera.normalized, Vector3.up);
            }
            Debug.Log($"[Scrap Mite rig capture] Instantiated the commissioned mesh pivot rig beneath {focusObject.name} for this Play Mode capture only; root was reseated using the current ground sample ({groundY:F3} m).");
        }

        private sealed class MeshIslandSummary
        {
            public int VertexCount;
            public int TriangleCount;
            public Bounds Bounds;

            public MeshIslandSummary(Vector3 firstVertex)
            {
                Bounds = new Bounds(firstVertex, Vector3.zero);
            }
        }

        private static int FindMeshIslandRoot(int[] parent, int index)
        {
            while (parent[index] != index)
            {
                parent[index] = parent[parent[index]];
                index = parent[index];
            }

            return index;
        }

        private static void UnionMeshIslandVertices(int[] parent, int left, int right)
        {
            var leftRoot = FindMeshIslandRoot(parent, left);
            var rightRoot = FindMeshIslandRoot(parent, right);
            if (leftRoot != rightRoot)
            {
                parent[rightRoot] = leftRoot;
            }
        }

