        private static void CaptureJumpArc(string fileName, int captureAtFrame)
        {
            BeginCapture(fileName, frontFacing: true, poseAction: SplatSkeletonAnimator.Action.Jump,
                simulateJumpArc: true, captureAfterFrames: captureAtFrame);
        }

        private static void BeginCapture(string fileName, bool frontFacing,
            SplatSkeletonAnimator.Action? poseAction = null, bool simulateJumpArc = false,
            int captureAfterFrames = -1, bool candidate310RestPose = false,
            bool candidate310Diagnostic = false, string candidateResource = "",
            bool simulateRun = false, float runCaptureDelaySeconds = 0.45f,
            string captureScenePath = "", string placementPlatform = "", string focusObjectName = "",
            float captureAfterPoseSeconds = 0f, bool isolateFocusObject = false,
            float focusDelaySeconds = 0f, bool turnPlatformCaptureRight = false,
            float spitterShotDelaySeconds = 0f, float runPoseSpeed = 0f,
            bool floaterDiveCapture = false, bool floaterIdleCapture = false,
            bool translateRunRoot = false, bool fixedStepRunCapture = false,
            float fixedStepRunMaxSpeed = 0.8f,
            bool miteAlertCapture = false, bool miteAttackCapture = false,
            bool miteLivePatrolCapture = false, bool miteContactFlinchCapture = false,
            bool miteDefeatCapture = false, bool floaterDefeatCapture = false,
            int sequenceFrameCount = 0, float sequenceCaptureIntervalSeconds = 0.12f,
            bool sideContactCamera = false, bool freezeFocusCamera = false, string authoredClipAction = "",
            bool hideOverlayUi = false, bool followFocusCamera = false,
            float runStopDelaySeconds = 0f, float capturePlatformScale = 1f,
            int captureTargetFrameRate = 0, bool rollerIdleCapture = false,
            bool rollerDefeatCapture = false, Vector3 capturePlatformEulerOffset = default,
            bool captureNeutralizeInput = false, Vector2 fixedStepRunInput = default,
            bool useFixedStepRunInput = false, Vector3 focusCameraCustomOffset = default,
            Vector3 focusCameraCustomTargetOffset = default, bool useFocusCameraCustomOffset = false,
            bool worldBossExamCapture = false, Vector3 captureRootOffset = default,
            bool preserveSceneCamera = false, bool silenceNonFocusEnemies = false,
            string spitterFocusObjectName = "", bool spitterHitResponseCapture = false,
            bool spitterJumpHitResponseCapture = false,
            bool forceWorldFacingForCapture = false,
            bool diagnosePinkRenderers = false,
            bool bossPhaseMiteCapture = false,
            string meshReaction = "", bool landingDustCapture = false)
        {
            if (!Application.isBatchMode)
            {
                Debug.LogError("Arrival visual capture must run in Unity batch mode.");
                EditorApplication.Exit(2);
                return;
            }

            var scenePath = string.IsNullOrWhiteSpace(captureScenePath) ? ScenePath : captureScenePath;
            if (!File.Exists(scenePath))
            {
                Debug.LogError($"Missing capture scene: {scenePath}");
                EditorApplication.Exit(2);
                return;
            }

            var output = Path.GetFullPath(Path.Combine("Logs", "score-comparison", fileName));
            Directory.CreateDirectory(Path.GetDirectoryName(output));

            SessionState.SetBool(ActiveKey, true);
            EditorApplication.wantsToQuit -= HoldBatchCaptureOpen;
            EditorApplication.wantsToQuit += HoldBatchCaptureOpen;
            SessionState.SetString(OutputKey, output);
            SessionState.SetInt(FrameKey, 0);
            SessionState.SetInt(CaptureFrameKey, -1);
            SessionState.SetBool(CapturedKey, false);
            SessionState.SetBool(VictoryScreenCapturePendingKey, false);
            SessionState.SetBool(FrontFacingKey, frontFacing);
            SessionState.SetBool(ForceWorldFacingForCaptureKey, forceWorldFacingForCapture);
            SessionState.SetBool(DiagnosePinkRenderersKey, diagnosePinkRenderers);
            SessionState.SetBool(PinkDiagnosticsLoggedKey, false);
            SessionState.SetString(PoseActionKey, poseAction?.ToString() ?? string.Empty);
            SessionState.SetBool(PoseActionAppliedKey, false);
            SessionState.SetFloat(PoseAppliedTimeKey, 0f);
            SessionState.SetFloat(CaptureAfterPoseSecondsKey, Mathf.Max(0f, captureAfterPoseSeconds));
            SessionState.SetInt(SequenceFrameCountKey, Mathf.Max(0, sequenceFrameCount));
            SessionState.SetFloat(SequenceCaptureIntervalKey, Mathf.Clamp(sequenceCaptureIntervalSeconds, 0.0167f, 1f));
            SessionState.SetInt(SequenceFrameIndexKey, 0);
            SessionState.SetFloat(SequenceLastCaptureTimeKey, 0f);
            SessionState.SetBool(SimulatedJumpKey, simulateJumpArc);
            SessionState.SetBool(SimulatedJumpInputKey, false);
            SessionState.SetBool(PulseJumpInSequenceKey, false);
            SessionState.SetInt(PulseJumpSequenceFrameKey, 0);
            SessionState.SetBool(SimulatedRunKey, simulateRun);
            SessionState.SetBool(FixedStepRunCaptureKey, fixedStepRunCapture);
            SessionState.SetFloat(FixedStepRunMaxSpeedKey, Mathf.Max(0f, fixedStepRunMaxSpeed));
            SessionState.SetBool(FixedStepRunInputEnabledKey, useFixedStepRunInput);
            SessionState.SetFloat(FixedStepRunInputXKey, fixedStepRunInput.x);
            SessionState.SetFloat(FixedStepRunInputYKey, fixedStepRunInput.y);
            SessionState.SetBool(FixedStepRunCaptureAppliedKey, false);
            SessionState.SetInt(CaptureTargetFrameRateKey, Mathf.Max(0, captureTargetFrameRate));
            SessionState.SetBool(CaptureTargetFrameRateAppliedKey, false);
            SessionState.SetFloat(OriginalCaptureDeltaTimeKey, 0f);
            SessionState.SetFloat(SimulatedRunStartTimeKey, 0f);
            SessionState.SetInt(SimulatedRunStartFrameKey, -1);
            SessionState.SetString(SimulatedRunStartPositionKey, string.Empty);
            SessionState.SetFloat(GroundedSinceTimeKey, 0f);
            SessionState.SetFloat(SimulatedRunCaptureDelayKey,
                Mathf.Max(fixedStepRunCapture ? (1f / 60f) : 0.45f, runCaptureDelaySeconds));
            SessionState.SetFloat(RunStopDelayKey, Mathf.Max(0f, runStopDelaySeconds));
            SessionState.SetBool(RunStopAppliedKey, false);
            SessionState.SetInt(CaptureDelayFramesKey, captureAfterFrames);
            SessionState.SetBool(Candidate310RestPoseKey, candidate310RestPose);
            SessionState.SetBool(Candidate310DiagnosticKey, candidate310Diagnostic);
            SessionState.SetString(CandidateResourceKey, candidateResource);
            SessionState.SetString(AuthoredClipActionKey, authoredClipAction);
            SessionState.SetString(MeshReactionKey, meshReaction ?? string.Empty);
            SessionState.SetBool(LandingDustCaptureKey, landingDustCapture);
            SessionState.SetBool(MeshReactionAppliedKey, false);
            SessionState.SetInt(MeshReactionAppliedIndexKey, -1);
            SessionState.SetString(PlacementPlatformKey, placementPlatform);
            SessionState.SetFloat(CapturePlatformScaleKey, Mathf.Clamp(capturePlatformScale, 0.15f, 100f));
            SessionState.SetVector3(CapturePlatformEulerOffsetKey, capturePlatformEulerOffset);
            SessionState.SetVector3(CaptureRootOffsetKey, captureRootOffset);
            SessionState.SetBool(CaptureNeutralizeInputKey, captureNeutralizeInput);
            SessionState.SetBool(PlacementAppliedKey, false);
            SessionState.SetBool(AlignSplatContactBeforeSequenceFrameKey, false);
            SessionState.SetBool(SimulatedJumpInputKey, false);
            SessionState.SetBool(TurnPlatformCaptureRightKey, turnPlatformCaptureRight);
            SessionState.SetString(FocusObjectKey, focusObjectName);
            SessionState.SetString(SpitterFocusObjectKey, spitterFocusObjectName);
            SessionState.SetBool(SpitterHitResponseCaptureKey, spitterHitResponseCapture);
            SessionState.SetBool(SpitterJumpHitResponseCaptureKey, spitterJumpHitResponseCapture);
            SessionState.SetBool(IsolateFocusObjectKey, isolateFocusObject);
            SessionState.SetBool(IsolatedFocusPreparedKey, false);
            SessionState.SetBool(PreserveSceneCameraKey, preserveSceneCamera);
            SessionState.SetBool(SilenceNonFocusEnemiesKey, silenceNonFocusEnemies);
            SessionState.SetBool(SideContactCameraKey, sideContactCamera);
            SessionState.SetBool(FreezeFocusCameraKey, freezeFocusCamera);
            SessionState.SetBool(FollowFocusCameraKey, followFocusCamera);
            SessionState.SetBool(UseFocusCameraCustomOffsetKey, useFocusCameraCustomOffset);
            SessionState.SetVector3(FocusCameraCustomOffsetKey, focusCameraCustomOffset);
            SessionState.SetVector3(FocusCameraCustomTargetOffsetKey, focusCameraCustomTargetOffset);
            SessionState.SetBool(HideOverlayCanvasKey, hideOverlayUi);
            SessionState.SetBool(FocusAggroStagedKey, false);
            SessionState.SetBool(FocusIdleStagedKey, false);
            SessionState.SetBool(MiteNearIdlePlayerCameraKey, false);
            SessionState.SetBool(MiteAlertCaptureKey, miteAlertCapture);
            SessionState.SetBool(MiteAttackCaptureKey, miteAttackCapture);
            SessionState.SetBool(BossPhaseMiteCaptureKey, bossPhaseMiteCapture);
            SessionState.SetBool(MiteLivePatrolCaptureKey, miteLivePatrolCapture);
            SessionState.SetBool(MiteContactFlinchCaptureKey, miteContactFlinchCapture);
            SessionState.SetBool(MiteDefeatCaptureKey, miteDefeatCapture);
            SessionState.SetBool(SentinelDefeatCaptureKey, false);
            SessionState.SetBool(SentinelSlamCaptureKey, false);
            SessionState.SetBool(SentinelWeakPointCaptureKey, false);
            SessionState.SetBool(SentinelSkipGuidedLookCaptureKey, false);
            SessionState.SetBool(SentinelFinalHitCaptureKey, false);
            SessionState.SetBool(SentinelFinalHitTriggeredKey, false);
            SessionState.SetBool(WorldBossExamCaptureKey, worldBossExamCapture);
            SessionState.SetBool(WorldBossExamCaptureStagedKey, false);
            SessionState.SetFloat(FocusAggroStagedAtKey, 0f);
            SessionState.SetFloat(FocusIdleStagedAtKey, 0f);
            SessionState.SetFloat(FocusDelaySecondsKey, focusDelaySeconds);
            SessionState.SetFloat(SpitterShotDelayKey, spitterShotDelaySeconds);
            SessionState.SetBool(FloaterDiveCaptureKey, floaterDiveCapture);
            SessionState.SetBool(FloaterIdleCaptureKey, floaterIdleCapture);
            SessionState.SetBool(FloaterDefeatCaptureKey, floaterDefeatCapture);
            SessionState.SetBool(RollerIdleCaptureKey, rollerIdleCapture);
            SessionState.SetBool(RollerDefeatCaptureKey, rollerDefeatCapture);
            SessionState.SetBool(RollerDefeatCaptureStartedKey, false);
            SessionState.SetFloat(RunPoseSpeedKey, Mathf.Max(0f, runPoseSpeed));
            SessionState.SetBool(RunRootTranslationKey, translateRunRoot);
            SessionState.SetBool(RunRootTranslationStartedKey, false);
            SessionState.SetFloat(RunRootStartXKey, 0f);
            SessionState.SetFloat(RunRootStartYKey, 0f);
            SessionState.SetFloat(RunRootStartZKey, 0f);
            SessionState.SetFloat(RunRootStartTimeKey, 0f);
            RegisterCallbacks();
            EditorSceneManager.OpenScene(scenePath, OpenSceneMode.Single);
            if (scenePath == World03ScenePath
                && SessionState.GetBool(World03PatrolStaggerCandidateKey, false))
            {
                var encounterPack = GameObject.Find("ART_EncounterPack");
                if (encounterPack != null)
                {
                    encounterPack.transform.position += Vector3.forward * 2.5f;
                    SessionState.SetBool(World03PatrolStaggerCandidateKey, false);
                    Debug.Log("[Space & Crafts] Applied an unsaved +2.5 m route-forward offset to World 03 ART_EncounterPack for a capture-only spacing comparison.");
                }
                else
                {
                    SessionState.SetBool(World03PatrolStaggerCandidateKey, false);
                    Debug.LogError("[Space & Crafts] World 03 patrol spacing candidate could not find ART_EncounterPack.");
                }
            }
            EditorApplication.delayCall += () => EditorApplication.isPlaying = true;
            Debug.Log($"[Space & Crafts] Opened {scenePath} for one batch-mode visual capture.");
        }

        private static bool HoldBatchCaptureOpen()
        {
            // Unity otherwise exits batch mode as soon as -executeMethod returns,
            // before the deferred Play Mode capture has a chance to run.
            return !SessionState.GetBool(ActiveKey, false);
        }

        private static void RegisterCallbacks()
        {
            EditorApplication.playModeStateChanged -= OnPlayModeStateChanged;
            EditorApplication.playModeStateChanged += OnPlayModeStateChanged;
            EditorApplication.update -= Tick;
            EditorApplication.update += Tick;
        }

        private static void OnPlayModeStateChanged(PlayModeStateChange state)
        {
            if (!SessionState.GetBool(ActiveKey, false))
            {
                return;
            }

            if (state == PlayModeStateChange.EnteredPlayMode)
            {
                var targetFrameRate = SessionState.GetInt(CaptureTargetFrameRateKey, 0);
                if (targetFrameRate > 0)
                {
                    SessionState.SetFloat(OriginalCaptureDeltaTimeKey, Time.captureDeltaTime);
                    Time.captureDeltaTime = 1f / targetFrameRate;
                    SessionState.SetBool(CaptureTargetFrameRateAppliedKey, true);
                    Debug.Log($"[Space & Crafts] Fixed diagnostic capture timestep at {targetFrameRate} fps.");
                }
                SessionState.SetInt(FrameKey, 0);
            }
            else if (state == PlayModeStateChange.EnteredEditMode && SessionState.GetBool(CapturedKey, false))
            {
                Finish();
            }
        }

        private static void Tick()
        {
            if (!SessionState.GetBool(ActiveKey, false))
            {
                EditorApplication.update -= Tick;
                return;
            }

            var frame = SessionState.GetInt(FrameKey, 0) + 1;
            SessionState.SetInt(FrameKey, frame);
            if (EditorApplication.isPlaying)
            {
                if (frame >= 15 && !SessionState.GetBool(SecretBadgeStagedKey, false)
                    && SessionState.GetString(OutputKey, string.Empty).Contains("arrival-secret-nook-badge-iter2152"))
                {
                    StageSecretBadgeCapture();
                }

                if (SessionState.GetBool(VictoryScreenCapturePendingKey, false))
                {
                    return;
                }

                if (SessionState.GetBool(BossPhaseMiteCaptureKey, false) && frame >= 15)
                {
                    StageScrapStormPhaseMiteCapture();
                }

                if (SessionState.GetBool(DiagnosePinkRenderersKey, false)
                    && !SessionState.GetBool(PinkDiagnosticsLoggedKey, false) && frame >= 15)
                {
                    LogPinkRendererDiagnostics();
                    SessionState.SetBool(PinkDiagnosticsLoggedKey, true);
                }

                if (SessionState.GetBool(FocusStaticMeshyMiteKey, false))
                {
                    var mites = Object.FindObjectsByType<SpaceAndCrafts.AI.ScrapMite>();
                    for (var i = 0; i < mites.Length; i++)
                    {
                        var mite = mites[i];
                        if (mite == null || !mite.gameObject.activeInHierarchy) continue;
                        var visual = mite.transform.Find("ART_MeshyEnemyVisual");
                        if (visual == null || !visual.gameObject.activeInHierarchy) continue;
                        var meshFilters = visual.GetComponentsInChildren<MeshFilter>(true);
                        if (meshFilters.Length != 1 || meshFilters[0] == null || meshFilters[0].sharedMesh == null) continue;

                        mite.gameObject.name = $"ART_ScrapMite_MeshyCapture_{frame}";
                        SessionState.SetString(FocusObjectKey, mite.gameObject.name);
                        SessionState.SetBool(FocusStaticMeshyMiteKey, false);
                        Debug.Log($"[Space & Crafts] Selected static Meshy Mite visual for capture: root={mite.name}, visual={visual.name}, mesh={meshFilters[0].sharedMesh.name}, meshFilters={meshFilters.Length}.");
                        break;
                    }

                    if (SessionState.GetBool(FocusStaticMeshyMiteKey, false))
                    {
                        var mite = Object.FindAnyObjectByType<SpaceAndCrafts.AI.ScrapMite>();
                        var meshPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(
                            "Assets/SpaceAndCrafts/Art/Commissioned/Enemies/ScrapMite_URP.prefab");
                        if (mite != null && meshPrefab != null)
                        {
                            SessionState.SetBool(FocusStaticMeshyMiteKey, false);
                            var visual = Object.Instantiate(meshPrefab, mite.transform);
                            visual.name = "ART_MeshyEnemyVisual";
                            visual.transform.localPosition = new Vector3(0f, 0.57f, 0f);
                            visual.transform.localRotation = Quaternion.identity;
                            visual.transform.localScale = Vector3.one * 110f;
                            var existingRenderers = mite.GetComponentsInChildren<Renderer>(true);
                            for (var i = 0; i < existingRenderers.Length; i++)
                            {
                                if (existingRenderers[i] != null
                                    && !existingRenderers[i].transform.IsChildOf(visual.transform))
                                {
                                    existingRenderers[i].enabled = false;
                                }
                            }
                            typeof(SpaceAndCrafts.AI.ScrapMite).GetMethod("CacheVisualRig",
                                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                                ?.Invoke(mite, null);
                            mite.gameObject.name = $"ART_ScrapMite_MeshyCapture_{frame}";
                            SessionState.SetString(FocusObjectKey, mite.gameObject.name);
                            Debug.Log($"[Space & Crafts] No active static Meshy Mite instance was in this capture scene; staged its existing cohesive source visual for capture only. root={mite.name}, asset={AssetDatabase.GetAssetPath(meshPrefab)}, meshFilters={visual.GetComponentsInChildren<MeshFilter>(true).Length}.");
                        }
                        else
                        {
                            var attempts = SessionState.GetInt(FocusStaticMeshyMiteAttemptsKey, 0) + 1;
                            SessionState.SetInt(FocusStaticMeshyMiteAttemptsKey, attempts);
                            if (attempts >= 90)
                            {
                                SessionState.SetBool(FocusStaticMeshyMiteKey, false);
                                Debug.LogWarning("[Space & Crafts] Could not find a live ScrapMite or load its existing Meshy visual for the focused capture.");
                            }
                        }
                    }
                }

                // Front-face evidence should land before the character's randomized
                // first blink; the standard rear gameplay capture keeps its longer
                // settling window so spawn/UI systems finish initializing.
                var frontFacing = SessionState.GetBool(FrontFacingKey, false);
                var requestedCaptureFrame = SessionState.GetInt(CaptureDelayFramesKey, -1);
                var captureDelayFrames = requestedCaptureFrame >= 0
                    ? requestedCaptureFrame
                    : frontFacing ? 45 : 180;
                var candidateDiagnostic = SessionState.GetBool(Candidate310DiagnosticKey, false);
                var poseActionName = SessionState.GetString(PoseActionKey, string.Empty);
                var capturePlayer = GameObject.Find("Splat_TEMP");
                var sequenceDiagnosticsRequested = SessionState.GetInt(SequenceFrameCountKey, 0) > 0;
                var splatAnimator = frontFacing || candidateDiagnostic || sequenceDiagnosticsRequested
                    || !string.IsNullOrEmpty(poseActionName)
                    ? capturePlayer != null
                        ? capturePlayer.GetComponent<SplatSkeletonAnimator>()
                            ?? Object.FindAnyObjectByType<SplatSkeletonAnimator>()
                        : Object.FindAnyObjectByType<SplatSkeletonAnimator>()
                    : null;
                var placementPlatform = SessionState.GetString(PlacementPlatformKey, string.Empty);
                if (!string.IsNullOrEmpty(placementPlatform)
                    && !SessionState.GetBool(PlacementAppliedKey, false) && frame >= 15)
                {
                    var capturePlatformScale = SessionState.GetFloat(CapturePlatformScaleKey, 1f);
                    var capturePlatformEulerOffset = SessionState.GetVector3(CapturePlatformEulerOffsetKey, Vector3.zero);
                    var capturePlatform = GameObject.Find(placementPlatform);
                    if (capturePlatform != null && capturePlatformEulerOffset.sqrMagnitude > 0.0001f)
                    {
                        capturePlatform.transform.rotation = Quaternion.Euler(capturePlatformEulerOffset)
                            * capturePlatform.transform.rotation;
                        Physics.SyncTransforms();
                        Debug.Log($"[Space & Crafts] Applied capture-only platform tilt {capturePlatformEulerOffset:F1} to {placementPlatform}.");
                    }
                    if (Mathf.Abs(capturePlatformScale - 1f) > 0.001f)
                    {
                        var platform = capturePlatform;
                        if (platform != null)
                        {
                            var scale = platform.transform.localScale;
                            scale.x *= capturePlatformScale;
                            scale.z *= capturePlatformScale;
                            platform.transform.localScale = scale;
                            Physics.SyncTransforms();
                            var scaleVerb = capturePlatformScale < 1f ? "Narrowed" : "Expanded";
                            Debug.Log($"[Space & Crafts] {scaleVerb} capture-only support platform {placementPlatform} to {capturePlatformScale:F2}x X/Z for the contact sample.");
                        }
                    }
                    PlaceSplatOnPlatform(placementPlatform);
                    var captureRootOffset = SessionState.GetVector3(CaptureRootOffsetKey, Vector3.zero);
                    if (captureRootOffset.sqrMagnitude > 0.000001f)
                    {
                        var captureSplat = GameObject.Find("Splat_TEMP");
                        if (captureSplat != null)
                        {
                            captureSplat.transform.position += captureRootOffset;
                            Physics.SyncTransforms();
                            Debug.Log($"[Space & Crafts] Applied capture-only Splat root offset {captureRootOffset:F3} for partial-pad-support contact sampling.");
                        }
                    }
                    SessionState.SetBool(PlacementAppliedKey, true);
                }

                if (!SessionState.GetBool(FocusAggroStagedKey, false)
                    && (SessionState.GetString(FocusObjectKey, string.Empty) == "ART_ScrapRoller"
                        || SessionState.GetString(FocusObjectKey, string.Empty) == "ART_Meshy_ScrapRoller")
                    && frame >= 15)
                {
                    if (SessionState.GetBool(RollerIdleCaptureKey, false))
                    {
                        StageScrapRollerIdleCapture();
                    }
                    else if (SessionState.GetBool(RollerDefeatCaptureKey, false))
                    {
                        StageSplatForScrapRollerCapture();
                    }
                    else
                    {
                        StageSplatForScrapRollerCapture();
                    }
                }

                if (!SessionState.GetBool(FocusIdleStagedKey, false)
                    && IsScrapMiteFocus(SessionState.GetString(FocusObjectKey, string.Empty))
                    && !SessionState.GetBool(MiteLivePatrolCaptureKey, false)
                    && !SessionState.GetBool(MiteAlertCaptureKey, false)
                    && !SessionState.GetBool(MiteAttackCaptureKey, false)
                    && frame >= 15)
                {
                    StageScrapMiteIdleCapture();
                }

                if (!SessionState.GetBool(FocusAggroStagedKey, false)
                    && IsScrapMiteFocus(SessionState.GetString(FocusObjectKey, string.Empty))
                    && SessionState.GetBool(MiteAlertCaptureKey, false)
                    && !SessionState.GetBool(MiteAttackCaptureKey, false)
                    && frame >= 15)
                {
                    StageScrapMiteAlertCapture();
                }

                if (!SessionState.GetBool(FocusAggroStagedKey, false)
                    && IsScrapMiteFocus(SessionState.GetString(FocusObjectKey, string.Empty))
                    && SessionState.GetBool(MiteAttackCaptureKey, false)
                    && frame >= 15)
                {
                    StageScrapMiteAttackCapture();
                }

                var spitterFocusName = SessionState.GetString(SpitterFocusObjectKey, string.Empty);
                if (string.IsNullOrEmpty(spitterFocusName))
                    spitterFocusName = SessionState.GetString(FocusObjectKey, string.Empty);
                if (!SessionState.GetBool(FocusAggroStagedKey, false)
                    && spitterFocusName.StartsWith("ART_ScrapSpitter_", System.StringComparison.Ordinal)
                    && frame >= 15)
                {
                    StageScrapSpitterCapture();
                }

                if (!SessionState.GetBool(FocusAggroStagedKey, false)
                    && SessionState.GetString(FocusObjectKey, string.Empty) == "ART_ScrapFloater"
                    && frame >= 15)
                {
                    StageScrapFloaterCapture(SessionState.GetBool(FloaterDiveCaptureKey, false),
                        SessionState.GetBool(FloaterIdleCaptureKey, false),
                        SessionState.GetBool(FloaterDefeatCaptureKey, false));
                }

                if (!SessionState.GetBool(FocusAggroStagedKey, false)
                    && SessionState.GetString(FocusObjectKey, string.Empty) == "ART_ScrapStormSentinel"
                    && SessionState.GetBool(SentinelDefeatCaptureKey, false)
                    && frame >= 15)
                {
                    StageScrapStormSentinelDefeatCapture();
                }

                if (!SessionState.GetBool(FocusAggroStagedKey, false)
                    && SessionState.GetString(FocusObjectKey, string.Empty) == "ART_ScrapStormSentinel"
                    && SessionState.GetBool(SentinelSlamCaptureKey, false)
                    && frame >= 15)
                {
                    StageScrapStormSentinelSlamCapture();
                }

                if (!SessionState.GetBool(FocusAggroStagedKey, false)
                    && SessionState.GetString(FocusObjectKey, string.Empty) == "ART_ScrapStormSentinel"
                    && (SessionState.GetBool(SentinelWeakPointCaptureKey, false)
                        || SessionState.GetBool(SentinelFinalHitCaptureKey, false))
                    && frame >= 15)
                {
                    StageScrapStormSentinelWeakPointCapture();
                }

                if (!string.IsNullOrEmpty(poseActionName) && frame >= 15
                    && !SessionState.GetBool(PoseActionAppliedKey, false))
                {
                    if (splatAnimator != null && System.Enum.TryParse(poseActionName, out SplatSkeletonAnimator.Action poseAction))
                    {
                        if (candidateDiagnostic && !string.IsNullOrWhiteSpace(
                                SessionState.GetString(CandidateResourceKey, string.Empty)))
                        {
                            PrepareCandidateDiagnostic(splatAnimator,
                                SessionState.GetString(CandidateResourceKey, string.Empty),
                                SessionState.GetBool(Candidate310RestPoseKey, false));
                        }
                        if (SessionState.GetBool(SimulatedJumpKey, false) && poseAction == SplatSkeletonAnimator.Action.Jump)
                        {
                            // Resolve from the staged player root first. Global
                            // FindAnyObjectByType can miss a disabled scene component,
                            // which previously left this capture as a posed still.
                            var stagedPlayer = GameObject.Find("Splat_TEMP");
                            var motor = stagedPlayer != null
                                ? stagedPlayer.GetComponent<SplatMotor>()
                                : Object.FindAnyObjectByType<SplatMotor>();
                            if (SessionState.GetBool(SimulatedJumpInputKey, false))
                            {
                                var inputReader = stagedPlayer != null
                                    ? stagedPlayer.GetComponent<SplatInputReader>()
                                    : Object.FindAnyObjectByType<SplatInputReader>();
                                if (motor != null && inputReader != null)
                                {
                                    if (!motor.enabled) motor.enabled = true;
                                    inputReader.DebugPulseJump();
                                    Debug.Log("[Space & Crafts] Pulsed the gameplay Jump input for the staged Splat capture; SplatMotor.TryJump will own takeoff.");
                                }
                                else
                                {
                                    Debug.LogWarning($"[Space & Crafts] Could not pulse gameplay Jump input; motor={(motor != null)}, inputReader={(inputReader != null)}.");
                                }
                            }
                            else
                            {
                                if (motor != null)
                                {
                                    if (!motor.enabled) motor.enabled = true;
                                    // The game settings' 2.4-unit jump at 45 units/s² begins at ~14.7 units/s.
                                    motor.ApplyLaunch(Vector3.up * 14.7f);
                                    Debug.Log("[Space & Crafts] Applied a physics-driven Splat jump for the pose-arc capture.");
                                }
                                else
                                {
                                    Debug.LogWarning($"[Space & Crafts] Could not simulate jump arc; Splat_TEMP motor missing (playerRoot={(stagedPlayer != null)}).");
                                }
                            }
                        }
                        var poseDuration = SessionState.GetInt(SequenceFrameCountKey, 0) > 0 ? 120f
                            : poseAction == SplatSkeletonAnimator.Action.Run ? 12f
                            : poseAction == SplatSkeletonAnimator.Action.Land ? 0.38f
                            : 3f;
                        if (SessionState.GetInt(SequenceFrameCountKey, 0) > 0)
                        {
                            // A scene-start celebration intentionally blocks other
                            // gameplay actions. A staged animation capture must clear
                            // that prior one-shot or it can silently render Idle.
                            splatAnimator.StopAllCoroutines();
                            typeof(SplatSkeletonAnimator).GetField("_action",
                                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                                ?.SetValue(splatAnimator, SplatSkeletonAnimator.Action.Idle);
                            typeof(SplatSkeletonAnimator).GetField("_actionUntil",
                                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                                ?.SetValue(splatAnimator, Time.time - 1f);
                        }
                        if (SessionState.GetInt(SequenceFrameCountKey, 0) > 0
                            && poseAction == SplatSkeletonAnimator.Action.Craft)
                        {
                            // Isolate a grounded craft pose from a late CharacterController
                            // landing callback that would otherwise replace Craft with Land.
                            var craftCaptureMotor = capturePlayer != null
                                ? capturePlayer.GetComponent<SplatMotor>() : null;
                            if (craftCaptureMotor != null)
                            {
                                craftCaptureMotor.enabled = false;
                                typeof(SplatMotor).GetField("<IsGrounded>k__BackingField",
                                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                                    ?.SetValue(craftCaptureMotor, true);
                                Debug.Log("[Space & Crafts] Held the capture-only player motor grounded during the craft animation sequence.");
                            }
                        }
                        var runPoseSpeed = SessionState.GetFloat(RunPoseSpeedKey, 0f);
                        if (poseAction == SplatSkeletonAnimator.Action.Run && runPoseSpeed > 0f)
                        {
                            var motor = Object.FindAnyObjectByType<SplatMotor>();
                            var velocityField = typeof(SplatMotor).GetField("_velocity",
                                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                            if (motor != null && velocityField != null)
                            {
                                velocityField.SetValue(motor, Vector3.forward * runPoseSpeed);
                                motor.enabled = false;
                                var groundedField = typeof(SplatMotor).GetField("<IsGrounded>k__BackingField",
                                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                                groundedField?.SetValue(motor, true);
                                Debug.Log($"[Space & Crafts] Held Splat in place with a {runPoseSpeed:F1} m/s animation speed for the platform run pose capture.");
                            }
                            else
                            {
                                Debug.LogWarning("[Space & Crafts] Could not stage platform run speed; SplatMotor or its velocity field was missing.");
                            }
                        }
                        if (poseAction == SplatSkeletonAnimator.Action.Craft)
                        {
                            splatAnimator.PlayCraftAnimation(poseDuration);
                        }
                        else
                        {
                            splatAnimator.PlayAction(poseAction, poseDuration);
                        }
                        Debug.Log($"[Space & Crafts] Staged {poseAction} capture pose on {splatAnimator.gameObject.name}; currentAction={splatAnimator.CurrentAction}, duration={poseDuration:F1}s, sequenceFrames={SessionState.GetInt(SequenceFrameCountKey, 0)}.");
                        SessionState.SetFloat(PoseAppliedTimeKey, Time.time);
                        if (poseAction == SplatSkeletonAnimator.Action.Run
                            && SessionState.GetBool(RunRootTranslationKey, false))
                        {
                            var rootMotor = Object.FindAnyObjectByType<SplatMotor>();
                            if (rootMotor != null)
                            {
                                var start = rootMotor.transform.position;
                                SessionState.SetFloat(RunRootStartXKey, start.x);
                                SessionState.SetFloat(RunRootStartYKey, start.y);
                                SessionState.SetFloat(RunRootStartZKey, start.z);
                                SessionState.SetFloat(RunRootStartTimeKey, Time.time);
                                SessionState.SetBool(RunRootTranslationStartedKey, true);
                            }
                        }
                        Debug.Log($"[Space & Crafts] Applied {poseAction} pose for rig review.");
                    }
                    else
                    {
                        Debug.LogWarning("[Space & Crafts] Could not apply requested Splat pose; animator or pose action was missing.");
                    }
                    if (SessionState.GetBool(LandingDustCaptureKey, false))
                    {
                        var dustCapturePlayer = GameObject.Find("Splat_TEMP");
                        var captureMotor = dustCapturePlayer != null
                            ? dustCapturePlayer.GetComponent<SplatMotor>()
                            : null;
                        var captureController = dustCapturePlayer != null
                            ? dustCapturePlayer.GetComponent<CharacterController>()
                            : null;
                        if (dustCapturePlayer != null)
                        {
                            var contactY = captureController != null
                                ? captureController.bounds.min.y - captureController.skinWidth
                                : dustCapturePlayer.transform.position.y;
                            var dust = TempLandDustBurst.Spawn(dustCapturePlayer.transform.position,
                                contactY, 0.9f, true);
                            var dustSystem = dust != null ? dust.GetComponent<ParticleSystem>() : null;
                            var dustRing = dust != null ? dust.GetComponentInChildren<MeshRenderer>() : null;
                            var dustRingMesh = dustRing != null ? dustRing.GetComponent<MeshFilter>() : null;
                            var capturePad = GameObject.Find(SessionState.GetString(PlacementPlatformKey, string.Empty));
                            var capturePadCollider = capturePad != null ? capturePad.GetComponent<Collider>() : null;
                            Debug.Log($"[LandingDustCapture] Spawned player landing burst: grounded={captureMotor != null && captureMotor.IsGrounded}, player={dustCapturePlayer.transform.position:F3}, particles={dustSystem?.particleCount ?? 0}, ring={dustRing != null && dustRing.enabled}, ringVertices={dustRingMesh?.sharedMesh?.vertexCount ?? 0}, ringShader={dustRing?.sharedMaterial?.shader?.name ?? "missing"}, ringBounds={dustRing?.bounds.ToString("F3") ?? "missing"}, padTop={(capturePadCollider != null ? capturePadCollider.bounds.max.y.ToString("F3") : "missing")}, contactY={contactY:F3}.");
                        }
                        else
                        {
                            Debug.LogWarning("[LandingDustCapture] Splat_TEMP was missing; could not stage the landing burst.");
                        }
                    }
                    SessionState.SetBool(PoseActionAppliedKey, true);
                }

                if (SessionState.GetBool(SimulatedRunKey, false)
                    && SessionState.GetFloat(SimulatedRunStartTimeKey, 0f) <= 0f)
                {
                    var motor = Object.FindAnyObjectByType<SplatMotor>();
                    var inputReader = Object.FindAnyObjectByType<SplatInputReader>();
                    if (motor == null || inputReader == null)
                    {
                        Debug.LogWarning("[Space & Crafts] Could not simulate a grounded run; motor or input reader was missing.");
                    }
                    else if (!motor.IsGrounded)
                    {
                        SessionState.SetFloat(GroundedSinceTimeKey, 0f);
                    }
                    else
                    {
                        var groundedSince = SessionState.GetFloat(GroundedSinceTimeKey, 0f);
                        if (groundedSince <= 0f)
                        {
                            SessionState.SetFloat(GroundedSinceTimeKey, Time.time);
                        }
                        else if (Time.time - groundedSince >= 0.35f)
                        {
                            if (SessionState.GetBool(FixedStepRunCaptureKey, false)
                                && !SessionState.GetBool(FixedStepRunCaptureAppliedKey, false))
                            {
                                SessionState.SetFloat(OriginalCaptureDeltaTimeKey, Time.captureDeltaTime);
                                Time.captureDeltaTime = 1f / 60f;
                                SessionState.SetBool(FixedStepRunCaptureAppliedKey, true);
                            }

                            var platformCapture = !string.IsNullOrEmpty(
                                SessionState.GetString(PlacementPlatformKey, string.Empty));
                            if (platformCapture)
                            {
                                var settingsField = typeof(SplatMotor).GetField("settings",
                                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                                var originalSettings = settingsField?.GetValue(motor) as SplatMotorSettings;
                                if (originalSettings != null)
                                {
                                    var captureSettings = Object.Instantiate(originalSettings);
                                    captureSettings.MaxSpeed = SessionState.GetFloat(FixedStepRunMaxSpeedKey, 0.8f);
                                    settingsField.SetValue(motor, captureSettings);
                                    var velocityField = typeof(SplatMotor).GetField("_velocity",
                                        System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                                    velocityField?.SetValue(motor, Vector3.zero);
                                    var boostMultiplierField = typeof(SplatMotor).GetField("_moveBoostMultiplier",
                                        System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                                    boostMultiplierField?.SetValue(motor, 1f);
                                    var boostUntilField = typeof(SplatMotor).GetField("_moveBoostUntil",
                                        System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                                    boostUntilField?.SetValue(motor, 0f);
                                    Debug.Log($"[Space & Crafts] Used a capture-only {captureSettings.MaxSpeed:F1} m/s run speed and cleared prior motor velocity/boost for the physics-driven contact sample on the traversal pad.");
                                }
                            }

                            var runInput = platformCapture
                                ? SessionState.GetBool(FixedStepRunInputEnabledKey, false)
                                    ? Vector2.ClampMagnitude(new Vector2(
                                        SessionState.GetFloat(FixedStepRunInputXKey, 1f),
