                                    continue;
                                }

                                names.Add($"{hit.collider.name}@{hit.distance:F2}m/n={hit.normal:F1}");
                            }

                            blockers = names.Count > 0
                                ? string.Join("; ", names)
                                : $"none in {diagnosticSweepDistance:F2}m sweep";
                        }
                        var animator = Object.FindAnyObjectByType<SplatSkeletonAnimator>();
                        var contactRepair = motor != null ? motor.GetComponent<SplatVisualRepair>() : null;
                        Debug.Log($"[Space & Crafts] Run capture state: elapsed={runElapsed:F2}s, frames={runFrameCount}, deltaTime={Time.deltaTime:F4}, captureDeltaTime={Time.captureDeltaTime:F4}, start={SessionState.GetString(SimulatedRunStartPositionKey, "unknown")}, grounded={motor != null && motor.IsGrounded}, planarSpeed={(motor != null ? motor.PlanarVelocity.magnitude : 0f):F2}, input={(inputReader != null ? inputReader.Move.ToString("F2") : "missing")}, motorEnabled={motor != null && motor.enabled}, controllerEnabled={controller != null && controller.enabled}, controllerRadius={(controller != null ? controller.radius : 0f):F2}, controllerSkinWidth={(controller != null ? controller.skinWidth : 0f):F3}, parent={(motor != null && motor.transform.parent != null ? motor.transform.parent.name : "none")}, maxSpeed={(motorSettings != null ? motorSettings.MaxSpeed : 0f):F2}, collisionFlags={(controller != null ? controller.collisionFlags.ToString() : "no controller")}, position={(motor != null ? motor.transform.position.ToString("F3") : "missing motor")}, requestedMove={(motor != null ? motor.LastRequestedMoveForDiagnostics.ToString("F4") : "missing")}, appliedMove={(motor != null ? motor.LastAppliedMoveForDiagnostics.ToString("F4") : "missing")}, horizontalSweepBlockers={blockers}, footPlants={(animator != null ? animator.FootPlantCountForDiagnostics : 0)}, leftLeg={(animator != null ? animator.BoundLeftLegWorldPosition.ToString("F3") : "missing")}, rightLeg={(animator != null ? animator.BoundRightLegWorldPosition.ToString("F3") : "missing")}, soleContact={(contactRepair != null ? contactRepair.SoleContactDiagnostics : "missing repair")}.");
                    }
                    if (SessionState.GetBool(Candidate310DiagnosticKey, false))
                    {
                        LogCandidateSkinBounds();
                    }
                    var focusedMiteName = SessionState.GetString(FocusObjectKey, string.Empty);
                    if (focusedMiteName.StartsWith("ART_ScrapMite_", System.StringComparison.Ordinal))
                    {
                        var focusedMiteObject = GameObject.Find(focusedMiteName);
                        var focusedMite = focusedMiteObject != null
                            ? focusedMiteObject.GetComponent<SpaceAndCrafts.AI.ScrapMite>() : null;
                        Debug.Log($"[Space & Crafts] ScrapMite animation state: name={focusedMiteName}, alert={(focusedMite != null ? focusedMite.AlertWeightForDiagnostics : -1f):F2}, attackTelegraph={(focusedMite != null ? focusedMite.AttackTelegraphWeightForDiagnostics : -1f):F2}, contactFlinch={(focusedMite != null ? focusedMite.ContactFlinchWeightForDiagnostics : -1f):F2}, leftPupilOffset={(focusedMite != null ? focusedMite.LeftPupilGazeOffsetForDiagnostics.ToString("F3") : "missing")}, rightPupilOffset={(focusedMite != null ? focusedMite.RightPupilGazeOffsetForDiagnostics.ToString("F3") : "missing")}, eyeBlink={(focusedMite != null ? focusedMite.EyeBlinkWeightForDiagnostics : -1f):F2}, position={(focusedMiteObject != null ? focusedMiteObject.transform.position.ToString("F3") : "missing")}.");
                        if (focusedMite != null)
                        {
                            var groundField = typeof(SpaceAndCrafts.AI.ScrapMite).GetField("_groundY",
                                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                            var groundY = groundField != null ? (float)groundField.GetValue(focusedMite) : float.NaN;
                            foreach (var renderer in focusedMite.GetComponentsInChildren<Renderer>(true))
                            {
                                if (renderer != null && renderer.enabled && renderer.gameObject.activeInHierarchy
                                    && renderer.name.Contains("MiteBody"))
                                {
                                    var meshFilter = renderer.GetComponent<MeshFilter>();
                                    var bodyMesh = meshFilter != null ? meshFilter.sharedMesh : null;
                                    var geometryBottom = float.PositiveInfinity;
                                    if (bodyMesh != null)
                                    {
                                        var vertices = bodyMesh.vertices;
                                        for (var vertexIndex = 0; vertexIndex < vertices.Length; vertexIndex++)
                                        {
                                            geometryBottom = Mathf.Min(geometryBottom,
                                                renderer.transform.TransformPoint(vertices[vertexIndex]).y);
                                        }
                                    }
                                    Debug.Log($"[Space & Crafts] ScrapMite body contact sample: {renderer.name}, boundsBottom={renderer.bounds.min.y:F3}, meshVertexBottom={(float.IsPositiveInfinity(geometryBottom) ? float.NaN : geometryBottom):F3}, groundY={groundY:F3}, boundsGap={renderer.bounds.min.y - groundY:F3}m, meshGap={(float.IsPositiveInfinity(geometryBottom) ? float.NaN : geometryBottom - groundY):F3}m, lossyScale={renderer.transform.lossyScale.ToString("F3")}.");
                                }
                            }
                            foreach (var leg in focusedMite.GetComponentsInChildren<Transform>(true))
                            {
                                if (leg == null || !leg.name.StartsWith("ART_MiteLeg_", System.StringComparison.Ordinal)) continue;
                                var renderers = leg.GetComponentsInChildren<Renderer>(true);
                                var lowest = float.PositiveInfinity;
                                foreach (var renderer in renderers)
                                {
                                    if (renderer != null && renderer.enabled && renderer.gameObject.activeInHierarchy)
                                        lowest = Mathf.Min(lowest, renderer.bounds.min.y);
                                }
                                Debug.Log($"[Space & Crafts] ScrapMite animation foot sample: {leg.name}, bottom={lowest:F3}, groundY={groundY:F3}, gap={lowest - groundY:F3}m.");
                            }
                        }
                    }
                    var focusedRollerObject = GameObject.Find(SessionState.GetString(FocusObjectKey, "ART_ScrapRoller"));
                    var focusedRoller = focusedRollerObject != null
                        ? focusedRollerObject.GetComponentInParent<SpaceAndCrafts.AI.ScrapRoller>() : null;
                    if (focusedRollerObject != null)
                    {
                        Debug.Log($"[Space & Crafts] ScrapRoller attack state: windup={focusedRoller?.WindupProgressForDiagnostics ?? -1f:F2}, windingUp={focusedRoller?.IsWindingUpForDiagnostics ?? false}, charging={focusedRoller?.IsChargingForDiagnostics ?? false}, rootEuler={focusedRollerObject.transform.eulerAngles:F1}, visualEuler={focusedRoller?.ChargeVisualLocalEulerForDiagnostics ?? Vector3.zero:F1}, position={focusedRollerObject.transform.position:F3}.");
                    }
                    var focusedSpitterName = SessionState.GetString(FocusObjectKey, string.Empty);
                    if (focusedSpitterName.StartsWith("ART_ScrapSpitter_", System.StringComparison.Ordinal))
                    {
                        var focusedSpitterObject = GameObject.Find(focusedSpitterName);
                        var focusedSpitter = focusedSpitterObject != null
                            ? focusedSpitterObject.GetComponent<SpaceAndCrafts.AI.ScrapSpitter>() : null;
                        Debug.Log($"[Space & Crafts] ScrapSpitter attack state: name={focusedSpitterName}, windup={(focusedSpitter != null ? focusedSpitter.WindupWeight : -1f):F2}, recoil={(focusedSpitter != null ? focusedSpitter.RecoilWeight : -1f):F2}, position={(focusedSpitterObject != null ? focusedSpitterObject.transform.position.ToString("F3") : "missing")}.");
                    }
                    Debug.Log($"[Space & Crafts] Rendered Arrival game camera: {output}");
                }

                var captureFrame = SessionState.GetInt(CaptureFrameKey, -1);
                if (captureFrame >= 0 && frame >= captureFrame + 45)
                {
                    EditorApplication.isPlaying = false;
                }

                return;
            }

            if (EditorApplication.isPlayingOrWillChangePlaymode)
            {
                return;
            }

            if (SessionState.GetBool(CapturedKey, false))
            {
                Finish();
                return;
            }

            if (frame > 1800)
            {
                Debug.LogError("Arrival visual capture timed out before reaching Play Mode.");
                SessionState.SetBool(ActiveKey, false);
                EditorApplication.Exit(3);
            }
        }

        private const string SecretBadgeStagedKey = "SpaceAndCrafts.ArrivalVisualCapture.SecretBadgeStaged";

        private static void StageSecretBadgeCapture()
        {
            var nook = GameObject.Find("TEMP_ART_Zone_SecretNook");
            var pickup = nook != null ? nook.transform.Find("ART_Pickup_discovery_badge_secret_nook") : null;
            if (pickup == null) throw new System.Exception("Secret nook badge model is missing from capture scene");
            pickup.gameObject.SetActive(true);
            var transforms = pickup.GetComponentsInChildren<Transform>(true);
            for (var i = 0; i < transforms.Length; i++) transforms[i].gameObject.SetActive(true);
            var tempLabel = pickup.Find("TEMP_ART_LABEL_Pickup_Curious_Nook_Badge");
            if (tempLabel != null) tempLabel.gameObject.SetActive(false);
            var behaviours = pickup.GetComponents<MonoBehaviour>();
            for (var i = 0; i < behaviours.Length; i++) behaviours[i].enabled = false;
            var renderers = pickup.GetComponentsInChildren<Renderer>(true);
            for (var i = 0; i < renderers.Length; i++) renderers[i].enabled = true;
            var colliders = pickup.GetComponentsInChildren<Collider>(true);
            for (var i = 0; i < colliders.Length; i++) colliders[i].enabled = false;
            SessionState.SetBool(SecretBadgeStagedKey, true);
            Debug.Log($"[Space & Crafts] Capture-only badge visual staged with {renderers.Length} renderers enabled and {colliders.Length} colliders disabled.");
        }

        private static void LogPinkRendererDiagnostics()
        {
            var renderers = Object.FindObjectsByType<Renderer>(FindObjectsInactive.Exclude);
            var hits = 0;
            for (var i = 0; i < renderers.Length; i++)
            {
                var renderer = renderers[i];
                if (renderer == null || !renderer.enabled || !renderer.gameObject.activeInHierarchy) continue;
                var materials = renderer.sharedMaterials;
                for (var m = 0; m < materials.Length; m++)
                {
                    var material = materials[m];
                    if (material == null)
                    {
                        Debug.LogWarning($"[World 01 pink audit] Missing material slot: renderer={GetPath(renderer.transform)}, slot={m}, boundsCenter={renderer.bounds.center:F2}.");
                        hits++;
                        continue;
                    }

                    var shader = material.shader;
                    var shaderName = shader != null ? shader.name : "<missing shader>";
                    var baseColor = material.HasProperty("_BaseColor") ? material.GetColor("_BaseColor")
                        : material.HasProperty("_Color") ? material.GetColor("_Color") : Color.white;
                    var errorShader = shader == null || !shader.isSupported
                        || shaderName.IndexOf("InternalError", System.StringComparison.OrdinalIgnoreCase) >= 0;
                    var magentaColor = baseColor.r > 0.78f && baseColor.b > 0.78f && baseColor.g < 0.38f;
                    if (!errorShader && !magentaColor) continue;
                    Debug.Log($"[World 01 pink audit] renderer={GetPath(renderer.transform)}, slot={m}, material={material.name}, shader={shaderName}, supported={(shader != null && shader.isSupported)}, baseColor={baseColor:F3}, boundsCenter={renderer.bounds.center:F2}, boundsSize={renderer.bounds.size:F2}.");
                    hits++;
                }
            }
            Debug.Log($"[World 01 pink audit] Diagnostic finished; reported {hits} suspect material slots from {renderers.Length} renderers.");
        }

        private static string GetPath(Transform transform)
        {
            if (transform == null) return "<missing>";
            var path = transform.name;
            for (var parent = transform.parent; parent != null; parent = parent.parent)
                path = parent.name + "/" + path;
            return path;
        }

        private static void PlaceSplatOnPlatform(string platformName)
        {
            var hero = GameObject.Find("Splat_TEMP");
            var platform = GameObject.Find(platformName);
            if (hero == null || platform == null)
            {
                Debug.LogWarning($"[Space & Crafts] Platform contact capture could not place Splat: hero={(hero != null)}, platform={(platform != null)}.");
                return;
            }

            if (SessionState.GetBool(CaptureNeutralizeInputKey, false))
            {
                var motor = hero.GetComponent<SplatMotor>();
                var inputField = motor != null
                    ? typeof(SplatMotor).GetField("input", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                    : null;
                var inputReader = motor != null && inputField != null
                    ? inputField.GetValue(motor) as SplatInputReader : hero.GetComponent<SplatInputReader>();
                if (inputReader != null)
                {
                    inputReader.DebugClear();
                    inputReader.DebugSetMove(Vector2.zero);
                    Debug.Log($"[Space & Crafts] Neutralized motor input for staged platform-contact capture: reader={inputReader.name}.");
                }
                else
                {
                    Debug.LogWarning("[Space & Crafts] Could not neutralize input: SplatInputReader missing.");
                }
            }

            var collider = platform.GetComponent<Collider>();
            var controller = hero.GetComponent<CharacterController>();
            if (collider == null || controller == null)
            {
                Debug.LogWarning($"[Space & Crafts] Platform contact capture lacks collider or CharacterController: collider={(collider != null)}, controller={(controller != null)}.");
                return;
            }

            if (SessionState.GetBool(DisableTeachPadsForCaptureKey, false))
            {
                var teachPads = Object.FindObjectsByType<SpaceAndCrafts.Gameplay.InventionTeachPad>();
                for (var i = 0; i < teachPads.Length; i++)
                    if (teachPads[i] != null) teachPads[i].enabled = false;
                var boingItems = Object.FindObjectsByType<SpaceAndCrafts.Crafting.BoingOMatic>();
                for (var i = 0; i < boingItems.Length; i++)
                    if (boingItems[i] != null) boingItems[i].enabled = false;
                // Suppress hostiles before the staged teleport, not only when the
                // later isolated-camera setup runs; their first overlap can launch
                // Splat and invalidate an otherwise grounded idle sample.
                SilenceNonFocusEnemies(hero);
                Debug.Log($"[Space & Crafts] Disabled {teachPads.Length} invention teaching triggers and {boingItems.Length} Boing-O-Matic triggers for isolated retarget contact capture.");
            }

            var heroPosition = hero.transform.position;
            heroPosition.x = collider.bounds.center.x;
            heroPosition.z = collider.bounds.center.z;
            var supportY = collider.bounds.max.y;
            var supportRay = new Ray(new Vector3(collider.bounds.center.x,
                collider.bounds.max.y + 1f, collider.bounds.center.z), Vector3.down);
            var supportDistance = collider.bounds.size.y + 2f;
            if (collider.Raycast(supportRay, out var supportHit, supportDistance)
                && supportHit.normal.y >= 0.65f)
            {
                supportY = supportHit.point.y;
            }
            var centerSupportY = supportY;
            if (SessionState.GetBool(CaptureNeutralizeInputKey, false)
                && SessionState.GetVector3(CapturePlatformEulerOffsetKey, Vector3.zero).sqrMagnitude > 0.0001f)
            {
                // An upright CharacterController spans a horizontal footprint. On a
                // tilted support its uphill rim can intersect the slope even when
                // the capsule bottom is placed at the collider's center height.
                // Seat this capture-only spawn against the highest walkable point
                // beneath that footprint, then let runtime grounding settle it.
                var radius = controller.radius * Mathf.Max(hero.transform.lossyScale.x,
                    hero.transform.lossyScale.z) * 0.9f;
                for (var probeIndex = 0; probeIndex < 8; probeIndex++)
                {
                    var angle = probeIndex * (Mathf.PI * 0.25f);
                    var probeX = collider.bounds.center.x + Mathf.Cos(angle) * radius;
                    var probeZ = collider.bounds.center.z + Mathf.Sin(angle) * radius;
                    var probe = new Ray(new Vector3(probeX, collider.bounds.max.y + 1f, probeZ), Vector3.down);
                    if (collider.Raycast(probe, out var footprintHit, supportDistance)
                        && footprintHit.normal.y >= 0.65f)
                    {
                        supportY = Mathf.Max(supportY, footprintHit.point.y);
                    }
                }
                // Start just above the sampled slope so CharacterController.Move
                // enters contact while descending instead of beginning overlapped
                // with the uphill side of its lower capsule hemisphere.
                supportY += controller.skinWidth;
            }
            heroPosition.y = supportY - controller.center.y + controller.height * 0.5f;
            controller.enabled = false;
            hero.transform.position = heroPosition;
            controller.enabled = true;
            if (SessionState.GetBool(CaptureNeutralizeInputKey, false))
            {
                hero.GetComponent<SplatMotor>()?.HardResetState();
                var inputReader = hero.GetComponent<SplatInputReader>();
                var motor = hero.GetComponent<SplatMotor>();
                Debug.Log($"[Space & Crafts] Neutral capture state after placement: groundPound={(motor != null && motor.IsGroundPounding)}, move={(inputReader != null ? inputReader.Move.ToString("F2") : "missing")}, jump={(inputReader != null && inputReader.JumpPressedThisFrame)}.");
            }
            if (SessionState.GetBool(TurnPlatformCaptureRightKey, false))
            {
                hero.transform.rotation = Quaternion.LookRotation(Vector3.right, Vector3.up);
            }
            Physics.SyncTransforms();
            Debug.Log($"[Space & Crafts] Placed Splat over {platform.name}: centerSupportY={centerSupportY:F4}, capsuleSpawnY={supportY:F4}, controllerBottom={controller.bounds.min.y:F4}, supportNormal={(supportHit.normal).ToString("F3")}, bounds={collider.bounds.size.ToString("F2")}.");
            var surfaceRenderers = platform.GetComponentsInChildren<Renderer>(true);
            for (var i = 0; i < surfaceRenderers.Length; i++)
            {
                var renderer = surfaceRenderers[i];
                if (renderer != null && renderer.enabled && renderer.gameObject.activeInHierarchy)
                {
                    Debug.Log($"[Space & Crafts] Platform surface renderer: platform={platform.name}, renderer={renderer.name}, boundsTop={renderer.bounds.max.y:F4}, boundsBottom={renderer.bounds.min.y:F4}, boundsSize={renderer.bounds.size.ToString("F3")}.");
                }
            }
        }

        private static void StageSplatForScrapRollerCapture()
        {
            // Resolve by the AI component instead of the presentation child name.
            // Arrival may have multiple similarly named scene/prefab variants, and
            // a visual-only Meshy showcase object must never pass as the actor.
            var focusName = SessionState.GetString(FocusObjectKey, "ART_ScrapRoller");
            var visual = GameObject.Find(focusName);
            var roller = visual != null
                ? visual.GetComponentInParent<SpaceAndCrafts.AI.ScrapRoller>()
                : null;
            roller ??= Object.FindAnyObjectByType<SpaceAndCrafts.AI.ScrapRoller>();
            var motor = Object.FindAnyObjectByType<SplatMotor>();
            if (roller == null)
            {
                Debug.LogWarning($"[Space & Crafts] Could not stage roller aggro capture: live ScrapRoller component was missing (SplatMotor={(motor != null)}).");
                SessionState.SetBool(FocusAggroStagedKey, true);
                return;
            }

            var stagedPosition = roller.transform.position - Vector3.forward * 3.8f;
            CharacterController controller = null;
            if (motor != null)
            {
                controller = motor.GetComponent<CharacterController>();
                if (controller != null) controller.enabled = false;
                stagedPosition.y = motor.transform.position.y;
                motor.transform.SetPositionAndRotation(stagedPosition, Quaternion.LookRotation(Vector3.forward, Vector3.up));
                motor.enabled = false;
            }
            else
            {
                // Some Arrival captures load the enemy showcase without the
                // player bootstrap. Use a capture-only target to drive the real
                // AI state machine rather than rendering an unanimated display mesh.
                var target = new GameObject("Capture_ScrapRollerTarget");
                target.transform.position = stagedPosition;
                var splatField = typeof(SpaceAndCrafts.AI.ScrapRoller).GetField("_splat",
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                if (splatField != null) splatField.SetValue(roller, target.transform);
            }
            var chargeTimer = typeof(SpaceAndCrafts.AI.ScrapRoller).GetField("_nextCharge",
                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
            if (chargeTimer != null) chargeTimer.SetValue(roller, Time.time);
            if (controller != null) controller.enabled = false;
            Physics.SyncTransforms();
            Debug.Log($"[Space & Crafts] Staged {(motor != null ? "Splat" : "capture-only target")} for the live ScrapRoller AI at {stagedPosition:F2}; nextChargeAt={(chargeTimer != null ? (float)chargeTimer.GetValue(roller) : -1f):F2}.");
            SessionState.SetFloat(FocusAggroStagedAtKey, Time.time);
            SessionState.SetBool(FocusAggroStagedKey, true);
        }

        private static void StageScrapRollerIdleCapture()
        {
            var focusName = SessionState.GetString(FocusObjectKey, "ART_ScrapRoller");
            var focusObject = GameObject.Find(focusName);
            var roller = focusObject != null
                ? focusObject.GetComponentInParent<SpaceAndCrafts.AI.ScrapRoller>()
                : null;
            roller ??= Object.FindAnyObjectByType<SpaceAndCrafts.AI.ScrapRoller>();
            if (roller == null)
            {
                Debug.LogWarning("[Space & Crafts] Could not stage Roller idle capture: live ScrapRoller component was missing.");
                SessionState.SetBool(FocusAggroStagedKey, true);
                return;
            }

            var motor = Object.FindAnyObjectByType<SplatMotor>();
            if (motor != null)
            {
                var controller = motor.GetComponent<CharacterController>();
                if (controller != null) controller.enabled = false;
                var remoteTarget = roller.transform.position - Vector3.forward * 14f;
                remoteTarget.y = motor.transform.position.y;
                motor.transform.SetPositionAndRotation(remoteTarget,
                    Quaternion.LookRotation(Vector3.forward, Vector3.up));
                motor.enabled = false;
            }

            // Add a second copy only to this transient capture scene so the
            // per-instance idle phase can be observed side by side. Its Awake
            // initializes a fresh phase and the moved player remains outside range.
            var second = Object.Instantiate(roller.gameObject,
                roller.transform.position + Vector3.right * 2.6f, roller.transform.rotation);
            second.name = "Capture_SecondScrapRollerIdle";
            var secondRoller = second.GetComponent<SpaceAndCrafts.AI.ScrapRoller>();
            Debug.Log($"[Space & Crafts] Staged two stationary Rollers for idle phase comparison: first={roller.IdlePhaseOffsetForDiagnostics:F2}, second={(secondRoller != null ? secondRoller.IdlePhaseOffsetForDiagnostics : -1f):F2}, Splat moved outside notice range.");
            Physics.SyncTransforms();
            SessionState.SetFloat(FocusIdleStagedAtKey, Time.time);
            SessionState.SetBool(FocusIdleStagedKey, true);
            SessionState.SetBool(FocusAggroStagedKey, true);
        }

        private static bool IsScrapMiteFocus(string name)
        {
            return name == "ART_ScrapMite"
                || (!string.IsNullOrEmpty(name) && name.StartsWith("ART_ScrapMite_", System.StringComparison.Ordinal));
        }

        private static void StageScrapMiteIdleCapture()
        {
            var focusName = SessionState.GetString(FocusObjectKey, "ART_ScrapMite_6");
            var miteObject = GameObject.Find(focusName);
            var mite = miteObject != null ? miteObject.GetComponent<SpaceAndCrafts.AI.ScrapMite>() : null;
            if (mite == null)
            {
                Debug.LogWarning($"[Space & Crafts] Could not stage ScrapMite idle capture: {focusName} or its ScrapMite component was missing.");
                SessionState.SetBool(FocusIdleStagedKey, true);
                return;
            }

            var type = typeof(SpaceAndCrafts.AI.ScrapMite);
            var speedField = type.GetField("moveSpeed", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
            var targetField = type.GetField("_target", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
            speedField?.SetValue(mite, 0f);
            // Do not use the exact root as a waypoint: Update sees that waypoint
            // as already reached and immediately replaces it with a patrol end.
            // A short stationary offset keeps the intended idle staging stable.
            var idleTarget = mite.transform.position + mite.transform.forward * 0.3f;
            targetField?.SetValue(mite, idleTarget);
            Debug.Log($"[Space & Crafts] Staged {mite.name} in its existing stationary idle animator at {mite.transform.position:F2} with parked target {idleTarget:F2} for phase comparison.");
            if (SessionState.GetBool(MiteNearIdlePlayerCameraKey, false))
            {
                var motor = Object.FindAnyObjectByType<SplatMotor>();
                if (motor != null)
                {
                    var towardMite = mite.transform.position - motor.transform.position;
                    towardMite.y = 0f;
                    if (towardMite.sqrMagnitude < 0.001f) towardMite = mite.transform.forward;
                    var stagedPosition = mite.transform.position - towardMite.normalized * 5.1f;
                    stagedPosition.y = motor.transform.position.y;
                    var controller = motor.GetComponent<CharacterController>();
                    var controllerWasEnabled = controller != null && controller.enabled;
                    if (controllerWasEnabled) controller.enabled = false;
                    // The imported Splat mesh's painted face points opposite its
                    // root's local forward axis. Keep the game-camera yaw looking
                    // toward the Mite, while orienting the character mesh toward it.
                    motor.transform.SetPositionAndRotation(stagedPosition,
                        Quaternion.LookRotation(-towardMite.normalized, Vector3.up));
                    if (controllerWasEnabled) controller.enabled = true;
                    motor.HardResetState();
                    Physics.SyncTransforms();
                    var cameraRig = Object.FindAnyObjectByType<SpaceAndCrafts.Cameras.PlatformingCameraRig>();
                    if (cameraRig != null)
                    {
                        var cameraFlags = System.Reflection.BindingFlags.Instance
                            | System.Reflection.BindingFlags.NonPublic;
                        typeof(SpaceAndCrafts.Cameras.PlatformingCameraRig).GetField("_yaw", cameraFlags)
                            ?.SetValue(cameraRig, Quaternion.LookRotation(towardMite.normalized,
                                Vector3.up).eulerAngles.y);
                        typeof(SpaceAndCrafts.Cameras.PlatformingCameraRig).GetField("_followVelocity", cameraFlags)
                            ?.SetValue(cameraRig, Vector3.zero);
                        cameraRig.transform.position = motor.transform.position;
                    }
                    var horizontalGap = Vector3.Distance(
                        new Vector3(motor.transform.position.x, 0f, motor.transform.position.z),
                        new Vector3(mite.transform.position.x, 0f, mite.transform.position.z));
                    Debug.Log($"[Space & Crafts] Capture-only near-idle player staging: Splat={motor.transform.position:F2}, Mite={mite.transform.position:F2}, horizontalGap={horizontalGap:F2}m, encounterYaw={(cameraRig != null ? cameraRig.transform.eulerAngles.y.ToString("F1") : "missing")}; Mite noticeRadius remains unchanged.");
                }
                else
                {
                    Debug.LogWarning("[Space & Crafts] Near-idle player-camera capture requested, but SplatMotor was missing.");
                }
            }
            SessionState.SetFloat(FocusIdleStagedAtKey, Time.time);
            var groundField = type.GetField("_groundY", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
            var groundY = groundField != null ? (float)groundField.GetValue(mite) : float.NaN;
            var renderers = mite.GetComponentsInChildren<Renderer>(true);
            for (var i = 0; i < renderers.Length; i++)
            {
                var renderer = renderers[i];
                if (renderer != null && renderer.enabled && renderer.gameObject.activeInHierarchy)
                {
                    Debug.Log($"[Space & Crafts] ScrapMite seated-renderer sample: {renderer.name}, bottom={renderer.bounds.min.y:F3}, groundY={groundY:F3}, rootY={mite.transform.position.y:F3}.");
                }
            }
            SessionState.SetBool(FocusIdleStagedKey, true);
        }

