        private static void StageScrapStormPhaseMiteCapture()
        {
            SessionState.SetBool(BossPhaseMiteCaptureKey, false);
            var bossObject = GameObject.Find("ART_ScrapStormSentinel");
            var boss = bossObject != null
                ? bossObject.GetComponent<SpaceAndCrafts.AI.ScrapStormSentinel>() : null;
            var spawn = boss != null
                ? typeof(SpaceAndCrafts.AI.ScrapStormSentinel).GetMethod("SpawnPhaseMites",
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                : null;
            if (spawn == null)
            {
                Debug.LogError("[Space & Crafts] Could not stage the boss-phase spider capture; sentinel or SpawnPhaseMites was missing.");
                return;
            }

            spawn.Invoke(boss, new object[] { 1 });
            var miteObject = GameObject.Find("ART_ScrapMite_Phase1_0");
            var contactTrigger = miteObject != null ? miteObject.GetComponent<Collider>() : null;
            if (contactTrigger != null && contactTrigger.isTrigger)
            {
                // The scripted attack capture deliberately parks Splat close to the
                // Mite; keep that editor-only overlap from registering a real stomp.
                contactTrigger.enabled = false;
            }
            var visual = miteObject != null ? miteObject.transform.Find("ART_MeshyEnemyVisual") : null;
            var driver = visual != null
                ? visual.GetComponentInChildren<SpaceAndCrafts.AI.RainbowSpiderAnimatorDriver>(true) : null;
            var skinnedRenderer = visual != null
                ? visual.GetComponentInChildren<SkinnedMeshRenderer>(true) : null;
            var motor = Object.FindAnyObjectByType<SplatMotor>();
            var splatRenderers = motor != null ? motor.GetComponentsInChildren<Renderer>(true) : System.Array.Empty<Renderer>();
            for (var i = 0; i < splatRenderers.Length; i++)
            {
                if (splatRenderers[i] != null) splatRenderers[i].enabled = false;
            }
            Debug.Log($"[Space & Crafts] Staged actual Scrap Storm Sentinel phase reinforcement: root={(miteObject != null ? miteObject.name : "missing")}, visual={(visual != null ? visual.name : "missing")}, skinned={(skinnedRenderer != null)}, driver={(driver != null)}, captureContactTriggerDisabled={(contactTrigger != null && contactTrigger.isTrigger && !contactTrigger.enabled)}, splatRenderersHidden={splatRenderers.Length}.");
        }

