        private static void StageScrapSpitterCapture()
        {
            var focusName = SessionState.GetString(SpitterFocusObjectKey, string.Empty);
            if (string.IsNullOrEmpty(focusName))
                focusName = SessionState.GetString(FocusObjectKey, "ART_ScrapSpitter_0");
            var spitterObject = GameObject.Find(focusName);
            var spitter = spitterObject != null ? spitterObject.GetComponent<SpaceAndCrafts.AI.ScrapSpitter>() : null;
            var motor = Object.FindAnyObjectByType<SplatMotor>();
            if (spitter == null || motor == null)
            {
                Debug.LogWarning("[Space & Crafts] Could not stage the ScrapSpitter animation capture: spitter or Splat motor missing.");
                SessionState.SetBool(FocusAggroStagedKey, true);
                return;
            }

            var target = spitter.transform.position + spitter.transform.forward * 6f;
            var controller = motor.GetComponent<CharacterController>();
            var jumpHitCapture = SessionState.GetBool(SpitterJumpHitResponseCaptureKey, false);
            if (SessionState.GetBool(SpitterHitResponseCaptureKey, false))
            {
                // Keep this visual review grounded on the already selected
                // traversal pad and let the real motor perform the knockback.
                // Other isolated projectile captures retain their fixed-air staging.
                target = motor.transform.position;
                var spitterPosition = jumpHitCapture
                    ? target + new Vector3(-2f, 1f, 0f)
                    : target + new Vector3(-5f, 1.65f, 0f);
                spitter.Configure(spitterPosition);
                var towardPlayer = target - spitter.transform.position;
                towardPlayer.y = 0f;
                if (towardPlayer.sqrMagnitude > 0.001f)
                    spitter.transform.rotation = Quaternion.LookRotation(towardPlayer.normalized, Vector3.up);
                motor.HardResetState();
                motor.enabled = true;
                if (controller != null) controller.enabled = true;
            }
            else
            {
                motor.transform.SetPositionAndRotation(target,
                    Quaternion.LookRotation(-spitter.transform.forward, Vector3.up));
                motor.enabled = false;
                if (controller != null) controller.enabled = false;
            }

            var type = typeof(SpaceAndCrafts.AI.ScrapSpitter);
            type.GetField("_splat", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                ?.SetValue(spitter, motor.transform);
            var nextFire = type.GetField("_nextFire", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
            var shotDelay = SessionState.GetFloat(SpitterShotDelayKey, 0.58f);
            var windupStarted = type.GetField("_windupStartedAt", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
            if (SessionState.GetBool(SpitterDefeatCaptureKey, false))
            {
                nextFire?.SetValue(spitter, Time.time + 999f);
                windupStarted?.SetValue(spitter, -1f);
                Debug.Log("[Space & Crafts] Staged a harmless idle ScrapSpitter for the defeat-sequence capture.");
            }
            else if (SessionState.GetBool(SpitterWindupCaptureKey, false))
            {
                if (jumpHitCapture)
                {
                    // The jump pulse is sent immediately after sequence frame 0.
                    // Preload the existing charge so this short shot reaches the
                    // airborne player instead of arriving after the jump lands.
                    nextFire?.SetValue(spitter, Time.time + shotDelay);
                    windupStarted?.SetValue(spitter, Time.time - 0.4f);
                    Debug.Log("[Space & Crafts] Precharged ScrapSpitter for a midair hit capture; release is scheduled 0.30s after staging.");
                }
                else if (SessionState.GetBool(SpitterDelayedWindupCaptureKey, false))
                {
                    // Leave enough pre-roll for the sequence recorder to begin
                    // before the live AI starts its charge. Starting the clock
                    // here made the ramp finish during Play Mode staging.
                    nextFire?.SetValue(spitter, Time.time + shotDelay);
                    windupStarted?.SetValue(spitter, -1f);
                    Debug.Log($"[Space & Crafts] Staged ScrapSpitter idle pre-roll, then windup and one live shot after {shotDelay:F2}s.");
                }
                else
                {
                    // Let the live AI show the whole anticipation-to-shot transition.
                    // The earlier in-flight-shot staging fired before the sequence,
                    // so its frames missed the windup and showed a mostly idle sphere.
                    nextFire?.SetValue(spitter, Time.time + shotDelay);
                    windupStarted?.SetValue(spitter, Time.time);
                    Debug.Log($"[Space & Crafts] Staged ScrapSpitter windup from weight 0 to a single live shot after {shotDelay:F2}s.");
                }
            }
            else
            {
                // The original diagnostic route retains its immediate in-flight
                // projectile before staging the following shot.
                type.GetMethod("Fire", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                    ?.Invoke(spitter, null);
                nextFire?.SetValue(spitter, Time.time + shotDelay);
                windupStarted?.SetValue(spitter, Time.time + shotDelay - 0.58f);
            }
            Physics.SyncTransforms();
            Debug.Log($"[Space & Crafts] Staged Splat at {target:F2} for ScrapSpitter in-flight projectile capture; shot delay={shotDelay:F2}s.");
            SessionState.SetFloat(FocusAggroStagedAtKey, Time.time);
            SessionState.SetBool(FocusAggroStagedKey, true);
        }

