        private static void StageScrapStormSentinelWeakPointCapture()
        {
            var sentinelObject = GameObject.Find("ART_ScrapStormSentinel");
            var sentinel = sentinelObject != null
                ? sentinelObject.GetComponent<SpaceAndCrafts.AI.ScrapStormSentinel>() : null;
            var motor = Object.FindAnyObjectByType<SplatMotor>();
            if (sentinel == null || motor == null)
            {
                Debug.LogWarning("[Space & Crafts] Could not stage Sentinel weak-point capture: Sentinel or Splat motor missing.");
                SessionState.SetBool(FocusAggroStagedKey, true);
                return;
            }

            // Keep Splat on the authored Terrace route while inside the boss's
            // activation radius; staging forward of Rattle puts the player over water.
            var terracePad = GameObject.Find("TEMP_ART_TerraceBoingOMatic");
            var padTrigger = terracePad != null
                ? terracePad.GetComponentInChildren<BoingOMatic>(true)?.GetComponent<Collider>() : null;
            var target = sentinel.transform.position - sentinel.transform.forward * 5f;
            if (padTrigger != null)
            {
                var padPosition = padTrigger.bounds.center;
                var towardBoss = sentinel.transform.position - padPosition;
                towardBoss.y = 0f;
                var closerPosition = padPosition + towardBoss.normalized * 1.5f;
                var rayOrigin = closerPosition + Vector3.up * 8f;
                if (Physics.Raycast(rayOrigin, Vector3.down, out var groundHit, 20f,
                        Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore))
                {
                    target = groundHit.point + Vector3.up * 0.05f;
                }
                else
                {
                    target = padPosition + Vector3.up * 0.15f;
                }
            }
            motor.transform.SetPositionAndRotation(target,
                Quaternion.LookRotation(sentinel.transform.position - target, Vector3.up));
            if (SessionState.GetBool(PreserveSceneCameraKey, false)
                && !SessionState.GetBool(SentinelSkipGuidedLookCaptureKey, false))
            {
                // Keep the production follow camera, but use its normal guided-look
                // behavior to frame the staged boss encounter after the player move.
                var cameraRig = Object.FindAnyObjectByType<SpaceAndCrafts.Cameras.PlatformingCameraRig>();
                if (cameraRig != null)
                {
                    cameraRig.GuideLookAt(sentinel.transform.position, 14f, 18f);
                }
            }
            motor.enabled = false;
            var controller = motor.GetComponent<CharacterController>();
            if (controller != null) controller.enabled = false;

            sentinel.StopAllCoroutines();
            var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
            typeof(SpaceAndCrafts.AI.ScrapStormSentinel).GetField("_hasInvention", flags)?.SetValue(sentinel, true);
            typeof(SpaceAndCrafts.AI.ScrapStormSentinel).GetField("_busy", flags)?.SetValue(sentinel, false);
            if (SessionState.GetBool(SentinelFinalHitCaptureKey, false))
            {
                var hitsToDefeat = (int)(typeof(SpaceAndCrafts.AI.ScrapStormSentinel)
                    .GetField("hitsToDefeat", flags)?.GetValue(sentinel) ?? 3);
                typeof(SpaceAndCrafts.AI.ScrapStormSentinel).GetField("_hits", flags)
                    ?.SetValue(sentinel, Mathf.Max(0, hitsToDefeat - 1));
            }
            var loop = typeof(SpaceAndCrafts.AI.ScrapStormSentinel).GetMethod("CombatLoop", flags)
                ?.Invoke(sentinel, null) as IEnumerator;
            if (loop == null)
            {
                Debug.LogWarning("[Space & Crafts] Could not restart Sentinel CombatLoop for weak-point capture.");
                SessionState.SetBool(FocusAggroStagedKey, true);
                return;
            }

            sentinel.StartCoroutine(loop);
            SessionState.SetBool(FocusAggroStagedKey, true);
            Debug.Log($"[Space & Crafts] Restarted Sentinel combat with invention enabled; staged player distance={(motor.transform.position - sentinel.transform.position).magnitude:F2}m; capture includes the natural slam-to-weak-point exposure sequence. commissioned={sentinel.UsesCommissionedVisualForDiagnostics}.");
        }

