        private static void StageScrapStormSentinelDefeatCapture()
        {
            var sentinels = Object.FindObjectsByType<SpaceAndCrafts.AI.ScrapStormSentinel>(FindObjectsInactive.Include);
            SpaceAndCrafts.AI.ScrapStormSentinel sentinel = null;
            for (var i = 0; i < sentinels.Length; i++)
            {
                if (sentinels[i] != null && sentinels[i].gameObject.name == "ART_ScrapStormSentinel")
                {
                    sentinel = sentinels[i];
                    break;
                }
            }

            var motors = Object.FindObjectsByType<SplatMotor>(FindObjectsInactive.Include);
            SplatMotor motor = null;
            for (var i = 0; i < motors.Length; i++)
            {
                if (motors[i] != null && motors[i].CompareTag("Player"))
                {
                    motor = motors[i];
                    break;
                }
            }

            if (sentinel == null || motor == null)
            {
                if (Time.frameCount % 30 == 0)
                {
                    Debug.LogWarning($"[Space & Crafts] Waiting to stage ScrapStormSentinel defeat capture: sentinel={(sentinel != null)}, playerMotor={(motor != null)}, sceneFrame={Time.frameCount}.");
                }

                // Keep retrying while the scene's runtime setup finishes. The
                // prior path latched this state as staged after one miss and
                // silently produced an ordinary Arrival image.
                return;
            }

            for (var parent = sentinel.transform; parent != null; parent = parent.parent)
            {
                if (!parent.gameObject.activeSelf)
                {
                    parent.gameObject.SetActive(true);
                }
            }
            for (var parent = motor.transform; parent != null; parent = parent.parent)
            {
                if (!parent.gameObject.activeSelf)
                {
                    parent.gameObject.SetActive(true);
                }
            }
            var sentinelObject = sentinel.gameObject;

            var terracePad = GameObject.Find("TEMP_ART_TerraceBoingOMatic");
            var padTrigger = terracePad != null
                ? terracePad.GetComponentInChildren<BoingOMatic>(true)?.GetComponent<Collider>() : null;
            var target = sentinel.transform.position - sentinel.transform.forward * 3.5f;
            if (padTrigger != null)
            {
                var padPosition = padTrigger.bounds.center;
                var towardBoss = sentinel.transform.position - padPosition;
                towardBoss.y = 0f;
                var candidate = padPosition + towardBoss.normalized * 1.1f;
                var rayOrigin = candidate + Vector3.up * 8f;
                if (Physics.Raycast(rayOrigin, Vector3.down, out var groundHit, 20f,
                        Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore))
                {
                    target = groundHit.point + Vector3.up * 0.05f;
                }
                else
                {
                    target = padPosition + Vector3.up * 0.15f;
                }
            }

            var toPlayer = target - sentinel.transform.position;
            toPlayer.y = 0f;
            if (toPlayer.sqrMagnitude > 0.01f)
            {
                sentinel.transform.rotation = Quaternion.LookRotation(toPlayer.normalized, Vector3.up);
            }
            motor.transform.SetPositionAndRotation(target,
                Quaternion.LookRotation(-sentinel.transform.forward, Vector3.up));
            motor.enabled = false;
            var controller = motor.GetComponent<CharacterController>();
            if (controller != null) controller.enabled = false;

            var sentinelType = typeof(SpaceAndCrafts.AI.ScrapStormSentinel);
            sentinel.StopAllCoroutines();
            var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
            sentinelType.GetField("_hasInvention", flags)
                ?.SetValue(sentinel, true);
            // Stage the prior hits as an already-escalated encounter. Otherwise
            // the injected final hit replays the phase-three mite spawn and
            // surge, burying the actual defeat/fanfare review under fresh adds.
            sentinelType.GetField("_phase", flags)?.SetValue(sentinel, 3);
            var hitsField = sentinelType.GetField("_hits", flags);
            var defeatThreshold = sentinelType.GetField("hitsToDefeat", flags);
            var hitsToDefeat = defeatThreshold != null ? (int)defeatThreshold.GetValue(sentinel) : 3;
            hitsField?.SetValue(sentinel, Mathf.Max(0, hitsToDefeat - 1));
            sentinel.NotifyWeakPointHit();
            Physics.SyncTransforms();
            SessionState.SetBool(FocusAggroStagedKey, true);
            Debug.Log($"[Space & Crafts] Staged ScrapStormSentinel defeat release; hit count={hitsToDefeat}, commissioned={sentinel.UsesCommissionedVisualForDiagnostics}.");
        }

        private static void StageScrapFloaterCapture(bool dive, bool idle, bool defeat)
        {
            var floaterObject = GameObject.Find("ART_ScrapFloater");
            var floater = floaterObject != null ? floaterObject.GetComponent<SpaceAndCrafts.AI.ScrapFloater>() : null;
            var motor = Object.FindAnyObjectByType<SplatMotor>();
            if (floater == null || motor == null)
            {
                Debug.LogWarning("[Space & Crafts] Could not stage the ScrapFloater animation capture: floater or Splat motor missing.");
                SessionState.SetBool(FocusAggroStagedKey, true);
                return;
            }

            var sequenceFrameCount = SessionState.GetInt(SequenceFrameCountKey, 0);
            var targetDistance = sequenceFrameCount >= 24 ? 1.0f : 2.5f;
            var target = floater.transform.position + floater.transform.forward * targetDistance;
            motor.transform.SetPositionAndRotation(target, Quaternion.LookRotation(-floater.transform.forward, Vector3.up));
            motor.enabled = false;
            var controller = motor.GetComponent<CharacterController>();
            if (controller != null) controller.enabled = false;
            if (defeat)
            {
                // The live follow rig otherwise overwrites the isolated focus
                // camera between sequence frames, causing the short defeat pose
                // to disappear from view after its first image.
                var cameraRig = Object.FindAnyObjectByType<SpaceAndCrafts.Cameras.PlatformingCameraRig>();
                if (cameraRig != null) cameraRig.enabled = false;
            }

            var type = typeof(SpaceAndCrafts.AI.ScrapFloater);
            type.GetField("_splat", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                ?.SetValue(floater, motor.transform);
            type.GetField("_windingUp", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                ?.SetValue(floater, !dive && !idle);
            type.GetField("_diving", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                ?.SetValue(floater, dive);
            type.GetField("_windupStartedAt", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                ?.SetValue(floater, Time.time);
            type.GetField("_windupUntil", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                ?.SetValue(floater, Time.time + (SessionState.GetInt(SequenceFrameCountKey, 0) > 0 && !dive && !idle
                    ? 0.82f : 2f));
            type.GetField("_windupPosition", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                ?.SetValue(floater, floater.transform.position);
            type.GetField("_diveTarget", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                ?.SetValue(floater, motor.transform.position + Vector3.up * 0.6f);
            type.GetField("_nextBump", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                ?.SetValue(floater, idle ? Time.time + 10f : 0f);
            if (defeat)
            {
                type.GetMethod("Defeat", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                    ?.Invoke(floater, null);
            }
            Physics.SyncTransforms();
            Debug.Log($"[Space & Crafts] Staged Splat for ScrapFloater {(defeat ? "defeat" : dive ? "dive" : idle ? "idle" : "wind-up")} capture at {target:F2}.");
            SessionState.SetFloat(FocusAggroStagedAtKey, Time.time);
            SessionState.SetBool(FocusAggroStagedKey, true);
        }

        private static void InstallCaptureOnlyRainbowSpiderCandidate(GameObject focusObject)
        {
            const string prefabPath = "Assets/SpaceAndCrafts/Art/Commissioned/Enemies/MeshySpenddown/20261101_rainbow-spider-rig-candidate-iter1461/UnityCandidate/RainbowKingdomSpider_AnimatedCandidate.prefab";
            var prefab = AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath);
            var mite = focusObject.GetComponent<SpaceAndCrafts.AI.ScrapMite>();
            if (prefab == null || mite == null)
            {
                Debug.LogWarning($"[Spider candidate capture] Missing prefab or ScrapMite: prefab={prefab != null}, mite={mite != null}.");
                return;
            }

            foreach (var renderer in focusObject.GetComponentsInChildren<Renderer>(true))
                if (renderer != null) renderer.enabled = false;
            foreach (var child in focusObject.GetComponentsInChildren<Transform>(true))
                if (child != focusObject.transform && child.name == "ART_MeshyEnemyVisual")
                    child.gameObject.SetActive(false);

            var instance = Object.Instantiate(prefab, focusObject.transform, false);
            instance.name = "ART_MeshyEnemyVisual";
            instance.transform.localRotation = Quaternion.identity;
            instance.transform.localScale = Vector3.one;
            var animator = instance.GetComponentInChildren<Animator>(true);
            var driver = instance.GetComponentInChildren<SpaceAndCrafts.AI.RainbowSpiderAnimatorDriver>(true);
            var driverWasAddedForCapture = false;
            if (driver == null && animator != null)
            {
                driver = animator.gameObject.AddComponent<SpaceAndCrafts.AI.RainbowSpiderAnimatorDriver>();
                driverWasAddedForCapture = driver != null;
            }
            typeof(SpaceAndCrafts.AI.ScrapMite).GetMethod("CacheVisualRig",
                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
                ?.Invoke(mite, null);
            var spiderSkin = instance.GetComponentInChildren<SkinnedMeshRenderer>(true);
            if (spiderSkin != null)
            {
                Debug.Log($"[Spider candidate capture] Contact bounds: supportY={mite.GroundYForVisuals:F3}, "+
                    $"rendererWorldMinY={spiderSkin.bounds.min.y:F3}, rendererLocalBounds={spiderSkin.localBounds}, "+
                    $"rendererTransform={spiderSkin.transform.position:F3}, "+
                    $"miteReportedGap={mite.CommissionedVisualGroundGapForDiagnostics:F3}m.");
            }
            var spiderFilters = instance.GetComponentsInChildren<MeshFilter>(true);
            for (var filterIndex = 0; filterIndex < spiderFilters.Length; filterIndex++)
            {
                var filter = spiderFilters[filterIndex];
                if (filter == null || filter.sharedMesh == null) continue;
                var mesh = filter.sharedMesh;
                var meshBottom = float.PositiveInfinity;
                var vertices = mesh.vertices;
                for (var vertexIndex = 0; vertexIndex < vertices.Length; vertexIndex++)
                    meshBottom = Mathf.Min(meshBottom, filter.transform.TransformPoint(vertices[vertexIndex]).y);
                Debug.Log($"[Spider candidate capture] Contact mesh {filter.name}: active={filter.gameObject.activeInHierarchy}, "+
                    $"vertices={vertices.Length}, worldMinY={meshBottom:F3}, supportGap={meshBottom - mite.GroundYForVisuals:F3}m.");
            }
            var spiderTransforms = instance.GetComponentsInChildren<Transform>(true);
            var footBoneCount = 0;
            for (var transformIndex = 0; transformIndex < spiderTransforms.Length; transformIndex++)
            {
                var bone = spiderTransforms[transformIndex];
                if (bone != null && bone.name.EndsWith("_IK", System.StringComparison.Ordinal))
                    Debug.Log($"[Spider candidate capture] IK target {bone.name}: world={bone.position:F3}, supportGap={bone.position.y - mite.GroundYForVisuals:F3}m.");
                if (bone == null || !bone.name.EndsWith("_Foot", System.StringComparison.Ordinal)) continue;
                Debug.Log($"[Spider candidate capture] Foot bone {bone.name}: world={bone.position:F3}, supportGap={bone.position.y - mite.GroundYForVisuals:F3}m.");
                footBoneCount++;
            }
            Debug.Log($"[Spider candidate capture] Foot bone count={footBoneCount}.");
            Debug.Log($"[Spider candidate capture] Injected existing Meshy rig into one isolated World 02 Mite: avatarValid={(animator != null && animator.avatar != null && animator.avatar.isValid)}, controller={(animator != null && animator.runtimeAnimatorController != null ? animator.runtimeAnimatorController.name : "missing")}, driver={(driver != null)}, driverAddedForCapture={driverWasAddedForCapture}, renderers={instance.GetComponentsInChildren<Renderer>(true).Length}, scale={instance.transform.lossyScale.ToString("F2")}.");
        }


        private static void PrepareIsolatedFocusCapture(GameObject focusObject)
        {
            if (focusObject == null) return;
            if (SessionState.GetBool(IsolatedFocusPreparedKey, false)) return;
            SessionState.SetBool(IsolatedFocusPreparedKey, true);

            // The boss-only preview can otherwise retain Splat's detached
            // face renderers from the capture rig. Disable the player root in
            // this temporary Play Mode scene so the boss silhouette is clear.
            if (focusObject.GetComponent<SpaceAndCrafts.AI.ScrapStormSentinel>() != null)
            {
                var splat = GameObject.Find("Splat_TEMP");
                if (splat != null) splat.SetActive(false);
            }

            var groundY = focusObject.transform.position.y - 0.05f;
            var hits = Physics.RaycastAll(focusObject.transform.position + Vector3.up * 1.5f,
                Vector3.down, 4f, Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore);
            var bestDistance = float.PositiveInfinity;
            for (var i = 0; i < hits.Length; i++)
            {
                var hit = hits[i];
                if (hit.collider == null || hit.collider.transform == focusObject.transform
                    || hit.collider.transform.IsChildOf(focusObject.transform)) continue;
                if (hit.distance < bestDistance)
                {
                    bestDistance = hit.distance;
                    groundY = hit.point.y;
                }
            }

            var platformName = SessionState.GetString(PlacementPlatformKey, string.Empty);
            var retainedPlatform = string.IsNullOrEmpty(platformName) ? null : GameObject.Find(platformName);
            var keepPlatform = retainedPlatform != null && focusObject.name == "Splat_TEMP";
            if (keepPlatform)
            {
                var platformCollider = retainedPlatform.GetComponent<Collider>();
                if (platformCollider != null) groundY = platformCollider.bounds.max.y;
            }

            if (SessionState.GetBool(MiteIslandPreviewKey, false))
            {
                BuildScrapMiteMeshIslandPreview(focusObject, groundY);
            }
            if (SessionState.GetBool(MiteCommissionedRigCaptureKey, false))
            {
                InstallCaptureOnlyCommissionedMiteRig(focusObject, groundY);
            }
            if (SessionState.GetBool(RainbowSpiderCandidateCaptureKey, false))
            {
                InstallCaptureOnlyRainbowSpiderCandidate(focusObject);
            }

            var renderers = Resources.FindObjectsOfTypeAll<Renderer>();
            for (var i = 0; i < renderers.Length; i++)
            {
                var renderer = renderers[i];
                if (renderer == null || !renderer.gameObject.scene.IsValid()
                    || renderer.gameObject.scene != focusObject.scene) continue;
                var keep = renderer.transform == focusObject.transform
                    || renderer.transform.IsChildOf(focusObject.transform)
                    || focusObject.name.StartsWith("ART_ScrapSpitter_", System.StringComparison.Ordinal)
                        && renderer.GetComponentInParent<SpaceAndCrafts.AI.ScrapSpitProjectile>() != null
                    || keepPlatform && (renderer.transform == retainedPlatform.transform
                        || renderer.transform.IsChildOf(retainedPlatform.transform));
                if (!keep) renderer.enabled = false;
            }

            SilenceNonFocusEnemies(focusObject);

            // Keep the Splat contact captures focused on the feet rather than
            // transient collection VFX already in flight from the loaded scene.
            // These sparks are intentionally disabled only in this Play Mode
            // capture; gameplay and the authored scene remain untouched.
            var pickupArcs = Object.FindObjectsByType<TempPouchPickupArc>();
            for (var i = 0; i < pickupArcs.Length; i++)
            {
                if (pickupArcs[i] != null && pickupArcs[i].gameObject != focusObject
                    && !pickupArcs[i].transform.IsChildOf(focusObject.transform))
                {
                    pickupArcs[i].gameObject.SetActive(false);
                }
            }

            // This neutral stage exists only in the capture's Play Mode scene,
            // which Unity discards on exit; it does not modify the authored world.
            if (!keepPlatform)
            {
                var stage = GameObject.CreatePrimitive(PrimitiveType.Plane);
                stage.name = "CaptureOnly_NeutralGround";
                stage.transform.position = new Vector3(focusObject.transform.position.x, groundY,
                    focusObject.transform.position.z);
                stage.transform.localScale = Vector3.one * 0.5f;
                var stageRenderer = stage.GetComponent<Renderer>();
                var shader = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard");
                if (stageRenderer != null && shader != null)
                {
                    var material = new Material(shader);
                    var neutral = new Color(0.16f, 0.22f, 0.28f);
                    if (material.HasProperty("_BaseColor")) material.SetColor("_BaseColor", neutral);
                    if (material.HasProperty("_Color")) material.SetColor("_Color", neutral);
                    stageRenderer.sharedMaterial = material;
                }
                var stageCollider = stage.GetComponent<Collider>();
                if (stageCollider != null) stageCollider.enabled = false;
            }
            RenderSettings.ambientLight = new Color(0.32f, 0.36f, 0.42f);
            var visibleBottom = float.PositiveInfinity;
            var focusRenderers = focusObject.GetComponentsInChildren<Renderer>(true);
            for (var i = 0; i < focusRenderers.Length; i++)
            {
                if (focusRenderers[i] != null && focusRenderers[i].enabled && focusRenderers[i].gameObject.activeInHierarchy)
                {
                    visibleBottom = Mathf.Min(visibleBottom, focusRenderers[i].bounds.min.y);
                }
            }
            var footGap = float.IsInfinity(visibleBottom) ? float.NaN : visibleBottom - groundY;
            Debug.Log($"[Space & Crafts] Isolated {focusObject.name}: ground={groundY:F3}, visibleBottom={visibleBottom:F3}, footGap={footGap:F3}m; temporary capture stage, authored scene renderers hidden for this Play Mode frame.");
        }

        private static void SilenceNonFocusEnemies(GameObject focusObject)
        {
            // Hiding renderers alone leaves invisible AI and hit colliders active.
            // They can strike Splat during an idle/run pose capture and invalidate
            // the sequence. The Play Mode scene is discarded after capture, so
            // deactivate only non-focus enemy roots for this isolated preview.
            var disabled = 0;
            DisableNonFocusEnemyRoots<SpaceAndCrafts.AI.ScrapMite>(focusObject, ref disabled);
            DisableNonFocusEnemyRoots<SpaceAndCrafts.AI.ScrapRoller>(focusObject, ref disabled);
            DisableNonFocusEnemyRoots<SpaceAndCrafts.AI.ScrapFloater>(focusObject, ref disabled);
            DisableNonFocusEnemyRoots<SpaceAndCrafts.AI.ScrapSpitter>(focusObject, ref disabled);
            DisableNonFocusEnemyRoots<SpaceAndCrafts.AI.ScrapStormSentinel>(focusObject, ref disabled);
            DisableNonFocusEnemyRoots<SpaceAndCrafts.AI.ScrapSpitProjectile>(focusObject, ref disabled);
            if (disabled > 0)
            {
                Debug.Log($"[Space & Crafts] Disabled {disabled} non-focus enemy/hostile objects for isolated animation capture.");
            }

        }

        private static void DisableNonFocusEnemyRoots<T>(GameObject focusObject, ref int disabled)
            where T : Component
        {
            var enemies = Object.FindObjectsByType<T>();
            for (var i = 0; i < enemies.Length; i++)
            {
                var enemy = enemies[i];
                if (enemy == null || enemy.gameObject == focusObject
                    || enemy.transform.IsChildOf(focusObject.transform))
                {
                    continue;
                }

                enemy.gameObject.SetActive(false);
                disabled++;
            }
        }

