        {
            SessionState.SetBool(VictoryScreenCapturePendingKey, false);
            SessionState.SetBool(ReviewWaveOneHandCaptureKey, false);
            SessionState.SetBool(ReviewWaveOneHandAppliedKey, false);
            SessionState.SetBool(ReviewRunCandidateCaptureKey, false);
            SessionState.SetBool(ReviewRunCandidateAppliedKey, false);
            SessionState.SetBool(ReviewRunContactCorrectionKey, false);
            SessionState.SetString(ReviewRunCandidateClipNameKey, string.Empty);
            SessionState.SetBool(MiteIslandPreviewKey, false);
            SessionState.SetBool(MiteCommissionedRigCaptureKey, false);
            SessionState.SetBool(RainbowSpiderCandidateCaptureKey, false);
            SessionState.SetBool(MiteCompactFaceCaptureKey, false);
            SessionState.SetBool(AlignSplatContactBeforeSequenceFrameKey, false);
            SessionState.SetBool(SpitterDelayedWindupCaptureKey, false);
            SessionState.SetString(SpitterFocusObjectKey, string.Empty);
            SessionState.SetBool(SpitterHitResponseCaptureKey, false);
            SessionState.SetBool(SpitterJumpHitResponseCaptureKey, false);
            SessionState.SetBool(SpitterDefeatCaptureKey, false);
            SessionState.SetBool(SpitterDefeatCaptureStartedKey, false);
            SessionState.SetBool(RollerDefeatCaptureKey, false);
            SessionState.SetBool(RollerDefeatCaptureStartedKey, false);
            SessionState.SetBool(WorldBossExamCaptureKey, false);
            SessionState.SetBool(WorldBossExamCaptureStagedKey, false);
            SessionState.SetBool(BossPhaseMiteCaptureKey, false);
            SessionState.SetBool(IsolatedFocusPreparedKey, false);
            if (SessionState.GetBool(FixedStepRunCaptureAppliedKey, false)
                || SessionState.GetBool(CaptureTargetFrameRateAppliedKey, false))
            {
                Time.captureDeltaTime = SessionState.GetFloat(OriginalCaptureDeltaTimeKey, 0f);
            }
            SessionState.SetBool(FixedStepRunCaptureAppliedKey, false);
            SessionState.SetBool(FixedStepRunCaptureKey, false);
            SessionState.SetInt(CaptureTargetFrameRateKey, 0);
            SessionState.SetBool(CaptureTargetFrameRateAppliedKey, false);
            SessionState.SetFloat(OriginalCaptureDeltaTimeKey, 0f);
            var output = SessionState.GetString(OutputKey, string.Empty);
            SessionState.SetBool(ActiveKey, false);
            SessionState.SetBool(FrontFacingKey, false);
            SessionState.SetString(PoseActionKey, string.Empty);
            SessionState.SetFloat(PoseAppliedTimeKey, 0f);
            SessionState.SetBool(SimulatedJumpKey, false);
            SessionState.SetBool(SimulatedRunKey, false);
            SessionState.SetFloat(SimulatedRunStartTimeKey, 0f);
            SessionState.SetInt(SimulatedRunStartFrameKey, -1);
            SessionState.SetString(SimulatedRunStartPositionKey, string.Empty);
            SessionState.SetFloat(GroundedSinceTimeKey, 0f);
            SessionState.SetFloat(SimulatedRunCaptureDelayKey, 0.45f);
            SessionState.SetFloat(RunStopDelayKey, 0f);
            SessionState.SetBool(RunStopAppliedKey, false);
            SessionState.SetInt(CaptureDelayFramesKey, -1);
            SessionState.SetBool(Candidate310RestPoseKey, false);
            SessionState.SetBool(Candidate310DiagnosticKey, false);
            SessionState.SetString(CandidateResourceKey, string.Empty);
            EditorApplication.update -= Tick;
            if (File.Exists(output) && new FileInfo(output).Length > 1024)
            {
                Debug.Log($"[Space & Crafts] Arrival screenshot saved: {output}");
                EditorApplication.Exit(0);
                return;
            }

            Debug.LogError($"Arrival screenshot was not written: {output}");
            EditorApplication.Exit(4);
        }

        private static void PrepareCandidateDiagnostic(SplatSkeletonAnimator splatAnimator,
            string candidateResource, bool restPose)
        {
            var hero = GameObject.Find("Splat_TEMP");
            var prefab = Resources.Load<GameObject>(candidateResource);
            if (hero == null || prefab == null)
            {
                Debug.LogError($"Could not prepare Splat candidate diagnostic; hero or resource '{candidateResource}' is missing.");
                return;
            }

            var candidateVersion = candidateResource.Contains("Iter378")
                ? "Iter378"
                : candidateResource.Contains("Iter1158")
                ? "Iter1158"
                : candidateResource.Contains("Iter375")
                ? "Iter375"
                : candidateResource.Contains("Iter355")
                ? "Iter355"
                : candidateResource.Contains("Iter352")
                ? "Iter352"
                : candidateResource.Contains("Iter349") ? "Iter349"
                : candidateResource.Contains("Iter324") ? "Iter324"
                : candidateResource.Contains("Iter318") ? "Iter318" : "Iter310";

            var activeVisual = hero.transform.Find("ART_SplatVisual");
            if (activeVisual != null)
            {
                activeVisual.gameObject.SetActive(false);
                activeVisual.name = "ART_SplatVisual_PreviousDisabled";
            }

            var visual = Object.Instantiate(prefab, hero.transform, false);
            visual.name = "ART_SplatVisual";
            visual.transform.localPosition = Vector3.zero;
            visual.transform.localRotation = Quaternion.identity;
            visual.transform.localScale = Vector3.one * 0.95f;

            var shader = Shader.Find("SpaceAndCrafts/SplatVertexColorLit");
            if (shader != null)
            {
                var material = new Material(shader) { name = $"Mat_Splat_{candidateVersion}_Diagnostic" };
                material.SetColor("_BaseColor", candidateVersion == "Iter1158"
                    ? new Color(0.56f, 0.72f, 1f, 1f)
                    : Color.white);
                material.SetColor("_SkinColor", new Color(0.31f, 0.12f, 0.57f, 1f));
                foreach (var renderer in visual.GetComponentsInChildren<SkinnedMeshRenderer>(true))
                {
                    var meshVersion = candidateVersion == "Iter1158" ? "Iter378" : candidateVersion;
                    if (renderer != null && renderer.name.Contains($"ART_SplatBody_{meshVersion}"))
                    {
                        renderer.sharedMaterial = material;
                    }
                }
            }

            if (restPose)
            {
                splatAnimator.enabled = false;
                Debug.Log($"[Space & Crafts] Prepared {candidateVersion} FBX in an unposed rest-pose diagnostic; the gameplay animator is disabled for this capture.");
            }
            else
            {
                var motor = hero.GetComponent<SplatMotor>();
                splatAnimator.Bind(motor, visual.transform);
                Debug.Log($"[Space & Crafts] Rebound the gameplay pose driver to {candidateVersion} FBX for an isolated run-pose capture.");
            }
        }

        private static void SampleBakedSkinBottom(SkinnedMeshRenderer[] renderers,
            out float unscaledRendererBottom, out float transformPointBottom)
        {
            unscaledRendererBottom = float.PositiveInfinity;
            transformPointBottom = float.PositiveInfinity;
            if (renderers == null || renderers.Length == 0) return;

            var baked = new Mesh { name = "SplatContactVertexDiagnostic" };
            try
            {
                for (var rendererIndex = 0; rendererIndex < renderers.Length; rendererIndex++)
                {
                    var renderer = renderers[rendererIndex];
                    if (renderer == null || !renderer.enabled || renderer.sharedMesh == null) continue;
                    baked.Clear();
                    renderer.BakeMesh(baked);
                    var vertices = baked.vertices;
                    for (var vertexIndex = 0; vertexIndex < vertices.Length; vertexIndex++)
                    {
                        var vertex = vertices[vertexIndex];
                        var rotationOnlyWorld = renderer.transform.position
                            + renderer.transform.rotation * vertex;
                        var fullyTransformedWorld = renderer.transform.TransformPoint(vertex);
                        unscaledRendererBottom = Mathf.Min(unscaledRendererBottom, rotationOnlyWorld.y);
                        transformPointBottom = Mathf.Min(transformPointBottom, fullyTransformedWorld.y);
                    }
                }
            }
            finally
            {
                Object.DestroyImmediate(baked);
            }
        }

        private static void LogCandidateSkinBounds()
        {
            var renderers = Object.FindObjectsByType<SkinnedMeshRenderer>(FindObjectsInactive.Exclude);
            var body = System.Array.Find(renderers, r => r != null && r.sharedMesh != null
                && r.sharedMesh.name.Contains("ART_SplatBody_Iter"));
            if (body == null)
            {
                Debug.LogWarning("[Space & Crafts] Candidate skin bounds: no visible Splat body renderer found.");
                return;
            }

            var mesh = new Mesh { name = "CandidateBoundsDiagnostic" };
            body.BakeMesh(mesh);
            var bakedVertices = mesh.vertices;
            var restBounds = body.localBounds;
            var bakedBounds = mesh.bounds;
            body.updateWhenOffscreen = true;
            var worldBounds = body.bounds;
            var camera = Camera.main;
            var insideExpandedWorldBounds = 0;
            var insideCameraFrustum = 0;
            var viewportMin = new Vector3(float.PositiveInfinity, float.PositiveInfinity, float.PositiveInfinity);
            var viewportMax = new Vector3(float.NegativeInfinity, float.NegativeInfinity, float.NegativeInfinity);
            for (var i = 0; i < bakedVertices.Length; i++)
            {
                // SkinnedMeshRenderer.BakeMesh includes the renderer transform scale
                // in its output vertices. Apply only world rotation and translation
                // here; TransformPoint would multiply the FBX's 95x import scale twice.
                var worldVertex = body.transform.position + body.transform.rotation * bakedVertices[i];
                if (worldBounds.Contains(worldVertex))
                {
                    insideExpandedWorldBounds++;
                }

                if (camera == null)
                {
                    continue;
                }

                var viewport = camera.WorldToViewportPoint(worldVertex);
                viewportMin = Vector3.Min(viewportMin, viewport);
                viewportMax = Vector3.Max(viewportMax, viewport);
                if (viewport.z >= camera.nearClipPlane && viewport.z <= camera.farClipPlane
                    && viewport.x >= 0f && viewport.x <= 1f && viewport.y >= 0f && viewport.y <= 1f)
                {
                    insideCameraFrustum++;
                }
            }

            var hero = GameObject.Find("Splat_TEMP");
            Debug.Log($"[Space & Crafts] Candidate skin bounds: renderer={body.name}, mesh={body.sharedMesh.name}, active={body.enabled && body.gameObject.activeInHierarchy}, rendererPosition={body.transform.position.ToString("F3")}, rendererRotation={body.transform.rotation.eulerAngles.ToString("F1")}, rendererScale={body.transform.lossyScale.ToString("F3")}, heroPosition={(hero != null ? hero.transform.position.ToString("F3") : "missing")}, heroRotation={(hero != null ? hero.transform.rotation.eulerAngles.ToString("F1") : "missing")}, cameraPosition={(camera != null ? camera.transform.position.ToString("F3") : "missing")}, cameraRotation={(camera != null ? camera.transform.rotation.eulerAngles.ToString("F1") : "missing")}, rendererViewport={(camera != null ? camera.WorldToViewportPoint(body.transform.position).ToString("F3") : "no camera")}, rootBone={body.rootBone?.name}, rootBonePosition={body.rootBone?.position.ToString("F3")}, originalLocalBoundsCenter={restBounds.center.ToString("F3")}, originalLocalBoundsSize={restBounds.size.ToString("F3")}, bakedBoundsCenter={bakedBounds.center.ToString("F3")}, bakedBoundsSize={bakedBounds.size.ToString("F3")}, updateWhenOffscreen={body.updateWhenOffscreen}, rendererWorldBoundsCenter={worldBounds.center.ToString("F3")}, rendererWorldBoundsSize={worldBounds.size.ToString("F3")}, bakedVerticesInsideWorldBounds={insideExpandedWorldBounds}/{bakedVertices.Length}, bakedVerticesInsideCameraFrustum={insideCameraFrustum}/{bakedVertices.Length}, bakedMeshViewportMin={viewportMin.ToString("F3")}, bakedMeshViewportMax={viewportMax.ToString("F3")}.");
            var candidateVisual = hero != null ? hero.transform.Find("ART_SplatVisual") : null;
            var armLeft = candidateVisual != null ? FindNamedTransform(candidateVisual, "Bone_ArmL") : null;
            var armRight = candidateVisual != null ? FindNamedTransform(candidateVisual, "Bone_ArmR") : null;
            var legLeft = candidateVisual != null ? FindNamedTransform(candidateVisual, "Bone_LegL") : null;
            var legRight = candidateVisual != null ? FindNamedTransform(candidateVisual, "Bone_LegR") : null;
            var animator = hero != null ? hero.GetComponent<SplatSkeletonAnimator>() : null;
            var armTipLeft = candidateVisual != null ? FindNamedTransform(candidateVisual, "Bone_ArmTipL") : null;
            var armTipRight = candidateVisual != null ? FindNamedTransform(candidateVisual, "Bone_ArmTipR") : null;
            var chest = candidateVisual != null ? FindNamedTransform(candidateVisual, "Bone_Chest") : null;
            Debug.Log($"[Space & Crafts] Candidate pose sample: action={animator?.CurrentAction.ToString() ?? "missing"}, leftArm={(armLeft != null ? armLeft.localRotation.eulerAngles.ToString("F1") : "missing")}, leftArmQ={(armLeft != null ? armLeft.localRotation.ToString("F4") : "missing")}, cachedLeftArmRestQ={animator?.BoundLeftArmRestLocalRotation.ToString("F4") ?? "missing"}, rightArm={(armRight != null ? armRight.localRotation.eulerAngles.ToString("F1") : "missing")}, armTipL={(armTipLeft != null ? armTipLeft.localRotation.eulerAngles.ToString("F1") : "missing")}, armTipR={(armTipRight != null ? armTipRight.localRotation.eulerAngles.ToString("F1") : "missing")}, chest={(chest != null ? chest.localRotation.eulerAngles.ToString("F1") : "missing")}, leftLeg={(legLeft != null ? legLeft.localRotation.eulerAngles.ToString("F1") : "missing")}, rightLeg={(legRight != null ? legRight.localRotation.eulerAngles.ToString("F1") : "missing")}.");
            Object.Destroy(mesh);
        }

        private static IEnumerator CaptureVictoryScreenAtEndOfFrame(string output,
            string sequenceDirectory, int sequenceFrameIndex, float duration)
        {
            yield return new WaitForEndOfFrame();
            Texture2D screenshot = null;
            try
            {
                screenshot = ScreenCapture.CaptureScreenshotAsTexture();
                if (screenshot == null || screenshot.width < 2 || screenshot.height < 2)
                {
                    throw new System.InvalidOperationException("ScreenCapture returned an empty game frame.");
                }

                File.WriteAllBytes(output, screenshot.EncodeToPNG());
                Debug.Log($"[Space & Crafts] Captured the rendered victory game frame: resolution={screenshot.width}x{screenshot.height}, sequenceFrame={sequenceFrameIndex}, output={output}.");
                Debug.Log($"[Space & Crafts] Completed Splat animation sequence capture: frames={sequenceFrameIndex}, duration={duration:F2}s, output={sequenceDirectory}.");
                SessionState.SetBool(VictoryScreenCapturePendingKey, false);
                SessionState.SetBool(CapturedKey, true);
                SessionState.SetInt(CaptureFrameKey, SessionState.GetInt(FrameKey, 0));
                EditorApplication.isPlaying = false;
            }
            catch (System.Exception exception)
            {
                Debug.LogError($"[Space & Crafts] Failed to capture the rendered victory game frame: {exception.Message}");
                SessionState.SetBool(VictoryScreenCapturePendingKey, false);
                SessionState.SetBool(ActiveKey, false);
                EditorApplication.Exit(5);
            }
            finally
            {
                if (screenshot != null)
                {
                    Object.Destroy(screenshot);
                }
            }
        }

        private static bool RenderGameCamera(string output)
        {
            if (SessionState.GetBool(IsolateFocusObjectKey, false))
            {
                var focusName = SessionState.GetString(FocusObjectKey, string.Empty);
                var focusObject = string.IsNullOrEmpty(focusName) ? null : GameObject.Find(focusName);
                if (focusObject != null) SuppressNonFocusCaptureRenderers(focusObject);
            }

            var camera = Camera.main != null ? Camera.main : Object.FindAnyObjectByType<Camera>();
            var ownsCaptureCamera = false;
            if (camera == null)
            {
                // Numbered worlds can be player-ready while omitting the Arrival
                // showcase camera. The capture harness still needs a review camera
                // so platform-contact checks cover the actual target scene.
                var cameraObject = new GameObject("TEMP_VisualCaptureCamera")
                {
                    hideFlags = HideFlags.HideAndDontSave
                };
                camera = cameraObject.AddComponent<Camera>();
                camera.clearFlags = CameraClearFlags.Skybox;
                camera.nearClipPlane = 0.05f;
                camera.farClipPlane = 1000f;
                ownsCaptureCamera = true;
                Debug.Log("[Space & Crafts] Created a temporary review camera because the loaded scene has no active camera.");
            }

            const int width = 1600;
            const int height = 900;
            var oldTarget = camera.targetTexture;
            var oldAspect = camera.aspect;
            var oldCameraPosition = camera.transform.position;
            var oldCameraRotation = camera.transform.rotation;
            var oldFieldOfView = camera.fieldOfView;
            var previousActive = RenderTexture.active;
            var renderTexture = new RenderTexture(width, height, 24, RenderTextureFormat.ARGB32)
            {
                name = "ArrivalVisualCapture"
            };
            var screenshot = new Texture2D(width, height, TextureFormat.RGB24, false)
            {
                name = "ArrivalVisualCapturePixels"
            };
            var overlayCanvases = Object.FindObjectsByType<Canvas>(FindObjectsInactive.Exclude);
            var overlayModes = new RenderMode[overlayCanvases.Length];
            var overlayCameras = new Camera[overlayCanvases.Length];
            var overlayDistances = new float[overlayCanvases.Length];
            var overlayEnabled = new bool[overlayCanvases.Length];

            try
            {
                SampleAuthoredClipForCapture();
                if (SessionState.GetBool(FrontFacingKey, false))
                {
                    var splatAnimator = Object.FindAnyObjectByType<SplatSkeletonAnimator>();
                    splatAnimator?.ForceEyesOpenForCapture();
                    var hero = GameObject.Find("Splat_TEMP");
                    if (hero != null)
                    {
                        if (SessionState.GetBool(ForceWorldFacingForCaptureKey, false))
                        {
                            hero.transform.rotation = Quaternion.identity;
                            Physics.SyncTransforms();
                        }
                        var visual = hero.transform.Find("ART_SplatVisual");
                        var leftArm = visual != null ? FindNamedTransform(visual, "Bone_ArmL") : null;
                        var rightArm = visual != null ? FindNamedTransform(visual, "Bone_ArmR") : null;
                        var skinned = visual != null ? visual.GetComponentsInChildren<SkinnedMeshRenderer>(true) : System.Array.Empty<SkinnedMeshRenderer>();
                        var bodyRenderer = System.Array.Find(skinned, r => r != null && r.sharedMesh != null
                            && (r.name.Contains("ART_SplatBody") || r.sharedMesh.name.Contains("ART_SplatBody")));
                        var rigRenderer = bodyRenderer ?? System.Array.Find(skinned, r => r != null && r.sharedMesh != null
                            && (bodyRenderer == null || r.sharedMesh.vertexCount > bodyRenderer.sharedMesh.vertexCount));
                        Debug.Log($"[Space & Crafts] Splat pose evidence: action={splatAnimator?.CurrentAction}, leftArm={(leftArm != null ? leftArm.localRotation.eulerAngles.ToString("F1") : "missing")}, skinnedRenderers={skinned.Length}, bodyRenderer={rigRenderer?.name ?? "missing"}, vertices={(rigRenderer != null && rigRenderer.sharedMesh != null ? rigRenderer.sharedMesh.vertexCount : 0)}, bones={(rigRenderer != null && rigRenderer.bones != null ? rigRenderer.bones.Length : 0)}.");
                        if (rigRenderer != null && rigRenderer.sharedMaterial != null) Debug.Log($"[Space & Crafts] Splat active face material: renderer={rigRenderer.name}, material={rigRenderer.sharedMaterial.name}, shader={rigRenderer.sharedMaterial.shader?.name ?? "missing"}, hasSkinColor={rigRenderer.sharedMaterial.HasProperty("_SkinColor")}, skinColor={(rigRenderer.sharedMaterial.HasProperty("_SkinColor") ? rigRenderer.sharedMaterial.GetColor("_SkinColor").ToString("F3") : "n/a")}, hasEyeBlink={rigRenderer.sharedMaterial.HasProperty("_EyeBlink")}, eyeBlink={(rigRenderer.sharedMaterial.HasProperty("_EyeBlink") ? rigRenderer.sharedMaterial.GetFloat("_EyeBlink").ToString("F2") : "n/a")}, vertexColor={rigRenderer.sharedMaterial.HasProperty("_BaseColor") && rigRenderer.sharedMaterial.GetColor("_BaseColor") != Color.clear}.");
                        Debug.Log($"[Space & Crafts] Splat arm skin weights: left={SummarizeBoneInfluence(skinned, leftArm)}, right={SummarizeBoneInfluence(skinned, rightArm)}.");
                        Debug.Log($"[Space & Crafts] Idle gesture evidence: phase={splatAnimator?.PhaseForDiagnostics:F2}, now={Time.time:F2}, action={splatAnimator?.CurrentAction}, greetingWeight={splatAnimator?.IdleGreetingWeightForDiagnostics:F2}, greetingStart={splatAnimator?.IdleGreetingStartedAtForDiagnostics:F2}, greetingNext={splatAnimator?.IdleGreetingNextAtForDiagnostics:F2}.");
                        Debug.Log($"[Space & Crafts] Idle greeting tip pose: left={(splatAnimator != null ? splatAnimator.BoundLeftArmTipEuler.ToString("F1") : "missing")}, right={(splatAnimator != null ? splatAnimator.BoundRightArmTipEuler.ToString("F1") : "missing")}.");
                        Debug.Log($"[Space & Crafts] Animator binding evidence: visibleRigBound={splatAnimator != null && splatAnimator.IsBoundToVisibleVisual(visual)}, visibleSkinBound={splatAnimator != null && splatAnimator.IsBoundToVisibleSkin(visual)}, boundArm={splatAnimator?.BoundLeftArmEuler.ToString("F1")}, restArm={splatAnimator?.BoundLeftArmRestEuler.ToString("F1")}, boundLeg={splatAnimator?.BoundLeftLegEuler.ToString("F1")}, boundLegPosition={splatAnimator?.BoundLeftLegLocalPosition.ToString("F4")}, boundLegWorldUpOffset={splatAnimator?.BoundLeftLegWorldUpOffset:F3}m.");
                        if (leftArm != null)
                        {
                            Debug.Log($"[Space & Crafts] Splat arm orientation: worldRight={leftArm.TransformDirection(Vector3.right):F3}, worldUp={leftArm.TransformDirection(Vector3.up):F3}, worldForward={leftArm.TransformDirection(Vector3.forward):F3}, localPosition={leftArm.localPosition:F3}.");
                        }
                        if (rightArm != null)
                        {
                            Debug.Log($"[Space & Crafts] Splat right arm orientation: worldRight={rightArm.TransformDirection(Vector3.right):F3}, worldUp={rightArm.TransformDirection(Vector3.up):F3}, worldForward={rightArm.TransformDirection(Vector3.forward):F3}, localPosition={rightArm.localPosition:F3}.");
                        }
                        if (rigRenderer != null && rigRenderer.bones != null)
                        {
                            for (var boneIndex = 0; boneIndex < rigRenderer.bones.Length; boneIndex++)
                            {
                                var bone = rigRenderer.bones[boneIndex];
                                if (bone != null)
                                {
                                    Debug.Log($"[Space & Crafts] Visible rig bone: index={boneIndex}, name={bone.name}, parent={bone.parent?.name ?? "none"}, localPosition={bone.localPosition:F4}, localRotation={bone.localRotation.eulerAngles:F1}.");
                                }
                            }

                            if (rigRenderer.sharedMesh != null)
                            {
                                var leftLegIndex = System.Array.FindIndex(rigRenderer.bones, bone => bone != null && bone.name == "Bone_LegL");
                                var rightLegIndex = System.Array.FindIndex(rigRenderer.bones, bone => bone != null && bone.name == "Bone_LegR");
                                var weights = rigRenderer.sharedMesh.boneWeights;
                                var leftInfluencedVertices = 0;
                                var rightInfluencedVertices = 0;
                                var leftWeightTotal = 0f;
                                var rightWeightTotal = 0f;
                                for (var weightIndex = 0; weightIndex < weights.Length; weightIndex++)
                                {
                                    var weight = weights[weightIndex];
                                    var leftWeight = (weight.boneIndex0 == leftLegIndex ? weight.weight0 : 0f)
                                        + (weight.boneIndex1 == leftLegIndex ? weight.weight1 : 0f)
                                        + (weight.boneIndex2 == leftLegIndex ? weight.weight2 : 0f)
                                        + (weight.boneIndex3 == leftLegIndex ? weight.weight3 : 0f);
                                    var rightWeight = (weight.boneIndex0 == rightLegIndex ? weight.weight0 : 0f)
                                        + (weight.boneIndex1 == rightLegIndex ? weight.weight1 : 0f)
                                        + (weight.boneIndex2 == rightLegIndex ? weight.weight2 : 0f)
                                        + (weight.boneIndex3 == rightLegIndex ? weight.weight3 : 0f);
                                    if (leftWeight > 0.001f) leftInfluencedVertices++;
                                    if (rightWeight > 0.001f) rightInfluencedVertices++;
                                    leftWeightTotal += leftWeight;
                                    rightWeightTotal += rightWeight;
                                }
                                Debug.Log($"[Space & Crafts] Leg skin-weight sample: meshVertices={weights.Length}, leftLegBoneIndex={leftLegIndex}, leftInfluencedVertices={leftInfluencedVertices}, leftWeightTotal={leftWeightTotal:F1}, rightLegBoneIndex={rightLegIndex}, rightInfluencedVertices={rightInfluencedVertices}, rightWeightTotal={rightWeightTotal:F1}.");
                            }
                        }
                        if (bodyRenderer != null)
                        {
                                var maxBindPoseError = 0f;
                                var maxBindPoseBone = "none";
                                var bindPoses = bodyRenderer.sharedMesh.bindposes;
                                var bindCount = Mathf.Min(bodyRenderer.bones.Length, bindPoses.Length);
                                for (var i = 0; i < bindCount; i++)
                                {
                                    var bone = bodyRenderer.bones[i];
                                    if (bone == null)
                                    {
                                        continue;
                                    }

                                    var reconstructedBind = bodyRenderer.transform.worldToLocalMatrix
                                        * bone.localToWorldMatrix * bindPoses[i];
                                    var error = 0f;
                                    var identity = Matrix4x4.identity;
                                    for (var row = 0; row < 4; row++)
                                    {
                                        for (var column = 0; column < 4; column++)
                                        {
                                            error = Mathf.Max(error,
                                                Mathf.Abs(reconstructedBind[row, column] - identity[row, column]));
                                        }
                                    }

                                    if (error > maxBindPoseError)
                                    {
                                        maxBindPoseError = error;
                                        maxBindPoseBone = bone.name;
                                    }
                                }
                                var poseMatrixLabel = SessionState.GetBool(Candidate310RestPoseKey, false)
                                    ? "bind-pose evidence"
                                    : "posed-skin matrix residual (not a bind-pose check)";
                                Debug.Log($"[Space & Crafts] Splat {poseMatrixLabel}: renderer={bodyRenderer.name}, bonesChecked={bindCount}, maxMatrixError={maxBindPoseError:F4}, worstBone={maxBindPoseBone}.");
                            var armBone = System.Array.FindIndex(bodyRenderer.bones, b => b != null && b.name == "Bone_ArmL");
                            Debug.Log($"[Space & Crafts] Splat body skin evidence: renderer={bodyRenderer.name}, mesh={bodyRenderer.sharedMesh.name}, vertices={bodyRenderer.sharedMesh.vertexCount}, boneCount={bodyRenderer.bones.Length}, leftArmBoneIndex={armBone}, rootBone={bodyRenderer.rootBone?.name}.");
                            var baked = new Mesh();
                            bodyRenderer.BakeMesh(baked);
                            Debug.Log($"[Space & Crafts] Splat mesh-space evidence: renderer={bodyRenderer.name}, localScale={bodyRenderer.transform.localScale.ToString("F4")}, lossyScale={bodyRenderer.transform.lossyScale.ToString("F4")}, sharedBounds={bodyRenderer.sharedMesh.bounds.size.ToString("F4")}, bakedBounds={baked.bounds.size.ToString("F4")}, rootBoneScale={bodyRenderer.rootBone?.lossyScale.ToString("F4") ?? "missing"}.");
                            var restVertices = bodyRenderer.sharedMesh.vertices;
                            var posedVertices = baked.vertices;
                            var maxPoseDelta = 0f;
                            var averagePoseDelta = 0f;
                            var deltaCount = Mathf.Min(restVertices.Length, posedVertices.Length);
                            for (var i = 0; i < deltaCount; i++)
                            {
                                var rendererScale = bodyRenderer.transform.localScale;
                                var scaleAdjustedRestVertex = Vector3.Scale(restVertices[i], rendererScale);
                                var delta = Vector3.Distance(scaleAdjustedRestVertex, posedVertices[i]);
                                maxPoseDelta = Mathf.Max(maxPoseDelta, delta);
                                averagePoseDelta += delta;
                            }
                            averagePoseDelta = deltaCount > 0 ? averagePoseDelta / deltaCount : 0f;
                            Debug.Log($"[Space & Crafts] Splat scale-compensated deformation evidence: maxVertexDelta={maxPoseDelta:F4}, averageVertexDelta={averagePoseDelta:F4}, rendererScale={bodyRenderer.transform.localScale.ToString("F2")}, comparedVertices={deltaCount}.");
                            Object.DestroyImmediate(baked);
                        }
                        var candidateDiagnostic = SessionState.GetBool(Candidate310DiagnosticKey, false);
                        var visualRoot = hero.transform.Find("ART_SplatVisual");
                        var visualRenderers = visualRoot != null
                            ? visualRoot.GetComponentsInChildren<Renderer>(true)
                            : System.Array.Empty<Renderer>();
                        var visualBounds = new Bounds(hero.transform.position + Vector3.up * 1.2f, Vector3.zero);
                        var hasVisualBounds = false;
                        for (var i = 0; i < visualRenderers.Length; i++)
                        {
                            if (visualRenderers[i] == null || !visualRenderers[i].enabled
                                || !visualRenderers[i].gameObject.activeInHierarchy)
                            {
                                continue;
                            }

                            if (!hasVisualBounds)
                            {
                                visualBounds = visualRenderers[i].bounds;
                                hasVisualBounds = true;
                            }
                            else
                            {
                                visualBounds.Encapsulate(visualRenderers[i].bounds);
                            }
                        }

                        // Frame the whole visible character, including its antenna
                        // and feet. Root-height framing cropped the upper body and
                        // aimed too low to judge contact on shallow traversal pads.
                        var target = hasVisualBounds
                            ? visualBounds.center
                            : hero.transform.position + Vector3.up * (candidateDiagnostic ? 1.2f : 1.1f);
                        var forward = hero.transform.forward;
                        var simulatedJump = SessionState.GetBool(SimulatedJumpKey, false);
                        var fieldOfView = candidateDiagnostic || simulatedJump ? 48f : 42f;
                        var framedHeight = hasVisualBounds ? visualBounds.size.y : 2.2f;
                        var cameraDistanceFloor = candidateDiagnostic ? 4.2f : simulatedJump ? 6.2f : 3.4f;
                        var distance = Mathf.Max(cameraDistanceFloor,
                            (framedHeight * 0.5f + 0.15f) / Mathf.Tan(fieldOfView * 0.5f * Mathf.Deg2Rad) * 1.08f);
                        camera.transform.position = target + forward * distance + Vector3.up * 0.2f;
                        camera.transform.rotation = Quaternion.LookRotation(target - camera.transform.position, Vector3.up);
                        camera.fieldOfView = fieldOfView;
                        if (simulatedJump || !string.IsNullOrEmpty(SessionState.GetString(PlacementPlatformKey, string.Empty)))
                        {
                            var viewportCenter = camera.WorldToViewportPoint(target);
                            Debug.Log($"[Space & Crafts] Character capture framing: action={splatAnimator?.CurrentAction}, root={hero.transform.position.ToString("F3")}, visualBoundsCenter={(hasVisualBounds ? visualBounds.center : hero.transform.position).ToString("F3")}, visualBoundsSize={(hasVisualBounds ? visualBounds.size : Vector3.zero).ToString("F3")}, camera={camera.transform.position.ToString("F3")}, viewportCenter={viewportCenter.ToString("F3")}, distance={distance:F2}, platformCapture={!string.IsNullOrEmpty(SessionState.GetString(PlacementPlatformKey, string.Empty))}.");
                        }
                    }
                }

                var focusObjectName = SessionState.GetString(FocusObjectKey, string.Empty);
                if (!string.IsNullOrEmpty(focusObjectName))
                {
                    var focusObject = GameObject.Find(focusObjectName);
                    if (focusObject != null)
                    {
                        var renderers = focusObject.GetComponentsInChildren<Renderer>(true);
                        var focusBounds = new Bounds(focusObject.transform.position + Vector3.up * 0.35f, Vector3.one * 0.2f);
                        var hasBounds = false;
                        for (var i = 0; i < renderers.Length; i++)
                        {
                            if (renderers[i] == null || !renderers[i].enabled || !renderers[i].gameObject.activeInHierarchy)
                            {
                                continue;
                            }

                            if (!hasBounds)
                            {
                                focusBounds = renderers[i].bounds;
                                hasBounds = true;
                            }
                            else
                            {
                                focusBounds.Encapsulate(renderers[i].bounds);
                            }
                        }

                        var focusTarget = hasBounds ? focusBounds.center : focusObject.transform.position + Vector3.up * 0.35f;
                        if (SessionState.GetBool(SideContactCameraKey, false))
                        {
                            // Skinned renderer bounds can be stale/invalid during an
                            // idle capture. For sole-contact views, keep the camera
                            // centered on the actual gameplay capsule so it never
                            // winds up underneath the platform while aiming at bad
                            // mesh bounds.
                            var contactController = focusObject.GetComponent<CharacterController>();
                            focusTarget = contactController != null && contactController.enabled
                                ? contactController.bounds.center
                                : focusObject.transform.position + Vector3.up * 1.0f;
                        }
                        if (SessionState.GetBool(UseFocusCameraCustomOffsetKey, false))
                        {
                            focusTarget += focusObject.transform.TransformDirection(
                                SessionState.GetVector3(FocusCameraCustomTargetOffsetKey, Vector3.zero));
                        }
                        if (camera != null && !SessionState.GetBool(PreserveSceneCameraKey, false))
                        {
                            var sequenceFrame = SessionState.GetInt(SequenceFrameIndexKey, 0);
                            var followForSequence = SessionState.GetBool(FollowFocusCameraKey, false)
                                && sequenceFrame > 0;
                            var freezeForSequence = SessionState.GetBool(FreezeFocusCameraKey, false)
                                && sequenceFrame > 0;
                            if (followForSequence)
                            {
                                var offset = new Vector3(SessionState.GetFloat(FocusCameraOffsetXKey, 0f),
                                    SessionState.GetFloat(FocusCameraOffsetYKey, 0f),
                                    SessionState.GetFloat(FocusCameraOffsetZKey, 0f));
                                var rotation = new Quaternion(SessionState.GetFloat(FocusCameraRotationXKey, 0f),
                                    SessionState.GetFloat(FocusCameraRotationYKey, 0f),
                                    SessionState.GetFloat(FocusCameraRotationZKey, 0f),
                                    SessionState.GetFloat(FocusCameraRotationWKey, 1f));
                                camera.transform.SetPositionAndRotation(focusTarget + offset, rotation);
                            }
                            else if (freezeForSequence)
                            {
                                camera.transform.SetPositionAndRotation(
                                    new Vector3(SessionState.GetFloat(FocusCameraPositionXKey, 0f),
                                        SessionState.GetFloat(FocusCameraPositionYKey, 0f),
                                        SessionState.GetFloat(FocusCameraPositionZKey, 0f)),
                                    new Quaternion(SessionState.GetFloat(FocusCameraRotationXKey, 0f),
                                        SessionState.GetFloat(FocusCameraRotationYKey, 0f),
                                        SessionState.GetFloat(FocusCameraRotationZKey, 0f),
                                        SessionState.GetFloat(FocusCameraRotationWKey, 1f)));
                            }
                            else
                            {
                                // RenderGameCamera restores the camera transform after
                                // each still. Reapplying this initial pose makes a fixed
                                // frame useful for judging the subject's actual motion.
                                var sideContactCamera = SessionState.GetBool(SideContactCameraKey, false);
                                var commissionedMiteCapture = SessionState.GetBool(MiteCommissionedRigCaptureKey, false);
                                var cameraOffset = SessionState.GetBool(UseFocusCameraCustomOffsetKey, false)
                                    ? focusObject.transform.TransformDirection(
                                        SessionState.GetVector3(FocusCameraCustomOffsetKey, Vector3.zero))
                                    : commissionedMiteCapture
                                        ? focusObject.transform.forward * 1.8f + Vector3.up * 0.05f
                                        : sideContactCamera
                                            ? focusObject.transform.right * 2.6f
                                                + focusObject.transform.forward * 2.6f + Vector3.up * 0.05f
                                            : focusObject.transform.forward * 2.5f + Vector3.up * 1.0f;
                                if (commissionedMiteCapture)
                                {
                                    var mite = focusObject.GetComponent<SpaceAndCrafts.AI.ScrapMite>();
                                    var ground = mite != null ? mite.GroundYForVisuals : focusObject.transform.position.y;
                                    focusTarget = new Vector3(focusObject.transform.position.x, ground + 0.52f,
                                        focusObject.transform.position.z);
                                }
                                camera.transform.position = focusTarget + cameraOffset;
                                camera.transform.rotation = Quaternion.LookRotation(focusTarget - camera.transform.position, Vector3.up);
                                if (SessionState.GetBool(FreezeFocusCameraKey, false))
                                {
                                    var position = camera.transform.position;
                                    var rotation = camera.transform.rotation;
                                    SessionState.SetFloat(FocusCameraPositionXKey, position.x);
                                    SessionState.SetFloat(FocusCameraPositionYKey, position.y);
                                    SessionState.SetFloat(FocusCameraPositionZKey, position.z);
                                    SessionState.SetFloat(FocusCameraRotationXKey, rotation.x);
                                    SessionState.SetFloat(FocusCameraRotationYKey, rotation.y);
                                    SessionState.SetFloat(FocusCameraRotationZKey, rotation.z);
                                    SessionState.SetFloat(FocusCameraRotationWKey, rotation.w);
                                }
                                if (SessionState.GetBool(FollowFocusCameraKey, false) && sequenceFrame == 0)
                                {
                                    var offset = camera.transform.position - focusTarget;
                                    var rotation = camera.transform.rotation;
                                    SessionState.SetFloat(FocusCameraOffsetXKey, offset.x);
                                    SessionState.SetFloat(FocusCameraOffsetYKey, offset.y);
                                    SessionState.SetFloat(FocusCameraOffsetZKey, offset.z);
                                    SessionState.SetFloat(FocusCameraRotationXKey, rotation.x);
                                    SessionState.SetFloat(FocusCameraRotationYKey, rotation.y);
                                    SessionState.SetFloat(FocusCameraRotationZKey, rotation.z);
                                    SessionState.SetFloat(FocusCameraRotationWKey, rotation.w);
                                }
                            }
                            camera.fieldOfView = SessionState.GetBool(MiteCommissionedRigCaptureKey, false) ? 44f : 55f;
                            Debug.Log($"[Space & Crafts] Focused capture camera on {focusObject.name}: target={focusTarget.ToString("F2")}, bounds={focusBounds.size.ToString("F2")}, sideContact={SessionState.GetBool(SideContactCameraKey, false)}, customOffset={SessionState.GetBool(UseFocusCameraCustomOffsetKey, false)}, freeze={SessionState.GetBool(FreezeFocusCameraKey, false)}.");
                        }
                        else if (camera != null)
                        {
                            Debug.Log($"[Space & Crafts] Preserving scene camera for staged {focusObject.name} capture; its transform is not replaced by focus-camera framing.");
                        }
                        if (SessionState.GetBool(IsolateFocusObjectKey, false))
                        {
                            PrepareIsolatedFocusCapture(focusObject);
                        }
                        else if (SessionState.GetBool(RainbowSpiderCandidateCaptureKey, false))
                        {
                            // The ordinary-camera path is rendered once per
                            // sequence frame too. Install the review visual only
                            // once so captures do not accumulate duplicate rigs.
                            if (!SessionState.GetBool(IsolatedFocusPreparedKey, false))
                            {
                                InstallCaptureOnlyRainbowSpiderCandidate(focusObject);
                                if (SessionState.GetBool(SilenceNonFocusEnemiesKey, false))
                                    SilenceNonFocusEnemies(focusObject);
                                SessionState.SetBool(IsolatedFocusPreparedKey, true);
                            }
                        }
                        else if (SessionState.GetBool(SilenceNonFocusEnemiesKey, false))
                        {
                            SilenceNonFocusEnemies(focusObject);
                        }
                    }
                    else
                    {
                        Debug.LogWarning($"[Space & Crafts] Requested focus target was missing: {focusObjectName}.");
                    }
                }

                var contactHero = GameObject.Find("Splat_TEMP");
                if (contactHero != null)
                {
                    var controller = contactHero.GetComponent<CharacterController>();
                    var motor = contactHero.GetComponent<SplatMotor>();
                    var splatAnimator = contactHero.GetComponent<SplatSkeletonAnimator>();
                    var contactRepair = contactHero.GetComponent<SplatVisualRepair>();
                    var visual = contactHero.transform.Find("ART_SplatVisual");
                    var renderers = visual != null
                        ? visual.GetComponentsInChildren<SkinnedMeshRenderer>(true)
                        : System.Array.Empty<SkinnedMeshRenderer>();
                    var visibleSole = float.PositiveInfinity;
                    var visibleTop = float.NegativeInfinity;
                    for (var i = 0; i < renderers.Length; i++)
                    {
                        if (renderers[i] != null && renderers[i].enabled && renderers[i].sharedMesh != null)
                        {
                            visibleSole = Mathf.Min(visibleSole, renderers[i].bounds.min.y);
                            visibleTop = Mathf.Max(visibleTop, renderers[i].bounds.max.y);
                        }
                    }

                    if (controller != null && !float.IsInfinity(visibleSole))
                    {
                        var clearance = visibleSole - controller.bounds.min.y;
                        Debug.Log($"[Space & Crafts] Splat rendered bounds: action={splatAnimator?.CurrentAction}, landingImpactSpeed={(motor != null ? motor.LastLandingImpactSpeed : 0f):F2}, landingImpactStrength={(splatAnimator != null ? splatAnimator.LandingImpactStrengthForDiagnostics : 0f):F2}, grounded={motor != null && motor.IsGrounded}, verticalSpeed={(motor != null ? motor.VerticalVelocity : 0f):F2}, controllerBottom={controller.bounds.min.y:F4}, skinnedBoundsBottom={visibleSole:F4}, clearance={clearance:F4}m, skinnedHeight={visibleTop - visibleSole:F3}m, legRoots=({splatAnimator?.BoundLeftLegLocalPosition.ToString("F3")},{splatAnimator?.BoundRightLegLocalPosition.ToString("F3")}), soleContact={(contactRepair != null ? contactRepair.SoleContactDiagnostics : "missing repair")}.");
                        if (splatAnimator != null && (splatAnimator.CurrentAction == SplatSkeletonAnimator.Action.Land
                            || splatAnimator.CurrentAction == SplatSkeletonAnimator.Action.Idle))
                        {
                            var hips = FindNamedTransform(visual, "Bone_Hips");
                            var leftLeg = FindNamedTransform(visual, "Bone_LegL");
                            var rightLeg = FindNamedTransform(visual, "Bone_LegR");
                            Debug.Log($"[Space & Crafts] Splat touchdown pose roots: action={splatAnimator.CurrentAction}, visualLocal={(visual != null ? visual.localPosition.ToString("F3") : "missing")}, visualWorld={(visual != null ? visual.position.ToString("F3") : "missing")}, hipsParent={(hips != null && hips.parent != null ? hips.parent.name : "missing")}, hipsLocal={(hips != null ? hips.localPosition.ToString("F3") : "missing")}, hipsRest={splatAnimator.HipsRestLocalPositionForDiagnostics.ToString("F3")}, leftParent={(leftLeg != null && leftLeg.parent != null ? leftLeg.parent.name : "missing")}, leftLocal={(leftLeg != null ? leftLeg.localPosition.ToString("F3") : "missing")}, leftEuler={(leftLeg != null ? leftLeg.localEulerAngles.ToString("F1") : "missing")}, rightParent={(rightLeg != null && rightLeg.parent != null ? rightLeg.parent.name : "missing")}, rightLocal={(rightLeg != null ? rightLeg.localPosition.ToString("F3") : "missing")}, rightEuler={(rightLeg != null ? rightLeg.localEulerAngles.ToString("F1") : "missing")}.");
                        }
                        SampleBakedSkinBottom(renderers, out var bakedUnscaledBottom, out var bakedTransformPointBottom);
                        Debug.Log($"[Space & Crafts] Splat baked contact vertices: rendererBoundsBottom={visibleSole:F4}, bakedWorldBottom(rotation+translation)={bakedUnscaledBottom:F4}, doubleTransformedBottom(diagnostic only)={bakedTransformPointBottom:F4}, rendererCount={renderers.Length}.");
                        var platformName = SessionState.GetString(PlacementPlatformKey, string.Empty);
                        var platform = string.IsNullOrEmpty(platformName) ? null : GameObject.Find(platformName);
                        var platformCollider = platform != null ? platform.GetComponent<Collider>() : null;
                        if (platformCollider != null)
                        {
                            var leftMeshContact = contactRepair != null
                                ? SampleRenderedPlatformHeight(camera, platform, contactRepair.LeftSoleWorldPointForDiagnostics)
                                : "missing repair";
                            var rightMeshContact = contactRepair != null
                                ? SampleRenderedPlatformHeight(camera, platform, contactRepair.RightSoleWorldPointForDiagnostics)
                                : "missing repair";
                            Debug.Log($"[Space & Crafts] Rendered platform mesh vs sole: left={leftMeshContact}, right={rightMeshContact}.");
                            var supportProbe = controller.bounds.center;
                            var hasLocalSupport = TryGetColliderSurfaceY(platformCollider, supportProbe, out var localSupportY);
                            var comparisonSupportY = hasLocalSupport ? localSupportY : platformCollider.bounds.max.y;
                            var supportSource = hasLocalSupport ? "raycast-at-controller-center" : "bounds-max-fallback";
                            Debug.Log($"[Space & Crafts] Traversal platform contact: platform={platform.name}, supportY={comparisonSupportY:F4}, supportSource={supportSource}, supportProbe=({supportProbe.x:F3},{supportProbe.z:F3}), boundsMaxY={platformCollider.bounds.max.y:F4}, controllerGapAtProbe={controller.bounds.min.y - comparisonSupportY:F4}m, rendererBoundsGapAtProbe={visibleSole - comparisonSupportY:F4}m, soleContact={(contactRepair != null ? contactRepair.SoleContactDiagnostics : "missing repair")}.");
                            if (splatAnimator != null && splatAnimator.CurrentAction == SplatSkeletonAnimator.Action.Run)
                            {
                                Debug.Log($"[Space & Crafts] Run leg roots: root={(motor != null ? motor.transform.position.ToString("F3") : "missing")}, left={splatAnimator.BoundLeftLegWorldPosition:F3}, right={splatAnimator.BoundRightLegWorldPosition:F3}, platformSupportAtRoot={comparisonSupportY:F3}.");
                            }
                            else if (splatAnimator != null && splatAnimator.CurrentAction == SplatSkeletonAnimator.Action.Idle)
                            {
                                Debug.Log($"[Space & Crafts] Idle foot support pivots: hips={splatAnimator.BoundHipsWorldPosition:F3}, left={splatAnimator.BoundLeftLegWorldPosition:F3}, right={splatAnimator.BoundRightLegWorldPosition:F3}, platformSupportAtRoot={comparisonSupportY:F3}.");
                            }
                        }
                    }
                }

                for (var i = 0; i < overlayCanvases.Length; i++)
                {
                    var canvas = overlayCanvases[i];
                    overlayModes[i] = canvas.renderMode;
                    overlayCameras[i] = canvas.worldCamera;
                    overlayDistances[i] = canvas.planeDistance;
                    overlayEnabled[i] = canvas.enabled;
                    if (SessionState.GetBool(HideOverlayCanvasKey, false))
                    {
                        canvas.enabled = false;
                    }
                    else if (canvas.renderMode == RenderMode.ScreenSpaceOverlay)
                    {
                        canvas.renderMode = RenderMode.ScreenSpaceCamera;
                        canvas.worldCamera = camera;
                        canvas.planeDistance = Mathf.Max(1.2f, camera.nearClipPlane + 0.1f);
                    }
                }

                Canvas.ForceUpdateCanvases();
                if (SessionState.GetString(FocusObjectKey, string.Empty) == "ART_ScrapStormSentinel"
                    && SessionState.GetBool(SentinelDefeatCaptureKey, false)
                    && SessionState.GetInt(SequenceFrameIndexKey, 0) % 20 == 0)
                {
                    var playerForCamera = GameObject.FindGameObjectWithTag("Player");
                    var gatewaysForCamera = GameObject.Find("ART_DistantMeshyGateway_0");
                    var playerViewport = playerForCamera != null
                        ? camera.WorldToViewportPoint(playerForCamera.transform.position + Vector3.up)
                        : Vector3.zero;
                    var gatewayViewport = gatewaysForCamera != null
                        ? camera.WorldToViewportPoint(gatewaysForCamera.transform.position)
                        : Vector3.zero;
                    Debug.Log($"[Space & Crafts] Victory capture render camera: frame={SessionState.GetInt(SequenceFrameIndexKey, 0)}, time={Time.time:F2}, camera={camera.name}, mainCamera={(camera == Camera.main)}, position={camera.transform.position:F2}, rotation={camera.transform.eulerAngles:F1}, fov={camera.fieldOfView:F1}, playerViewport={playerViewport:F2}, firstGatewayViewport={gatewayViewport:F2}.");
                }

                renderTexture.Create();
                camera.targetTexture = renderTexture;
                camera.aspect = (float)width / height;
                if (GraphicsSettings.currentRenderPipeline != null)
                {
                    if (SessionState.GetString(FocusObjectKey, string.Empty) == "ART_ScrapStormSentinel"
                        && SessionState.GetBool(SentinelDefeatCaptureKey, false))
                    {
                        // URP's standard request can render the camera stack using
                        // stale GameCamera framing while its live transform is in
                        // the victory shot. Use the single-camera request so the
                        // captured pixels follow the production camera transform.
                        var request = new UnityEngine.Rendering.Universal.UniversalRenderPipeline.SingleCameraRequest
                        {
                            destination = renderTexture
                        };
                        camera.ResetWorldToCameraMatrix();
                        camera.ResetProjectionMatrix();
                        RenderPipeline.SubmitRenderRequest(camera, request);
                    }
                    else
                    {
                        var request = new RenderPipeline.StandardRequest { destination = renderTexture };
                        RenderPipeline.SubmitRenderRequest(camera, request);
                    }
                }
                else
                {
                    camera.Render();
                }

                if (SessionState.GetBool(IsolateFocusObjectKey, false))
                {
                    LogIsolatedCharacterRenderState(camera);
                }

                var landingShadowMotor = Object.FindAnyObjectByType<SplatMotor>();
                var landingShadow = landingShadowMotor != null
                    ? landingShadowMotor.GetComponent<PlayerLandingShadow>()
                    : null;
                if (landingShadow != null)
                {
                    var shadowViewport = camera.WorldToViewportPoint(landingShadow.GroundPointForDiagnostics);
                    Debug.Log($"[LandingShadowCapture] visible={landingShadow.IsVisibleForDiagnostics}, surface={landingShadow.GroundSurfaceNameForDiagnostics}, playerY={landingShadowMotor.transform.position.y:F2}, shadowY={landingShadow.GroundPointForDiagnostics.y:F2}, verticalGap={landingShadow.VerticalGapForDiagnostics:F2}m, shadowPosition={landingShadow.GroundPointForDiagnostics:F2}, viewport={shadowViewport:F2}.");
                }

                RenderTexture.active = renderTexture;
                screenshot.ReadPixels(new Rect(0f, 0f, width, height), 0, 0, false);
                screenshot.Apply(false, false);
                File.WriteAllBytes(output, screenshot.EncodeToPNG());
                return File.Exists(output) && new FileInfo(output).Length > 1024;
            }
            catch (System.Exception exception)
            {
                Debug.LogException(exception);
                return false;
            }
            finally
            {
                for (var i = 0; i < overlayCanvases.Length; i++)
                {
                    var canvas = overlayCanvases[i];
                    if (canvas == null)
                    {
                        continue;
                    }

                    canvas.renderMode = overlayModes[i];
                    canvas.worldCamera = overlayCameras[i];
                    canvas.planeDistance = overlayDistances[i];
                    canvas.enabled = overlayEnabled[i];
                }

                camera.targetTexture = oldTarget;
                camera.aspect = oldAspect;
                camera.transform.SetPositionAndRotation(oldCameraPosition, oldCameraRotation);
                camera.fieldOfView = oldFieldOfView;
                RenderTexture.active = previousActive;
                Object.DestroyImmediate(screenshot);
                renderTexture.Release();
                Object.DestroyImmediate(renderTexture);
                if (ownsCaptureCamera && camera != null)
                {
                    Object.DestroyImmediate(camera.gameObject);
                }
            }
        }

        private static void SuppressNonFocusCaptureRenderers(GameObject focusObject)
        {
            // Runtime effects may spawn after the first isolation pass. Reapply
            // the capture visibility mask immediately before each image, retaining
            // the character, requested platform, and neutral review plane only.
            var platformName = SessionState.GetString(PlacementPlatformKey, string.Empty);
            var platform = string.IsNullOrEmpty(platformName) ? null : GameObject.Find(platformName);
            var renderers = Resources.FindObjectsOfTypeAll<Renderer>();
            var hidden = 0;
            for (var i = 0; i < renderers.Length; i++)
            {
                var renderer = renderers[i];
                if (renderer == null || !renderer.gameObject.scene.IsValid()) continue;
                var keep = renderer.transform == focusObject.transform
                    || renderer.transform.IsChildOf(focusObject.transform)
                    || platform != null && (renderer.transform == platform.transform
                        || renderer.transform.IsChildOf(platform.transform))
                    || renderer.gameObject.name == "CaptureOnly_NeutralGround";
                if (keep || !renderer.enabled) continue;
                renderer.enabled = false;
                hidden++;
            }
            if (hidden > 0)
                Debug.Log($"[Space & Crafts] Suppressed {hidden} newly spawned non-focus renderers in isolated capture.");
        }

        private static void SampleAuthoredClipForCapture()
        {
            var action = SessionState.GetString(AuthoredClipActionKey, string.Empty);
            if (string.IsNullOrEmpty(action)) return;
            if (action != null && action.StartsWith("MotorState_NameRetargeted", System.StringComparison.Ordinal))
            {
                SampleMotorDrivenRetargetedClipForCapture();
                return;
            }

            var nameRetargeted = action.EndsWith("_NameRetargeted", System.StringComparison.Ordinal);
            var combinedRigClip = action.EndsWith("_Combined", System.StringComparison.Ordinal);
            var actionName = combinedRigClip ? action.Substring(0, action.Length - "_Combined".Length)
                : nameRetargeted ? action.Substring(0, action.Length - "_NameRetargeted".Length) : action;
            var sourceVersion = actionName.EndsWith("_Iter1161", System.StringComparison.Ordinal) ? "Iter1161"
                : actionName.EndsWith("_Iter1160", System.StringComparison.Ordinal) ? "Iter1160"
                : actionName.EndsWith("_Iter1117", System.StringComparison.Ordinal) ? "Iter1117"
                : actionName.EndsWith("_Iter1116", System.StringComparison.Ordinal) ? "Iter1116"
                : actionName.EndsWith("_Iter1115", System.StringComparison.Ordinal) ? "Iter1115"
                : actionName.EndsWith("_Iter850", System.StringComparison.Ordinal) ? "Iter850"
                : actionName.EndsWith("_Iter849", System.StringComparison.Ordinal) ? "Iter849"
                : actionName.EndsWith("_Iter688", System.StringComparison.Ordinal) ? "Iter688" : "Iter588";
            var versionSuffix = "_" + sourceVersion;
            var clipAction = actionName.EndsWith(versionSuffix, System.StringComparison.Ordinal)
                ? actionName.Substring(0, actionName.Length - versionSuffix.Length) : actionName;
            var assetPath = nameRetargeted
                ? "Assets/SpaceAndCrafts/Resources/Characters/Splat_AnimationActions_Iter911.fbx"
                : combinedRigClip
                ? "Assets/SpaceAndCrafts/Resources/Characters/Splat_AnimationActions_Iter911.fbx"
                : $"Assets/SpaceAndCrafts/Art/Animations/Authoring/{sourceVersion}/Splat_{clipAction}_{sourceVersion}.fbx";
            AnimationClip clip = null;
            foreach (var asset in AssetDatabase.LoadAllAssetsAtPath(assetPath))
            {
                if (!(asset is AnimationClip candidate) || candidate.name.StartsWith("__preview__")) continue;
                var isMatch = combinedRigClip || nameRetargeted
                    ? candidate.name.Contains("|Splat_" + clipAction + "_")
                    : sourceVersion == "Iter1115" || sourceVersion == "Iter1116" || sourceVersion == "Iter1117"
                        || sourceVersion == "Iter1160" || sourceVersion == "Iter1161"
                        ? candidate.name == "Scene" || candidate.name.Contains("Splat_" + clipAction + "_" + sourceVersion)
                        : candidate.name == "Scene";
                if (isMatch)
                {
                    clip = candidate;
                    break;
                }
            }

            var hero = GameObject.Find("Splat_TEMP");
            var visual = hero != null ? hero.transform.Find(OrganicSplatBuilder.VisualRootName) : null;
            var rig = visual != null ? FindNamedTransform(visual, "Splat_SkinRig") : null;
            if (clip == null || rig == null)
            {
                Debug.LogWarning($"[Splat authored preview] Could not apply {clipAction} ({sourceVersion}): clip={(clip != null)}, rig={(rig != null)}, asset={assetPath}.");
                return;
            }

            var proceduralAnimator = hero.GetComponent<SplatSkeletonAnimator>();
            if (proceduralAnimator != null) proceduralAnimator.enabled = false;
            var frameIndex = SessionState.GetInt(SequenceFrameIndexKey, 0);
            var sequenceCount = Mathf.Max(2, SessionState.GetInt(SequenceFrameCountKey, 8));
            var sampleTime = clip.length * (frameIndex / (float)sequenceCount);
            var activeRigClip = sourceVersion == "Iter1160" || sourceVersion == "Iter1161";
            if ((nameRetargeted || activeRigClip)
                && (clipAction == "Idle" || clipAction == "Land" || clipAction == "Run" || activeRigClip)
                && frameIndex == 0)
                StageRetargetedGroundContactCapture(hero, proceduralAnimator,
                    clipAction == "Land" ? SplatSkeletonAnimator.Action.Land : SplatSkeletonAnimator.Action.Idle);
            // The combined FBX clip preserves source paths; the name-retarget path
            // samples that source rig, then transfers local rotation deltas by bone name.
            // The split preview clips use paths relative to Splat_SkinRig.
            // These clips key translation/scale throughout the source rig. The
            // runtime physics root and candidate's bind proportions must stay fixed;
            // use the clip's rotation curves for an in-place pose preview.
            var posePrefix = AuthoredPreviewRootPoseKey + actionName + ".";
            if (frameIndex == 0)
            {
                StorePreviewHierarchyPose(posePrefix, hero.transform);
            }
            if (nameRetargeted)
                SampleClipRetargetedByBoneName(clip, sampleTime, rig);
            else
                clip.SampleAnimation(combinedRigClip ? hero : rig.gameObject, sampleTime);
            RestorePreviewHierarchyPose(posePrefix, hero.transform);

            var repair = hero.GetComponent<SplatVisualRepair>();
            var groundedContactSamples = (nameRetargeted || activeRigClip)
                && (clipAction == "Idle" || clipAction == "Land" || clipAction == "Run") ? 4 : 1;
            // The preview restores the same saved hierarchy before every sample,
            // which also resets the runtime landing correction. Reapply the
            // capture-only grounded correction until its small per-frame step
            // converges, so each still shows the intended seated pose.
            for (var contactSample = 0; contactSample < groundedContactSamples; contactSample++)
                repair?.AlignGroundedSolesAfterPose();
            var leftLeg = FindNamedTransform(rig, "Bone_LegL");
            var rightLeg = FindNamedTransform(rig, "Bone_LegR");
            var minimumY = float.PositiveInfinity;
            foreach (var renderer in visual.GetComponentsInChildren<Renderer>(true))
            {
                if (renderer != null && renderer.enabled && renderer.gameObject.activeInHierarchy)
                    minimumY = Mathf.Min(minimumY, renderer.bounds.min.y);
            }
            var padTop = float.NaN;
            var pad = GameObject.Find(SessionState.GetString(PlacementPlatformKey, string.Empty));
            if (pad != null)
            {
                foreach (var collider in pad.GetComponentsInChildren<Collider>(true))
                    if (collider != null && collider.enabled) padTop = float.IsNaN(padTop)
                        ? collider.bounds.max.y : Mathf.Max(padTop, collider.bounds.max.y);
            }

            Debug.Log($"[Splat authored preview] action={clipAction}, source={(nameRetargeted ? "Iter911 name-retargeted" : combinedRigClip ? "Iter911 combined" : sourceVersion)}, clip={clip.name}, sample={sampleTime:F3}/{clip.length:F3}s, rigRoot={rig.name}, armL={(FindNamedTransform(rig, "Bone_ArmL") != null ? FindNamedTransform(rig, "Bone_ArmL").localRotation.eulerAngles.ToString("F1") : "missing")}, armR={(FindNamedTransform(rig, "Bone_ArmR") != null ? FindNamedTransform(rig, "Bone_ArmR").localRotation.eulerAngles.ToString("F1") : "missing")}, legL={(leftLeg != null ? leftLeg.localRotation.eulerAngles.ToString("F1") : "missing")}, legR={(rightLeg != null ? rightLeg.localRotation.eulerAngles.ToString("F1") : "missing")}, visualBottom={minimumY:F3}m, padTop={padTop:F3}m, bottomGap={minimumY - padTop:F3}m, soleCorrection={repair?.SoleContactDiagnostics ?? "missing repair"}.");
        }

        private static void SampleMotorDrivenRetargetedClipForCapture()
        {
            const string clipAssetPath = "Assets/SpaceAndCrafts/Resources/Characters/Splat_AnimationActions_Iter911.fbx";
            var hero = GameObject.Find("Splat_TEMP");
            var motor = hero != null ? hero.GetComponent<SplatMotor>() : null;
            var animator = hero != null ? hero.GetComponent<SplatSkeletonAnimator>() : null;
            var visual = hero != null ? hero.transform.Find(OrganicSplatBuilder.VisualRootName) : null;
            var rig = visual != null ? FindNamedTransform(visual, "Splat_SkinRig") : null;
            if (hero == null || motor == null || animator == null || rig == null)
            {
                Debug.LogWarning($"[Splat motor retarget preview] Missing binding: hero={hero != null}, motor={motor != null}, animator={animator != null}, rig={rig != null}.");
                return;
            }

            if (animator.enabled) animator.enabled = false;
            var grounded = motor.IsGrounded;
            if (!MotorRetargetStateInitialized)
            {
                MotorRetargetWasGrounded = grounded;
                MotorRetargetJumpStartedAt = Time.time;
                MotorRetargetLandStartedAt = -1f;
                MotorRetargetStateInitialized = true;
            }
            else if (MotorRetargetWasGrounded && !grounded)
            {
                MotorRetargetJumpStartedAt = Time.time;
                MotorRetargetLandStartedAt = -1f;
            }
            else if (!MotorRetargetWasGrounded && grounded)
            {
                MotorRetargetLandStartedAt = Time.time;
            }
            MotorRetargetWasGrounded = grounded;

            string state;
            if (!grounded) state = "Jump";
            else if (MotorRetargetLandStartedAt >= 0f && Time.time - MotorRetargetLandStartedAt < 0.37f) state = "Land";
            else if (motor.PlanarVelocity.magnitude >= 0.55f) state = "Run";
            else state = "Idle";

            AnimationClip clip = null;
            var clips = AssetDatabase.LoadAllAssetsAtPath(clipAssetPath);
            for (var i = 0; i < clips.Length; i++)
            {
                if (clips[i] is AnimationClip candidate && !candidate.name.StartsWith("__preview__")
                    && candidate.name.Contains("|Splat_" + state + "_"))
                {
                    clip = candidate;
                    break;
                }
            }
            if (clip == null)
            {
                Debug.LogWarning($"[Splat motor retarget preview] No Iter911 {state} clip found in {clipAssetPath}.");
                return;
            }

            var stateChanged = state != MotorRetargetState;
            if (stateChanged)
            {
                MotorRetargetBlendFrom.Clear();
                var targetBones = rig.GetComponentsInChildren<Transform>(true);
                for (var i = 0; i < targetBones.Length; i++)
                {
                    var bone = targetBones[i];
                    if (bone != null && bone.name.StartsWith("Bone_", System.StringComparison.Ordinal))
                        MotorRetargetBlendFrom[bone.name] = bone.localRotation;
                }
                MotorRetargetState = state;
                MotorRetargetStateStartedAt = Time.time;
                var actionMap = state switch
                {
                    "Jump" => SplatSkeletonAnimator.Action.Jump,
                    "Land" => SplatSkeletonAnimator.Action.Land,
                    "Run" => SplatSkeletonAnimator.Action.Run,
                    _ => SplatSkeletonAnimator.Action.Idle
                };
                animator.PlayAction(actionMap, clip.length);
            }

            var elapsed = Mathf.Max(0f, Time.time - MotorRetargetStateStartedAt);
            var sampleTime = state switch
            {
                "Run" or "Idle" => Mathf.Repeat(elapsed, clip.length),
                "Land" => Mathf.Clamp(elapsed, 0f, clip.length),
                _ => Mathf.Clamp01(elapsed / 0.75f) * clip.length
            };
            SampleClipRetargetedByBoneName(clip, sampleTime, rig);
            var blend = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(elapsed / 0.12f));
            if (blend < 1f)
            {
                var targetBones = rig.GetComponentsInChildren<Transform>(true);
                for (var i = 0; i < targetBones.Length; i++)
                {
                    var bone = targetBones[i];
                    if (bone != null && MotorRetargetBlendFrom.TryGetValue(bone.name, out var from))
                        bone.localRotation = Quaternion.Slerp(from, bone.localRotation, blend);
                }
            }

            var uncorrectedContact = SessionState.GetString(AuthoredClipActionKey, string.Empty)
                .EndsWith("_Uncorrected", System.StringComparison.Ordinal);
            if (!uncorrectedContact)
                hero.GetComponent<SplatVisualRepair>()?.AlignGroundedSolesAfterPose();
            var contactRepair = hero.GetComponent<SplatVisualRepair>();
            var contactSummary = uncorrectedContact
                ? "not refreshed (uncorrected capture)"
                : contactRepair?.SoleContactDiagnostics ?? "missing repair";
            Debug.Log($"[Splat motor retarget preview] state={state}, grounded={grounded}, speed={motor.PlanarVelocity.magnitude:F2}m/s, sample={sampleTime:F3}/{clip.length:F3}s, transitionBlend={blend:F2}, root={hero.transform.position:F3}, leftLeg={(FindNamedTransform(rig, "Bone_LegL") != null ? FindNamedTransform(rig, "Bone_LegL").localRotation.eulerAngles.ToString("F1") : "missing")}, rightLeg={(FindNamedTransform(rig, "Bone_LegR") != null ? FindNamedTransform(rig, "Bone_LegR").localRotation.eulerAngles.ToString("F1") : "missing")}, soleCorrection={(uncorrectedContact ? "disabled for evaluation" : "grounded post-pose")}, soleContact={contactSummary}.");
        }

        private static void SampleClipRetargetedByBoneName(AnimationClip clip, float sampleTime, Transform targetRig)
        {
            const string sourcePath = "Assets/SpaceAndCrafts/Resources/Characters/Splat_AnimationActions_Iter911.fbx";
            const string targetPath = "Assets/SpaceAndCrafts/Resources/Characters/Splat_Rigged_Candidate_Iter378.fbx";
            var sourceAsset = AssetDatabase.LoadAssetAtPath<GameObject>(sourcePath);
            var targetAsset = AssetDatabase.LoadAssetAtPath<GameObject>(targetPath);
            if (sourceAsset == null || targetAsset == null || clip == null || targetRig == null)
            {
                Debug.LogWarning($"[Splat authored preview] Name retarget skipped: source={(sourceAsset != null)}, target={(targetAsset != null)}, clip={(clip != null)}, liveRig={(targetRig != null)}.");
                return;
            }

            var sourceRest = BuildUniqueTransformMap(sourceAsset.transform);
            var targetRest = BuildUniqueTransformMap(targetAsset.transform);
            var liveTarget = BuildUniqueTransformMap(targetRig);
            var sourcePose = Object.Instantiate(sourceAsset);
            sourcePose.name = "CaptureOnly_SplatRetargetSource";
            sourcePose.hideFlags = HideFlags.HideAndDontSave;
            foreach (var renderer in sourcePose.GetComponentsInChildren<Renderer>(true)) renderer.enabled = false;
            foreach (var collider in sourcePose.GetComponentsInChildren<Collider>(true)) collider.enabled = false;
            try
            {
                clip.SampleAnimation(sourcePose, sampleTime);
                var sampled = BuildUniqueTransformMap(sourcePose.transform);
                var copied = 0;
                var missing = 0;
                var missingNames = new System.Collections.Generic.List<string>();
                foreach (var pair in liveTarget)
                {
                    var boneName = pair.Key;
                    if (!boneName.StartsWith("Bone_", System.StringComparison.Ordinal)) continue;
                    if (!sampled.TryGetValue(boneName, out var sourceBone)
                        || !sourceRest.TryGetValue(boneName, out var sourceBind)
                        || !targetRest.TryGetValue(boneName, out var targetBind))
                    {
                        missing++;
                        missingNames.Add(boneName);
                        continue;
                    }

                    // Transfer motion relative to each rig's own bind pose. This
                    // preserves the target arm rest offset instead of copying the
                    // source arm's absolute local rotation onto it.
                    var sourceDelta = Quaternion.Inverse(sourceBind.localRotation) * sourceBone.localRotation;
                    pair.Value.localRotation = targetBind.localRotation * sourceDelta;
                    copied++;
                }

                Debug.Log($"[Splat authored preview] name-retarget sample={sampleTime:F3}/{clip.length:F3}s, copiedBones={copied}, missingOrAmbiguousBones={missing}, skippedBones={string.Join(",", missingNames)}, armRestDelta={Quaternion.Angle(sourceRest["Bone_ArmL"].localRotation, targetRest["Bone_ArmL"].localRotation):F2}deg.");
            }
            finally
            {
                Object.DestroyImmediate(sourcePose);
            }
        }

        private static void StageRetargetedGroundContactCapture(GameObject hero, SplatSkeletonAnimator animator,
            SplatSkeletonAnimator.Action stagedAction)
        {
            var platformName = SessionState.GetString(PlacementPlatformKey, string.Empty);
            if (hero == null || string.IsNullOrEmpty(platformName)) return;

            // The regular showcase scene can fire gameplay triggers before its
            // camera settles. Re-place the actor after those scene systems have
            // initialized, then freeze only this Play Mode capture actor so the
            // sampled Idle clip can be evaluated against a stable support plane.
            PlaceSplatOnPlatform(platformName);
            var respawn = hero.GetComponent<PlayerRespawn>();
            if (respawn != null) respawn.enabled = false;
            var motor = hero.GetComponent<SplatMotor>();
            if (motor != null)
            {
                motor.HardResetState();
                var groundedBackingField = typeof(SplatMotor).GetField("<IsGrounded>k__BackingField",
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                groundedBackingField?.SetValue(motor, true);
                motor.enabled = false;
            }

            if (animator != null)
            {
                animator.PlayAction(stagedAction, 30f);
                animator.enabled = false;
            }

            Physics.SyncTransforms();
            var controller = hero.GetComponent<CharacterController>();
            Debug.Log($"[Splat authored preview] froze capture-only {stagedAction} stage: rootY={hero.transform.position.y:F3}, capsuleBottom={(controller != null ? controller.bounds.min.y.ToString("F3") : "missing")}, grounded={(motor != null && motor.IsGrounded)}, motorDisabled={(motor != null && !motor.enabled)}, respawnDisabled={(respawn != null && !respawn.enabled)}.");
        }

        private static System.Collections.Generic.Dictionary<string, Transform> BuildUniqueTransformMap(Transform root)
        {
            var grouped = new System.Collections.Generic.Dictionary<string, System.Collections.Generic.List<Transform>>();
            foreach (var transform in root.GetComponentsInChildren<Transform>(true))
            {
                if (!grouped.TryGetValue(transform.name, out var matches))
                    grouped.Add(transform.name, matches = new System.Collections.Generic.List<Transform>());
                matches.Add(transform);
            }

            var unique = new System.Collections.Generic.Dictionary<string, Transform>();
            foreach (var pair in grouped)
                if (pair.Value.Count == 1) unique.Add(pair.Key, pair.Value[0]);
            return unique;
        }

        private static Transform FindNamedTransform(Transform root, string name)
        {
            var all = root.GetComponentsInChildren<Transform>(true);
            for (var i = 0; i < all.Length; i++)
            {
                if (all[i].name == name)
                {
                    return all[i];
                }
            }
            return null;
        }

        private static string SummarizeBoneInfluence(SkinnedMeshRenderer[] skins, Transform bone)
        {
            if (bone == null) return "bone missing";
            var summaries = new List<string>();
            for (var skinIndex = 0; skinIndex < skins.Length; skinIndex++)
            {
                var skin = skins[skinIndex];
                if (skin == null || skin.sharedMesh == null || skin.bones == null) continue;
                var boneIndex = System.Array.IndexOf(skin.bones, bone);
                if (boneIndex < 0) continue;
                var mesh = skin.sharedMesh;
                if (!mesh.isReadable)
                {
                    summaries.Add($"{skin.name}: mesh not readable");
                    continue;
                }

                try
                {
                    using (var bonesPerVertex = mesh.GetBonesPerVertex())
                    using (var allWeights = mesh.GetAllBoneWeights())
                    {
                        var offset = 0;
                        var influencedVertices = 0;
                        var totalWeight = 0f;
                        var maxWeight = 0f;
                        for (var vertexIndex = 0; vertexIndex < bonesPerVertex.Length; vertexIndex++)
                        {
                            var vertexInfluence = false;
                            var influenceCount = bonesPerVertex[vertexIndex];
                            for (var influenceIndex = 0; influenceIndex < influenceCount; influenceIndex++)
                            {
                                var weight = allWeights[offset + influenceIndex];
                                if (weight.boneIndex == boneIndex && weight.weight > 0.0001f)
                                {
                                    vertexInfluence = true;
                                    totalWeight += weight.weight;
                                    maxWeight = Mathf.Max(maxWeight, weight.weight);
                                }
                            }
                            if (vertexInfluence) influencedVertices++;
                            offset += influenceCount;
                        }
                        summaries.Add($"{skin.name}: vertices={influencedVertices}/{mesh.vertexCount}, sum={totalWeight:F1}, max={maxWeight:F2}");
                    }
                }
                catch (System.Exception exception)
                {
                    summaries.Add($"{skin.name}: weight read failed ({exception.GetType().Name})");
                }
            }

            return summaries.Count > 0 ? string.Join(" | ", summaries.ToArray()) : "no skinned renderer contains this bone";
        }

        private static void StorePreviewTransform(string key, Transform transform)
        {
            SessionState.SetFloat(key + ".px", transform.localPosition.x);
            SessionState.SetFloat(key + ".py", transform.localPosition.y);
            SessionState.SetFloat(key + ".pz", transform.localPosition.z);
            SessionState.SetFloat(key + ".sx", transform.localScale.x);
            SessionState.SetFloat(key + ".sy", transform.localScale.y);
            SessionState.SetFloat(key + ".sz", transform.localScale.z);
        }

        private static void RestorePreviewTransform(string key, Transform transform)
        {
            transform.localPosition = new Vector3(
                SessionState.GetFloat(key + ".px", transform.localPosition.x),
                SessionState.GetFloat(key + ".py", transform.localPosition.y),
                SessionState.GetFloat(key + ".pz", transform.localPosition.z));
            transform.localScale = new Vector3(
                SessionState.GetFloat(key + ".sx", transform.localScale.x),
                SessionState.GetFloat(key + ".sy", transform.localScale.y),
                SessionState.GetFloat(key + ".sz", transform.localScale.z));
        }

        private static void StorePreviewHierarchyPose(string key, Transform root)
        {
            var transforms = root.GetComponentsInChildren<Transform>(true);
            SessionState.SetInt(key + ".count", transforms.Length);
            for (var i = 0; i < transforms.Length; i++)
                StorePreviewTransform(key + "." + i, transforms[i]);
        }

        private static void RestorePreviewHierarchyPose(string key, Transform root)
        {
            var transforms = root.GetComponentsInChildren<Transform>(true);
            var savedCount = SessionState.GetInt(key + ".count", 0);
            if (savedCount != transforms.Length)
            {
                Debug.LogWarning($"[Splat authored preview] Could not restore bind positions/scales: saved transforms={savedCount}, current={transforms.Length}.");
                return;
            }

            for (var i = 0; i < transforms.Length; i++)
                RestorePreviewTransform(key + "." + i, transforms[i]);
        }

        private static void LogIsolatedCharacterRenderState(Camera camera)
        {
            var hero = GameObject.Find("Splat_TEMP");
            if (camera == null || hero == null) return;
            var skins = hero.GetComponentsInChildren<SkinnedMeshRenderer>(true);
            for (var i = 0; i < skins.Length; i++)
            {
                var skin = skins[i];
                if (skin == null) continue;
                var bounds = skin.bounds;
                var viewport = camera.WorldToViewportPoint(bounds.center);
                var layerIncluded = (camera.cullingMask & (1 << skin.gameObject.layer)) != 0;
                Debug.Log($"[Space & Crafts] Isolated character draw state: renderer={skin.name}, enabled={skin.enabled}, active={skin.gameObject.activeInHierarchy}, visible={skin.isVisible}, forceOff={skin.forceRenderingOff}, layer={skin.gameObject.layer}, cameraMaskIncludesLayer={layerIncluded}, boundsCenter={bounds.center:F3}, boundsSize={bounds.size:F3}, viewportCenter={viewport:F3}, rootBone={skin.rootBone?.position.ToString("F3") ?? "missing"}.");
            }
        }

        private static string SampleRenderedPlatformHeight(Camera camera, GameObject platform, Vector3 solePoint)
        {
            if (platform == null || solePoint == Vector3.zero) return "sole point unavailable";
            if (_diagnosticPadProbeCollider == null)
            {
                var filters = platform.GetComponentsInChildren<MeshFilter>(true);
                MeshFilter chosen = null;
                for (var i = 0; i < filters.Length; i++)
                {
                    var filter = filters[i];
                    if (filter == null || filter.sharedMesh == null) continue;
                    if (filter.name.IndexOf("disc", System.StringComparison.OrdinalIgnoreCase) >= 0)
                    {
                        chosen = filter;
                        break;
                    }
                    if (chosen == null) chosen = filter;
                }

                if (chosen == null) return "platform mesh missing";
                _diagnosticPadProbeObject = new GameObject("DIAGNOSTIC_RenderedPlatformSurfaceProbe");
                _diagnosticPadProbeObject.layer = DiagnosticMeshProbeLayer;
                _diagnosticPadProbeObject.transform.SetPositionAndRotation(
                    chosen.transform.position, chosen.transform.rotation);
                _diagnosticPadProbeObject.transform.localScale = chosen.transform.lossyScale;
                _diagnosticPadProbeCollider = _diagnosticPadProbeObject.AddComponent<MeshCollider>();
                _diagnosticPadProbeCollider.sharedMesh = chosen.sharedMesh;
                Physics.SyncTransforms();
            }

            if (_diagnosticPadProbeCollider == null || !_diagnosticPadProbeCollider.enabled)
                return "diagnostic mesh collider unavailable";
            var ray = new Ray(solePoint + Vector3.up * 0.5f, Vector3.down);
            if (!_diagnosticPadProbeCollider.Raycast(ray, out var hit, 1f))
                return $"sole={solePoint:F3}, rendered mesh miss";
            var soleScreen = camera != null ? camera.WorldToScreenPoint(solePoint) : Vector3.zero;
            var meshScreen = camera != null ? camera.WorldToScreenPoint(hit.point) : Vector3.zero;
            var screenDelta = camera != null ? (soleScreen - meshScreen).magnitude : 0f;
            return $"sole={solePoint:F3}, mesh={hit.point:F3}, deltaY={(solePoint.y - hit.point.y):F4}m, "
                + $"screenSole={soleScreen:F1}, screenMesh={meshScreen:F1}, screenDelta={screenDelta:F2}px";
        }

        private static bool TryGetColliderSurfaceY(Collider collider, Vector3 worldProbe, out float surfaceY)
        {
            surfaceY = 0f;
            if (collider == null || !collider.enabled || !collider.gameObject.activeInHierarchy)
                return false;

            var bounds = collider.bounds;
            var origin = new Vector3(worldProbe.x, bounds.max.y + 0.05f, worldProbe.z);
            var ray = new Ray(origin, Vector3.down);
            var distance = Mathf.Max(0.1f, bounds.size.y + 0.1f);
            if (!collider.Raycast(ray, out var hit, distance))
                return false;

            surfaceY = hit.point.y;
            return true;
        }
    }
}
